var e=[{unitId:`prep1_t1_u1`,grade:`prep_1`,gradeNumber:7,term:1,unitNumber:1,unitTitleEn:`My Family and Me`,unitTitleAr:`عائلتي وأنا (العمل التطوعي والهوايات)`,theme:`Family relations, voluntary work, musical instruments, chess, orphanages`,tab1_Vocabulary:{words:[{id:`p1_u1_w1`,word:`Voluntary work`,phonetics:`/ˈvɒl.ən.tər.i wɜːk/`,arabicMeaning:`عمل تطوعي (بدون مقابل مادي)`,partOfSpeech:`phrase`,exampleSentence:`Doing voluntary work at the children hospital makes me feel proud.`,visualCue:`volunteers_team`},{id:`p1_u1_w2`,word:`Orphan`,phonetics:`/ˈɔː.fən/`,arabicMeaning:`يتيم (فقد والديه)`,partOfSpeech:`noun`,exampleSentence:`Heidi was an orphan girl who lived with her grandfather in the Alps.`,visualCue:`kind_smile`},{id:`p1_u1_w3`,word:`Twin`,phonetics:`/twɪn/`,arabicMeaning:`توأم`,partOfSpeech:`noun`,exampleSentence:`Hany and Hazem are twins; they have the same age and look alike.`,visualCue:`friends_group`},{id:`p1_u1_w4`,word:`Drums`,phonetics:`/drʌmz/`,arabicMeaning:`طبول (آلة موسيقية إيقاعية)`,partOfSpeech:`noun`,exampleSentence:`My brother loves playing the drums in the school band.`,visualCue:`music_singing`}],collocations:[{phrase:`do voluntary work`,meaningAr:`يقوم بعمل تطوعي`,example:`We do voluntary work to assist children.`},{phrase:`play chess`,meaningAr:`يلعب شطرنج`,example:`Grandfather teaches me how to play chess.`}],conversationTerms:[{en:`What musical instruments do you play?`,ar:`ما الآلات الموسيقية التي تعزف عليها؟`},{en:`Voluntary work is work you do for no money.`,ar:`العمل التطوعي هو عمل تقوم به دون مقابل مادي.`},{en:`Both of my brothers are keen on sports.`,ar:`كلا شقيقيّ شغوفان بالرياضة.`}]},tab2_Grammar:{rules:[{title:`Possessive Adjectives vs. Possessive Pronouns`,ruleExplanationAr:`صفات الملكية (my, your, his, her, our, their) يتبعها اسم، بينما ضمائر الملكية (mine, yours, his, hers, ours, theirs) تأتي بمفردها دون اسم.`,structureFormula:`Possessive Adj + Noun | Possessive Pronoun (No Noun)`,examples:[{en:`This is my bag, and that bag is yours.`,ar:`هذه حقيبتي وتلك الحقيبة حقيبتك.`},{en:`Whose pen is this? It is mine.`,ar:`لمن هذا القلم؟ إنه لي.`}],visualPatternBlocks:[`Possessive Adj (my/your/his) + Noun`,`Possessive Pronoun (mine/yours/his)`]}],sentenceBuilderDrills:[{jumbledParts:[`bag`,`This`,`is`,`mine`,`not`,`yours`],correctOrder:[`This`,`bag`,`is`,`mine`,`not`,`yours`],translationAr:`هذه الحقيبة تخصني وليست لك`}],errorCorrectionDrills:[{sentence:`This book belongs to me. It is (my).`,wrongWord:`my`,correctWord:`mine`,explanationAr:`في نهاية الجملة بدون اسم نستخدم ضمير الملكية mine وليس صفة الملكية my.`}]},tab3_Skills:{dialogue:{title:`Complete the dialogue between Omar and Hazem:`,context:`Omar is telling Hazem about his hobbies and family voluntary work.`,turns:[{speaker:`Hazem`,text:`Hello Omar! What are your favourite hobbies?`,isBlank:!1},{speaker:`Omar`,isBlank:!0,blankNumber:1,expectedAnswer:`I like playing drums and doing voluntary work.`,hintAr:`اذكر هوايتك المفضلة`},{speaker:`Hazem`,text:`Where do you do voluntary work?`,isBlank:!1},{speaker:`Omar`,isBlank:!0,blankNumber:2,expectedAnswer:`At the children hospital.`,hintAr:`حدد المكان (مستشفى الأطفال)`}]},readingPassage:{title:`Heidi: The Story of an Orphan Girl`,text:`Heidi is an orphan girl who goes to live with her grandfather in the Swiss mountains. Her grandfather lives in a small wooden house with his goats. Heidi loves nature, fresh air, and watching the birds. Later, she travels to the city of Frankfurt to help Clara, a disabled girl in a wheelchair. Heidi teaches Clara courage and kindness.`,translationAr:`قصة هايدي الفتاة اليتيمة التي عاشت مع جدها في جبال سويسرا.`},writingPrompt:{title:`A Paragraph on Voluntary Work (العمل التطوعي)`,prompt:`Write a paragraph of about 80 words about why Egyptian teenagers should do voluntary work in their community.`,targetWordsCount:80,rubric:[`Relevance to topic`,`Grammar and tense accuracy`,`Appropriate lexical range`,`Correct punctuation`],modelAnswer:`Voluntary work is of paramount importance to our community. When teenagers volunteer in hospitals, orphanages, or public gardens, they learn cooperation and empathy. It teaches us responsibility and builds our character. We do not receive money, but we receive happiness and gratitude from those we help.`}},examSuite:{level1_Foundation:[{id:`prep1_u1_l1_q1`,type:`mcq`,questionPrompt:`A child who has no mother or father is an ______.`,options:[`orphan`,`engineer`,`athlete`,`musician`],correctAnswer:`orphan`,explanationAr:`الطفل الذي فقد والديه يُدعى يتيماً (orphan).`,marks:1,subSkill:`Vocabulary`},{id:`prep1_u1_l1_q2`,type:`mcq`,questionPrompt:`Voluntary work is work that you do ______ money.`,options:[`without`,`for lots of`,`for earning`,`with high`],correctAnswer:`without`,explanationAr:`العمل التطوعي يُؤدى بدون مقابل مالي (without money).`,marks:1,subSkill:`Vocabulary`}],level2_Contextual:[{id:`prep1_u1_l2_q1`,type:`fill_in_the_blank`,questionPrompt:`Whose racket is this? — It belongs to Mona. It is ______.`,options:[`hers`,`her`,`she`,`him`],correctAnswer:`hers`,explanationAr:`نستخدم ضمير الملكية hers ليعود على اسم منى المؤنث دون أن يتبعه اسم.`,marks:1,subSkill:`Grammar`}],level3_AdvancedStructure:[{id:`prep1_u1_l3_q1`,type:`error_correction`,questionPrompt:`Correct the word between brackets: "That camera is (my); I bought it yesterday."`,correctAnswer:`mine`,explanationAr:`التصحيح mine لأنها تأتي بعد فعل to be منفردة كضمير ملكية.`,marks:2,subSkill:`Grammar`}],level4_MoeMockExam:[{id:`prep1_u1_l4_q1`,type:`mcq`,questionPrompt:`Practice MOE Mock: Hany and Ali have the same parents and birthday. They are ______.`,options:[`twins`,`strangers`,`cousins`,`grandparents`],correctAnswer:`twins`,explanationAr:`الأخوان المولودان في نفس اليوم لنفس الأبوين هما توأم (twins).`,marks:2,subSkill:`Vocabulary`}],level5_HigherThinking:[{id:`prep1_u1_l5_q1`,type:`guided_writing`,questionPrompt:`Reflect on Heidi's attitude toward nature in two analytical sentences:`,correctAnswer:`Heidi found peace and resilience in the mountains because nature taught her simplicity and gratitude. Her connection with animals and open spaces helped her heal from loneliness.`,explanationAr:`تحليل نقدي لشخصية هايدي وعلاقتها بالطبيعة الإنسانية والبيئية.`,marks:3,subSkill:`Writing`}]}},{unitId:`prep2_t1_u1`,grade:`prep_2`,gradeNumber:8,term:1,unitNumber:1,unitTitleEn:`Coming Home`,unitTitleAr:`العودة إلى المنزل (الروتين اليومي والمساعدة المنزلية)`,theme:`Daily routines, leisure activities, chores, texting friends, bakeries`,tab1_Vocabulary:{words:[{id:`p2_u1_w1`,word:`Daily routine`,phonetics:`/ˈdeɪ.li ruːˈtiːn/`,arabicMeaning:`الروتين اليومي المعتاد`,partOfSpeech:`phrase`,exampleSentence:`My daily routine is the same every school morning.`,visualCue:`open_book`},{id:`p2_u1_w2`,word:`Sofa`,phonetics:`/ˈsəʊ.fə/`,arabicMeaning:`أريكة / كنبة مريحة`,partOfSpeech:`noun`,exampleSentence:`Grandfather sits comfortably on the large sofa to read his newspaper.`,visualCue:`happy_face`},{id:`p2_u1_w3`,word:`Text`,phonetics:`/tekst/`,arabicMeaning:`يراسل نصياً عبر الهاتف`,partOfSpeech:`verb`,exampleSentence:`I always text my classmates on the sofa after doing homework.`,visualCue:`hand_wave`},{id:`p2_u1_w4`,word:`Railway line`,phonetics:`/ˈreɪl.weɪ laɪn/`,arabicMeaning:`خط السكة الحديد`,partOfSpeech:`noun`,exampleSentence:`The Railway Children lived in a house near the railway line.`,visualCue:`desert_safari`}],collocations:[{phrase:`have a routine`,meaningAr:`يمتلك روتيناً يومياً`,example:`Do you have the same daily routine every week?`},{phrase:`make breakfast`,meaningAr:`يعد وجبة الإفطار`,example:`My mum helps me make breakfast before school.`}],conversationTerms:[{en:`What time do you usually wake up?`,ar:`في أي وقت تستيقظ عادةً؟`},{en:`I always catch the bus at seven sharp.`,ar:`أنا دائماً أستقل الحافلة في تمام السابعة.`},{en:`How do you spend your free time?`,ar:`كيف تقضي وقت فراغك؟`}]},tab2_Grammar:{rules:[{title:`Adverbs of Frequency & Present Simple`,ruleExplanationAr:`ظروف التكرار (always, usually, often, sometimes, never) تأتي قبل الفعل الأساسي وبعد فعل to be (am, is, are).`,structureFormula:`Subject + Adverb of Frequency + Main Verb | Subject + am/is/are + Adverb`,examples:[{en:`Mariam always listens to the teacher attentively.`,ar:`مريم دائماً تستمع إلى المعلم بانتباه.`},{en:`We are never late for our morning lessons.`,ar:`نحن لا نتأخر أبداً عن حصص الصباح.`}],visualPatternBlocks:[`Subject`,`Adverb of Frequency (always 100% -> never 0%)`,`Base Verb`]}],sentenceBuilderDrills:[{jumbledParts:[`late`,`are`,`We`,`never`,`for`,`school`],correctOrder:[`We`,`are`,`never`,`late`,`for`,`school`],translationAr:`نحن لا نتأخر أبداً عن المدرسة`}],errorCorrectionDrills:[{sentence:`He (always is) cheerful and polite.`,wrongWord:`always is`,correctWord:`is always`,explanationAr:`يأتي فعل to be قبل ظرف التكرار دائماً: is always.`}]},tab3_Skills:{dialogue:{title:`Dialogue: Discussing daily morning routine`,context:`Nader and Tamer meet on the bus to school.`,turns:[{speaker:`Nader`,text:`Good morning Tamer! How do you get to school?`,isBlank:!1},{speaker:`Tamer`,isBlank:!0,blankNumber:1,expectedAnswer:`I always take the school bus.`,hintAr:`أجب بأنك تستقل الحافلة المدرسية`},{speaker:`Nader`,text:`Does your mother make your breakfast?`,isBlank:!1},{speaker:`Tamer`,isBlank:!0,blankNumber:2,expectedAnswer:`Yes, she always prepares healthy breakfast for me.`,hintAr:`أجب بالإيجاب`}]},readingPassage:{title:`The Railway Children (Edith Nesbit)`,text:`Roberta, Peter, and Phyllis lived happily with their parents in London. Suddenly, their father was taken away from their comfortable home. The children and their mother moved to a small, poor house near a railway line. Life was difficult, but the children helped poor people and waved to the trains, making friends with an old gentleman who helped prove their father's innocence.`,translationAr:`قصة أطفال السكة الحديد وكفاحهم الشجاع في الريف.`},writingPrompt:{title:`Paragraph: My Daily Routine (روتيني اليومي)`,prompt:`Write 80-90 words about your typical daily routine on school days.`,targetWordsCount:85,rubric:[`Accurate adverbs of frequency`,`Correct present simple`,`Logical sequence of daily events`],modelAnswer:`On school days, my alarm goes off at six o'clock. I always wash my face and brush my teeth before breakfast. My mother usually prepares warm milk and cheese sandwiches. At half past seven, I walk to school with my classmates. After school, I rest, do my homework, and sometimes text my friends. I never stay up late because sleep keeps me healthy.`}},examSuite:{level1_Foundation:[{id:`prep2_u1_l1_q1`,type:`mcq`,questionPrompt:`A comfortable long seat for two or more people in the living room is a ______.`,options:[`sofa`,`shelf`,`wardrobe`,`fridge`],correctAnswer:`sofa`,explanationAr:`الأريكة المريحة في غرفة المعيشة تُسمى sofa.`,marks:1,subSkill:`Vocabulary`}],level2_Contextual:[{id:`prep2_u1_l2_q1`,type:`fill_in_the_blank`,questionPrompt:`They ______ go to school on Fridays because it is a weekend.`,options:[`never`,`always`,`usually`,`often`],correctAnswer:`never`,explanationAr:`يوم الجمعة إجازة رسمية، فالطلاب لا يذهبون أبداً (never).`,marks:1,subSkill:`Grammar`}],level3_AdvancedStructure:[{id:`prep2_u1_l3_q1`,type:`error_correction`,questionPrompt:`Correct: "Hany (listen usually) to the morning news."`,correctAnswer:`usually listens`,explanationAr:`يأتي ظرف التكرار قبل الفعل الأساسي، ومع المفرد نضيف s: usually listens.`,marks:2,subSkill:`Grammar`}],level4_MoeMockExam:[{id:`prep2_u1_l4_q1`,type:`mcq`,questionPrompt:`Practice MOE Mock: The Railway Children had to leave their big house because their father ______.`,options:[`was taken away unjustly`,`bought a new car`,`went on a holiday`,`built a factory`],correctAnswer:`was taken away unjustly`,explanationAr:`اقتيد والدهم ظلماً بعيداً عن أسرته في القصة المقررة.`,marks:2,subSkill:`Reading`}],level5_HigherThinking:[{id:`prep2_u1_l5_q1`,type:`guided_writing`,questionPrompt:`Explain how having an organized daily routine improves academic achievement:`,correctAnswer:`A consistent daily routine enhances discipline and reduces stress. Allocating dedicated study slots ensures tasks are finished on time, fostering academic excellence.`,explanationAr:`تحليل أهمية تنظيم الوقت والروتين الإيجابي في التفوق الدراسي.`,marks:3,subSkill:`Writing`}]}},{unitId:`prep3_t1_u1`,grade:`prep_3`,gradeNumber:9,term:1,unitNumber:1,unitTitleEn:`Around Town`,unitTitleAr:`حول المدينة (معالم الإسماعيلية ووسائل النقل)`,theme:`Directions, public transport, Lake Timsah, Ismailia monuments, botanical gardens`,tab1_Vocabulary:{words:[{id:`p3_u1_w1`,word:`Botanical garden`,phonetics:`/bəˈtæn.ɪ.kəl ˈɡɑː.dən/`,arabicMeaning:`حديقة نباتية عامة`,partOfSpeech:`noun`,exampleSentence:`The Orman Botanical Garden in Giza has rare trees and flowers.`,visualCue:`rooftop_garden`},{id:`p3_u1_w2`,word:`Monuments`,phonetics:`/ˈmɒn.jə.mənts/`,arabicMeaning:`آثار تاريخية وصروح تذكارية`,partOfSpeech:`noun`,exampleSentence:`Luxor contains one third of the world historical monuments.`,visualCue:`ancient_pyramids`},{id:`p3_u1_w3`,word:`Aquarium`,phonetics:`/əˈkweə.ri.əm/`,arabicMeaning:`متحف الأحياء المائية / حديقة الأسماك`,partOfSpeech:`noun`,exampleSentence:`Children love observing colourful marine life at the aquarium.`,visualCue:`river_nile`},{id:`p3_u1_w4`,word:`Platform`,phonetics:`/ˈplæt.fɔːm/`,arabicMeaning:`رصيف قطار محدد`,partOfSpeech:`noun`,exampleSentence:`The express train to Alexandria departs from platform number four.`,visualCue:`goodbye_door`}],collocations:[{phrase:`go straight on`,meaningAr:`سر بشكل مستقيم للأمام`,example:`Go straight on and then turn left at the traffic lights.`},{phrase:`take the first turning`,meaningAr:`ادخل في أول منعطف`,example:`Take the first turning on your right.`}],conversationTerms:[{en:`Could you tell me the way to the library, please?`,ar:`هل يمكنك إخباري بالطريق إلى المكتبة من فضلك؟`},{en:`The train to Aswan leaves at eight o’clock tonight.`,ar:`القطار المتجه إلى أسوان يغادر في تمام الثامنة مساءً.`},{en:`Ismailia is peaceful and known for attractive gardens.`,ar:`تتميز الإسماعيلية بالهدوء والحدائق الجذابة.`}]},tab2_Grammar:{rules:[{title:`Prepositions of Place & Present Simple for Scheduled Timetables`,ruleExplanationAr:`نستخدم المضارع البسيط للتعبير عن المواعيد والجداول الزمنية الرسمية للقطارات والحافلات والافتتاح والختام. ونستخدم حروف جر المكان (next to, opposite, between, on the corner).`,structureFormula:`Timetabled Subject (train/plane/library) + Verb (-s/-es) + Scheduled Time`,examples:[{en:`The train departs at 07:15 AM tomorrow morning.`,ar:`يغادر القطار في تمام الساعة 7:15 صباح الغد.`},{en:`The science museum opens at nine o'clock.`,ar:`يفتح متحف العلوم في تمام الساعة التاسعة.`}],visualPatternBlocks:[`Public Vehicle / Event`,`Present Simple Verb (-s)`,`Fixed Official Time`]}],sentenceBuilderDrills:[{jumbledParts:[`train`,`leaves`,`The`,`seven`,`at`,`o'clock`],correctOrder:[`The`,`train`,`leaves`,`at`,`seven`,`o'clock`],translationAr:`القطار يغادر في تمام السابعة`}],errorCorrectionDrills:[{sentence:`The metro train (leave) at 8:30 AM tomorrow.`,wrongWord:`leave`,correctWord:`leaves`,explanationAr:`جداول المواعيد الثابتة للمواصلات العامة تصاغ في المضارع البسيط مع المفرد: leaves.`}]},tab3_Skills:{dialogue:{title:`Dialogue: Asking for and giving directions in town`,context:`A tourist asks a local Egyptian student for directions to the railway station.`,turns:[{speaker:`Tourist`,text:`Excuse me, could you direct me to the railway station?`,isBlank:!1},{speaker:`Student`,isBlank:!0,blankNumber:1,expectedAnswer:`Go straight on and take the second turning on your left.`,hintAr:`أعطِ توجيهاً واضحاً ومحدداً`},{speaker:`Tourist`,text:`How far is it from here?`,isBlank:!1},{speaker:`Student`,isBlank:!0,blankNumber:2,expectedAnswer:`It is about five minutes on foot.`,hintAr:`حدد المسافة أو المدة الزمنية`}]},readingPassage:{title:`Ismailia: The Jewel of the Suez Canal`,text:`Ismailia is a beautiful, peaceful city situated on Lake Timsah between Port Said and Suez. It has historic French and British architecture, wide streets, and over thirty public parks. It is quiet with very little pollution. Many tourists visit the Natural Science Museum and enjoy swimming in Lake Timsah.`,translationAr:`نص القراءة الرسمي عن مدينة الإسماعيلية وتاريخها المتميز.`},writingPrompt:{title:`A Review of Your City / Town (مقال عن مدينتي)`,prompt:`Write an article of about 110 words describing your hometown, its monuments, and transport system.`,targetWordsCount:110,rubric:[`Accurate prepositions`,`Present simple for attractions`,`Clear structure (intro, body, conclusion)`],modelAnswer:`I live in Ismailia, which is one of the most attractive cities in Egypt. It is located on the Suez Canal. There are many historical monuments and botanical gardens with majestic trees. The public transport system is efficient and punctual; trains and buses connect the city smoothly with Cairo and Port Said. I am proud to live in such a peaceful place.`}},examSuite:{level1_Foundation:[{id:`prep3_u1_l1_q1`,type:`mcq`,questionPrompt:`A place where you can see live fish and marine creatures is an ______.`,options:[`aquarium`,`library`,`bank`,`stadium`],correctAnswer:`aquarium`,explanationAr:`متحف الأحياء المائية هو aquarium.`,marks:1,subSkill:`Vocabulary`}],level2_Contextual:[{id:`prep3_u1_l2_q1`,type:`fill_in_the_blank`,questionPrompt:`The express train to Alexandria ______ at platform six in ten minutes.`,options:[`arrives`,`arrived`,`is arriving`,`arrive`],correctAnswer:`arrives`,explanationAr:`مواعيد وسائل النقل العامة المجدولة نستخدم فيها المضارع البسيط: arrives.`,marks:1,subSkill:`Grammar`}],level3_AdvancedStructure:[{id:`prep3_u1_l3_q1`,type:`error_correction`,questionPrompt:`Correct: "The exhibition (finish) at 4:00 PM this afternoon."`,correctAnswer:`finishes`,explanationAr:`مواعيد إغلاق المعارض والفعاليات الثابتة تصاغ في المضارع البسيط: finishes.`,marks:2,subSkill:`Grammar`}],level4_MoeMockExam:[{id:`prep3_u1_l4_q1`,type:`mcq`,questionPrompt:`Practice MOE Mock: Lake Timsah is a famous natural landmark located in the city of ______.`,options:[`Ismailia`,`Aswan`,`Matrouh`,`Tanta`],correctAnswer:`Ismailia`,explanationAr:`بحيرة التمساح تقع في مدينة الإسماعيلية كما ورد في منهج New Hello.`,marks:2,subSkill:`Reading`}],level5_HigherThinking:[{id:`prep3_u1_l5_q1`,type:`guided_writing`,questionPrompt:`Evaluate why electric public transport (monorail & electric trains) is essential for Egypt's modern green cities:`,correctAnswer:`Electric transport reduces carbon emissions and eases traffic congestion in metropolitan centers. It supports sustainable urban growth by offering punctual and eco-friendly mobility.`,explanationAr:`تقييم بيئي وتنموي لأهمية وسائل النقل الكهربائي الحديثة في مصر.`,marks:3,subSkill:`Writing`}]}},{unitId:`prep1_t1_u2`,grade:`prep_1`,gradeNumber:7,term:1,unitNumber:2,unitTitleEn:`It's My Favourite Subject`,unitTitleAr:`إنها مادتي المفضلة (المواد الدراسية والجدول المدرسي)`,theme:`School subjects, timetable, school bell, library, telling the time, typical school day in different countries`,tab1_Vocabulary:{words:[{id:`p1_u2_w1`,word:`Timetable`,phonetics:`/ˈtaɪmˌteɪ.bəl/`,arabicMeaning:`جدول المواعيد / جدول الحصص`,partOfSpeech:`noun`,exampleSentence:`Look at the school timetable to see which subject we have next.`,visualCue:`open_book`},{id:`p1_u2_w2`,word:`Bell`,phonetics:`/bel/`,arabicMeaning:`جرس المدرسة`,partOfSpeech:`noun`,exampleSentence:`When the bell rings, the break time begins.`,visualCue:`clock_alarm`},{id:`p1_u2_w3`,word:`Drama`,phonetics:`/ˈdrɑː.mə/`,arabicMeaning:`مادة التمثيل المسرحي والدراما`,partOfSpeech:`noun`,exampleSentence:`In drama lessons, we learn how to act and speak confidently on stage.`,visualCue:`trophy_cup`},{id:`p1_u2_w4`,word:`Typical`,phonetics:`/ˈtɪp.ɪ.kəl/`,arabicMeaning:`نموذجي / معتاد`,partOfSpeech:`adjective`,exampleSentence:`On a typical school day, we have seven lessons.`,visualCue:`star_badge`}],collocations:[{phrase:`have a lesson`,meaningAr:`يأخذ حصة دراسية`,example:`We have English lessons four times a week.`},{phrase:`ring the bell`,meaningAr:`يرن الجرس`,example:`The teacher rings the bell at break.`}],conversationTerms:[{en:`What is your favourite subject?`,ar:`ما هي مادتك المفضلة؟`},{en:`What time does the science lesson start?`,ar:`في أي وقت تبدأ حصة العلوم؟`},{en:`We have computer studies in the multimedia lab.`,ar:`لدينا حاسب آلي في معمل التطوير.`}]},tab2_Grammar:{rules:[{title:`Apostrophe of Possession ('s / s')`,ruleExplanationAr:`نضع 's للمفرد والجموع الشاذة (boy's book / children's games)، ونضع الفاصلة فقط ' بعد الأسماء والجموع المنتهية بحرف s مثل (the girls' school / boys' bags).`,structureFormula:`Singular Noun + 's | Regular Plural (-s) + ' | Irregular Plural + 's`,examples:[{en:`This is Ali's notebook.`,ar:`هذا دفتر علي.`},{en:`The teachers' room is on the first floor.`,ar:`غرفة المعلمين في الطابق الأول.`}],visualPatternBlocks:[`Ali + 's = Ali's (Singular)`,`Teachers + ' = Teachers' (Plural with -s)`]}],sentenceBuilderDrills:[{jumbledParts:[`teachers'`,`room`,`The`,`is`,`upstairs`],correctOrder:[`The`,`teachers'`,`room`,`is`,`upstairs`],translationAr:`غرفة المعلمين تقع في الطابق العلوي`}],errorCorrectionDrills:[{sentence:`This is my (brother) car. It is brand new.`,wrongWord:`brother`,correctWord:`brother's`,explanationAr:`لإثبات الملكية لمفرد نستخدم فاصلة عليا وحرف s: brother's.`}]},tab3_Skills:{dialogue:{title:`Dialogue: Asking about school subjects and timetable`,context:`Lina and Sarah are talking after the first period.`,turns:[{speaker:`Lina`,text:`Hi Sarah! What is your favourite subject today?`,isBlank:!1},{speaker:`Sarah`,isBlank:!0,blankNumber:1,expectedAnswer:`My favourite subject is English because it is interesting.`,hintAr:`أخبريها بمادتك المفضلة (اللغة الإنجليزية)`},{speaker:`Lina`,text:`When do we have maths?`,isBlank:!1},{speaker:`Sarah`,isBlank:!0,blankNumber:2,expectedAnswer:`We have maths after the break.`,hintAr:`حددي الموعد (بعد الفسحة)`}]},readingPassage:{title:`A Typical School Day in Nairobi, Kenya`,text:`In Nairobi, students wake up early. Many children walk for an hour to get to school. Lessons start at eight o'clock and finish at four in the afternoon. Students study English, Kiswahili, maths, and science. During break, they play football in the yard. They love learning because education opens doors to great careers.`,translationAr:`يوم دراسي نموذجي في نيروبي، كينيا وحرص الطلاب على التعليم.`},writingPrompt:{title:`Paragraph: My Favourite School Day (يومي الدراسي المفضل)`,prompt:`Write 80 words about your favourite day at school, mentioning your subjects and activities.`,targetWordsCount:80,rubric:[`Correct use of possessive apostrophe`,`Accurate subject names`,`Logical flow of timetable`],modelAnswer:`Thursday is my favourite day of the week. We have our English lesson in the morning, followed by science and computer studies. I enjoy English because our teacher, Mr. Mohammad, explains grammar clearly. At break time, I chat with my friends in the playground and eat healthy snacks. In the afternoon, we have physical education and play volleyball. I return home feeling energetic and satisfied.`}},examSuite:{level1_Foundation:[{id:`prep1_u2_l1_q1`,type:`mcq`,questionPrompt:`In a ______ lesson, students learn how to act in plays and perform on stage.`,options:[`drama`,`science`,`geography`,`maths`],correctAnswer:`drama`,explanationAr:`في حصة الدراما (drama) يتعلم الطلاب التمثيل المسرحي.`,marks:1,subSkill:`Vocabulary`}],level2_Contextual:[{id:`prep1_u2_l2_q1`,type:`fill_in_the_blank`,questionPrompt:`These are the ______ bags; they left them in the girls' changing room.`,options:[`girls'`,`girl's`,`girls`,`girles`],correctAnswer:`girls'`,explanationAr:`جمع البنات ينتهي بحرف s، فنضيف الفاصلة العليا فقط بعد s: girls'.`,marks:1,subSkill:`Grammar`}],level3_AdvancedStructure:[{id:`prep1_u2_l3_q1`,type:`error_correction`,questionPrompt:`Correct the word between brackets: "That is the (childrens) playground."`,correctAnswer:`children's`,explanationAr:`كلمة children جمع غير منتظم (شاذ)، فنضع لها 's لإثبات الملكية: children's.`,marks:2,subSkill:`Grammar`}],level4_MoeMockExam:[{id:`prep1_u2_l4_q1`,type:`mcq`,questionPrompt:`Practice MOE Mock: We know the lesson has finished when the school ______ rings loudly.`,options:[`bell`,`ball`,`bull`,`bill`],correctAnswer:`bell`,explanationAr:`جرس المدرسة يُدعى bell.`,marks:2,subSkill:`Vocabulary`}],level5_HigherThinking:[{id:`prep1_u2_l5_q1`,type:`guided_writing`,questionPrompt:`Why is having a structured timetable vital for student academic achievement?`,correctAnswer:`A structured timetable instills punctuality, balanced subject allocation, and cognitive focus. It prevents burnout by pacing academic demands and physical recreation evenly.`,explanationAr:`أهمية الجدول الدراسي المنظم في تعزيز التحصيل الأكاديمي وتنظيم الوقت.`,marks:3,subSkill:`Writing`}]}},{unitId:`prep2_t1_u2`,grade:`prep_2`,gradeNumber:8,term:1,unitNumber:2,unitTitleEn:`How Are You Feeling?`,unitTitleAr:`كيف تشعر؟ (المشاعر والوظائف الخدمية ومساعدة الآخرين)`,theme:`Feelings, street-food stalls, sign language, hospitals, call-centre workers, empathy`,tab1_Vocabulary:{words:[{id:`p2_u2_w1`,word:`Street-food stall`,phonetics:`/striːt fuːd stɔːl/`,arabicMeaning:`كشك بيع طعام الشارع`,partOfSpeech:`noun`,exampleSentence:`The chef prepares delicious falafel at his street-food stall every morning.`,visualCue:`food_lunch`},{id:`p2_u2_w2`,word:`Sign language`,phonetics:`/saɪn ˈlæŋ.ɡwɪdʒ/`,arabicMeaning:`لغة الإشارة للصم والبكم`,partOfSpeech:`noun`,exampleSentence:`My aunt teaches sign language to help deaf people communicate easily.`,visualCue:`hand_wave`},{id:`p2_u2_w3`,word:`Grateful`,phonetics:`/ˈɡreɪt.fəl/`,arabicMeaning:`ممتن / شاكر للجميل`,partOfSpeech:`adjective`,exampleSentence:`I am always grateful to my parents for their unconditional care.`,visualCue:`happy_face`},{id:`p2_u2_w4`,word:`Call-centre worker`,phonetics:`/kɔːl ˈsen.tər ˈwɜː.kər/`,arabicMeaning:`موظف خدمة عملاء بالهاتف`,partOfSpeech:`noun`,exampleSentence:`The call-centre worker answers customers' questions politely.`,visualCue:`phone_call`}],collocations:[{phrase:`park a food stall`,meaningAr:`يوقف كشك الطعام في مكان مخصص`,example:`Street vendors park their stalls along the promenade.`},{phrase:`communicate in sign language`,meaningAr:`يتواصل بلغة الإشارة`,example:`Deaf students communicate in sign language fluently.`}],conversationTerms:[{en:`How are you feeling today?`,ar:`كيف تشعر اليوم؟`},{en:`I am feeling proud and grateful.`,ar:`أشعر بالفخر والامتنان.`},{en:`She is looking after sick patients with tenderness.`,ar:`إنها ترعى المرضى بحنان وعناية.`}]},tab2_Grammar:{rules:[{title:`Present Continuous vs. Present Simple & Adverbs of Manner`,ruleExplanationAr:`المضارع البسيط يعبر عن الحقائق والعادات، بينما المضارع المستمر (am/is/are + v-ing) يعبر عن أحداث تقع الآن أو مؤقتة. كما نضيف ly للصفة لتكوين الظرف الدال على الكيفية (slow -> slowly, careful -> carefully).`,structureFormula:`Present Simple: S + V(s) | Present Continuous: S + am/is/are + V-ing | Adverb: Adj + ly`,examples:[{en:`He usually walks to work, but today he is taking a taxi.`,ar:`هو يمشي عادةً للعمل، ولكنه اليوم يستقل تاكسي.`},{en:`She speaks English fluently and drives carefully.`,ar:`تتحدث الإنجليزية بطلاقة وتقود بحذر.`}],visualPatternBlocks:[`Fact/Habit -> Present Simple`,`Action Right Now -> am/is/are + V-ing`,`Manner -> Verb + Adverb (-ly)`]}],sentenceBuilderDrills:[{jumbledParts:[`speaking`,`is`,`He`,`politely`,`to`,`customers`],correctOrder:[`He`,`is`,`speaking`,`politely`,`to`,`customers`],translationAr:`هو يتحدث بأدب مع الزبائن`}],errorCorrectionDrills:[{sentence:`She sings (beautiful) in the school concert.`,wrongWord:`beautiful`,correctWord:`beautifully`,explanationAr:`نصف الفعل بالظرف المنتهي بـ ly: beautifully.`}]},tab3_Skills:{dialogue:{title:`Dialogue: Checking in on a friend who is working at a charity`,context:`Maged meets Tarek near a medical center.`,turns:[{speaker:`Maged`,text:`Hi Tarek, why are you wearing a uniform today?`,isBlank:!1},{speaker:`Tarek`,isBlank:!0,blankNumber:1,expectedAnswer:`Because I am volunteering at the children hospital ward.`,hintAr:`أخبره بأنك تتطوع في عنبر الأطفال`},{speaker:`Maged`,text:`How do you communicate with hearing-impaired kids?`,isBlank:!1},{speaker:`Tarek`,isBlank:!0,blankNumber:2,expectedAnswer:`I use sign language to talk with them.`,hintAr:`أخبره باستخدام لغة الإشارة`}]},readingPassage:{title:`Street Food in Cairo and Modern Urban Life`,text:`Early in the morning, street vendors park their food stalls in busy areas of Cairo. They prepare delicious foul and tameya sandwiches for workers and commuters. These workers wake up before dawn to ensure the food is fresh and hygienic. Customers smile and thank them for their continuous hard work.`,translationAr:`طعام الشارع في القاهرة وكفاح البائعين في الصباح الباكر.`},writingPrompt:{title:`Paragraph: A Job That Helps Our Community (وظيفة تخدم المجتمع)`,prompt:`Write 80-90 words about the role of nurses and healthcare workers in hospitals.`,targetWordsCount:85,rubric:[`Accurate adverbs of manner`,`Contrast between habits and temporary actions`,`Rich emotional vocabulary`],modelAnswer:`Nurses are true heroes in our healthcare system. They look after sick patients day and night with immense patience. Even during difficult emergencies, they speak softly and act calmly to soothe worried families. Today, many nurses are working extra shifts to keep hospital wards sterile and safe. We should always treat them respectfully and feel grateful for their noble contributions.`}},examSuite:{level1_Foundation:[{id:`prep2_u2_l1_q1`,type:`mcq`,questionPrompt:`People who cannot hear or speak communicate with each other using ______ language.`,options:[`sign`,`secret`,`foreign`,`loud`],correctAnswer:`sign`,explanationAr:`لغة الإشارة للصم والبكم هي sign language.`,marks:1,subSkill:`Vocabulary`}],level2_Contextual:[{id:`prep2_u2_l2_q1`,type:`fill_in_the_blank`,questionPrompt:`Look! The street vendor ______ hot sandwiches for hungry workers right now.`,options:[`is preparing`,`prepares`,`prepared`,`was prepared`],correctAnswer:`is preparing`,explanationAr:`كلمة Look! تدل على المضارع المستمر: is preparing.`,marks:1,subSkill:`Grammar`}],level3_AdvancedStructure:[{id:`prep2_u2_l3_q1`,type:`error_correction`,questionPrompt:`Correct the word between brackets: "Ahmed did his homework very (careful) yesterday."`,correctAnswer:`carefully`,explanationAr:`لوصف طريقة أداء الفعل نستخدم ظرف الكيفية المنتهي بـ ly: carefully.`,marks:2,subSkill:`Grammar`}],level4_MoeMockExam:[{id:`prep2_u2_l4_q1`,type:`mcq`,questionPrompt:`Practice MOE Mock: When someone does you a favour, you should feel ______ and thank them.`,options:[`grateful`,`greedy`,`careless`,`jealous`],correctAnswer:`grateful`,explanationAr:`عندما يسدي لك أحد معروفاً يجب أن تكون ممتناً وشاكراً (grateful).`,marks:2,subSkill:`Vocabulary`}],level5_HigherThinking:[{id:`prep2_u2_l5_q1`,type:`guided_writing`,questionPrompt:`Analyze how learning sign language in schools fosters social inclusion for disabled citizens:`,correctAnswer:`Teaching sign language breaks communicative barriers, dismantles prejudice, and guarantees equal social participation for the deaf community. It nurtures an empathetic societal fabric rooted in mutual respect.`,explanationAr:`تحليل أثر تعلم لغة الإشارة في دمج الصم في المجتمع وتعزيز التكافل الاجتماعي.`,marks:3,subSkill:`Writing`}]}},{unitId:`prep3_t1_u2`,grade:`prep_3`,gradeNumber:9,term:1,unitNumber:2,unitTitleEn:`Let's Go Shopping`,unitTitleAr:`هيا نتسوق (الأجهزة المنزلية والتسوق الإلكتروني والعروض)`,theme:`Consumer technology, smart home devices, online shopping, customer reviews, complaints, delivery`,tab1_Vocabulary:{words:[{id:`p3_u2_w1`,word:`Microwave`,phonetics:`/ˈmaɪ.krə.weɪv/`,arabicMeaning:`فرن الميكروويف (لتسخين الطعام بسرعة)`,partOfSpeech:`noun`,exampleSentence:`Use the microwave to warm the soup in two minutes.`,visualCue:`trophy_cup`},{id:`p3_u2_w2`,word:`Kettle`,phonetics:`/ˈket.əl/`,arabicMeaning:`غلاية مياه كهربائية`,partOfSpeech:`noun`,exampleSentence:`He boiled water in the electric kettle to make hot mint tea.`,visualCue:`clock_alarm`},{id:`p3_u2_w3`,word:`Special offer`,phonetics:`/ˈspeʃ.əl ˈɒf.ər/`,arabicMeaning:`عرض خاص / تخفيض ترويجي`,partOfSpeech:`phrase`,exampleSentence:`The electronics store has a special offer: buy one speaker, get one free.`,visualCue:`star_badge`},{id:`p3_u2_w4`,word:`Complaint`,phonetics:`/kəmˈpleɪnt/`,arabicMeaning:`شكوى رسمية من خدمة أو منتج`,partOfSpeech:`noun`,exampleSentence:`She made a polite complaint to the customer service department about the late delivery.`,visualCue:`phone_call`}],collocations:[{phrase:`make a complaint`,meaningAr:`يقدم شكوى رسمية`,example:`Customers can make a complaint via email or phone.`},{phrase:`on special offer`,meaningAr:`في عرض خاص أو تخفيض`,example:`These smart televisions are currently on special offer.`}],conversationTerms:[{en:`Could I speak to the manager, please?`,ar:`هل يمكنني التحدث إلى المدير من فضلك؟`},{en:`The item arrived damaged in the package.`,ar:`وصلت السلعة تالفة داخل الطرد.`},{en:`We apologize and will deliver a replacement immediately.`,ar:`نعتذر وسنرسل بديلاً فوراً.`}]},tab2_Grammar:{rules:[{title:`Comparative / Superlative & (Both...and / Either...or / Neither...nor / None of)`,ruleExplanationAr:`للمقارنة بين شيئين: (Adj-er than / more + adj + than). وللتفضيل: (the Adj-est / the most + adj). وتراكيب الربط: both...and (فعل جمع دائماً)، either...or (إما...أو)، neither...nor (لا هذا ولا ذاك والفعل يتبع الفاعل الثاني)، none of (لا أحد من أكثر من اثنين).`,structureFormula:`Both X and Y + Plural Verb | Neither X nor Y + Verb matches Y | Either X or Y`,examples:[{en:`Both the kettle and the microwave are on sale.`,ar:`كلا الغلاية والميكروويف معروضان في التخفيضات.`},{en:`Neither the toaster nor the speakers were working.`,ar:`لا المحمصة ولا مكبرات الصوت كانت تعمل.`}],visualPatternBlocks:[`Both + A + and + B + Plural Verb`,`Neither + A + nor + B + Verb agrees with B`]}],sentenceBuilderDrills:[{jumbledParts:[`Both`,`laptops`,`on`,`sale`,`are`,`today`],correctOrder:[`Both`,`laptops`,`are`,`on`,`sale`,`today`],translationAr:`كلا الجهازين المحمولين معروضان في التخفيضات اليوم`}],errorCorrectionDrills:[{sentence:`Both Mona and her sister (is) clever at English.`,wrongWord:`is`,correctWord:`are`,explanationAr:`التركيب both...and يأخذ دائماً فعلاً في صيغة الجمع: are.`}]},tab3_Skills:{dialogue:{title:`Dialogue: Filing a polite complaint about an online purchase`,context:`Heba is phoning customer service regarding a faulty kettle.`,turns:[{speaker:`Agent`,text:`Hello, Modern Appliances customer care. How can I help you?`,isBlank:!1},{speaker:`Heba`,isBlank:!0,blankNumber:1,expectedAnswer:`I would like to make a complaint about an electric kettle I ordered.`,hintAr:`أخبره برغبتك في تقديم شكوى بشأن غلاية مياه`},{speaker:`Agent`,text:`What exactly is the problem with it?`,isBlank:!1},{speaker:`Heba`,isBlank:!0,blankNumber:2,expectedAnswer:`It does not heat water and the power cord is broken.`,hintAr:`صفي العطل (لا تسخن الماء وسلك الكهرباء تالف)`}]},readingPassage:{title:`Smart Consumer Choices: Online Shopping vs. In-Store Buying`,text:`Online shopping has transformed commerce in Egypt. Customers can compare prices across dozens of websites in seconds, read verified user reviews, and take advantage of seasonal discounts like White Friday. However, online shoppers must verify website authenticity to avoid counterfeit merchandise and delayed courier deliveries.`,translationAr:`التسوق عبر الإنترنت وتأثيره على المستهلك المصري.`},writingPrompt:{title:`Review: An Online Purchase You Made (مراجعة تجربة شراء إلكترونية)`,prompt:`Write a review of 100-110 words about an electronic device you bought online, evaluating its performance.`,targetWordsCount:105,rubric:[`Accurate comparative and correlative conjunctions`,`Balanced evaluation of pros and cons`,`Clear purchasing recommendation`],modelAnswer:`Last month, I ordered a smart microwave from a certified online retailer during their White Friday sale. The package arrived within forty-eight hours, which was commendable. The microwave heats food evenly and features multiple intuitive digital presets. Both the build quality and the energy-saving mode exceeded my expectations. The only minor drawback was the short power cable, which required an extension. Overall, it is one of the most reliable kitchen appliances I have ever purchased, and I strongly recommend it to busy households seeking rapid, hygienic cooking.`}},examSuite:{level1_Foundation:[{id:`prep3_u2_l1_q1`,type:`mcq`,questionPrompt:`An electrical kitchen appliance used specifically to heat food rapidly using electromagnetic waves is a ______.`,options:[`microwave`,`toaster`,`washing machine`,`iron`],correctAnswer:`microwave`,explanationAr:`جهاز تسخين الطعام السريع بالموجات الكهرومغناطيسية هو الميكروويف (microwave).`,marks:1,subSkill:`Vocabulary`}],level2_Contextual:[{id:`prep3_u2_l2_q1`,type:`fill_in_the_blank`,questionPrompt:`Neither the seller ______ the delivery courier answered my urgent messages.`,options:[`nor`,`or`,`and`,`with`],correctAnswer:`nor`,explanationAr:`تأتي nor مكملة لـ Neither في صيغة النفي المزدوج: Neither...nor.`,marks:1,subSkill:`Grammar`}],level3_AdvancedStructure:[{id:`prep3_u2_l3_q1`,type:`error_correction`,questionPrompt:`Correct the word between brackets: "Both the red toaster and the blender (is) discounted by 30%."`,correctAnswer:`are`,explanationAr:`الرابط both...and يتبعه دائماً فعل جمع: are.`,marks:2,subSkill:`Grammar`}],level4_MoeMockExam:[{id:`prep3_u2_l4_q1`,type:`mcq`,questionPrompt:`Practice MOE Mock: When a customer is dissatisfied with defective goods, they have the legal right to submit a ______.`,options:[`complaint`,`reward`,`donation`,`medal`],correctAnswer:`complaint`,explanationAr:`الشكوى الرسمية عند وجود عيب في السلعة تسمى complaint.`,marks:2,subSkill:`Vocabulary`}],level5_HigherThinking:[{id:`prep3_u2_l5_q1`,type:`guided_writing`,questionPrompt:`Critique how digital payment security and transparent return policies empower electronic commerce in developing economies:`,correctAnswer:`Robust cybersecurity encryption and friction-free return guarantees establish consumer trust, encouraging reluctant traditional buyers to embrace e-commerce. This drives micro-business revenues and integrates unbanked segments into the digital economy.`,explanationAr:`تحليل دور أمان الدفع الإلكتروني وسياسات الإرجاع في دعم التجارة الرقمية.`,marks:3,subSkill:`Writing`}]}},{unitId:`prep3_t1_u3`,grade:`prep_3`,gradeNumber:9,term:1,unitNumber:3,unitTitleEn:`My Community`,unitTitleAr:`مجتمعي (مبادرة حياة كريمة ومرافق الأحياء والتطوع)`,theme:`Decent Life initiative (حياة كريمة), public facilities, neighborhood improvements, social networking, elderly care`,tab1_Vocabulary:{words:[{id:`p3_u3_w1`,word:`Decent Life initiative`,phonetics:`/ˈdiː.sənt laɪf ɪˈnɪʃ.ə.tɪv/`,arabicMeaning:`مبادرة حياة كريمة الرئاسية لتطوير الريف`,partOfSpeech:`phrase`,exampleSentence:`The Decent Life initiative builds schools and hospitals in rural villages across Egypt.`,visualCue:`trophy_cup`},{id:`p3_u3_w2`,word:`Facilities`,phonetics:`/fəˈsɪl.ə.tiz/`,arabicMeaning:`مرافق وخدمات عامة (مستشفيات، نوادٍ، حدائق)`,partOfSpeech:`noun`,exampleSentence:`Our town boasts modern sports facilities and accessible libraries.`,visualCue:`star_badge`},{id:`p3_u3_w3`,word:`Pavement`,phonetics:`/ˈpeɪv.mənt/`,arabicMeaning:`رصيف المشاة`,partOfSpeech:`noun`,exampleSentence:`Pedestrians should safely walk on the wide pavement rather than the highway.`,visualCue:`desert_safari`},{id:`p3_u3_w4`,word:`Social networking service`,phonetics:`/ˌsəʊ.ʃəl ˈnet.wɜː.kɪŋ ˈsɜː.vɪs/`,arabicMeaning:`موقع أو خدمة التواصل الاجتماعي`,partOfSpeech:`phrase`,exampleSentence:`Neighbors created a social networking service group to coordinate street cleaning.`,visualCue:`phone_call`}],collocations:[{phrase:`deliver public services`,meaningAr:`يقدم خدمات عامة للمواطنين`,example:`The local council delivers clean water and electricity to every hamlet.`},{phrase:`have equal opportunities`,meaningAr:`يمتلك فرصاً متكافئة`,example:`All rural youth must have equal educational opportunities.`}],conversationTerms:[{en:`What facilities does your neighborhood need most?`,ar:`ما أكثر المرافق التي يحتاجها حيك السكني؟`},{en:`We are repainting the walls to brighten our street.`,ar:`نحن نعيد طلاء الجدران لتجميل شارعنا.`},{en:`Community cooperation creates lasting change.`,ar:`التعاون المجتمعي يصنع تغييراً دائماً.`}]},tab2_Grammar:{rules:[{title:`Adjectives ending in -ed vs. -ing & Present Continuous for Future Arrangements`,ruleExplanationAr:`الصفات المنتهية بـ -ed تعبر عن الشعور (I am excited = أشعر بالحماس)، بينما المنتهية بـ -ing تعبر عن المسبب أو الشيء المؤثر (The match is exciting = المباراة ممتعة ومحمسة). والمضارع المستمر (am/is/are + v-ing) يعبر عن ترتيبات مستقبلية تم حجزها وتجهيزها.`,structureFormula:`Feelings: S + feel/be + Adj-ed | Cause: S + be + Adj-ing | Future: S + am/is/are + V-ing + time`,examples:[{en:`The villagers were amazed by the speed of the renovations.`,ar:`شعر القرويون بالدهشة لسرعة أعمال التطوير.`},{en:`We are holding a community meeting next Monday at six.`,ar:`نحن نقيم اجتماعاً مجتمعياً الاثنين القادم في السادسة.`}],visualPatternBlocks:[`Person feels -> -ed (surprised, bored, interested)`,`Thing causes -> -ing (surprising, boring, interesting)`,`Arrangement -> am/is/are + V-ing`]}],sentenceBuilderDrills:[{jumbledParts:[`meeting`,`are`,`We`,`the`,`mayor`,`tomorrow`],correctOrder:[`We`,`are`,`meeting`,`the`,`mayor`,`tomorrow`],translationAr:`نحن سنقابل رئيس المدينة غداً`}],errorCorrectionDrills:[{sentence:`The historical documentary about Egyptian villages was very (interested).`,wrongWord:`interested`,correctWord:`interesting`,explanationAr:`الفيلم الوثائقي هو مسبب الاهتمام، فنستخدم الصفة المنتهية بـ ing: interesting.`}]},tab3_Skills:{dialogue:{title:`Dialogue: Discussing rural development and Hayah Kareema`,context:`Karim and Sherif are discussing their grandfather's village in Upper Egypt.`,turns:[{speaker:`Karim`,text:`Hi Sherif! Have you visited your grandfather's village recently?`,isBlank:!1},{speaker:`Sherif`,isBlank:!0,blankNumber:1,expectedAnswer:`Yes, the village has changed completely thanks to the Decent Life initiative.`,hintAr:`أخبره بالتغيير الكبير بفضل حياة كريمة`},{speaker:`Karim`,text:`What new facilities have they established there?`,isBlank:!1},{speaker:`Sherif`,isBlank:!0,blankNumber:2,expectedAnswer:`They paved new roads and built a primary healthcare centre.`,hintAr:`اذكر رصف الطرق وبناء وحدة رعاية صحية`}]},readingPassage:{title:`Hayah Kareema (The Decent Life Initiative)`,text:`The Decent Life initiative is one of the most ambitious social welfare projects in modern Egyptian history. Launched by the government, it targets thousands of underserved villages across Egypt to eliminate rural poverty. Engineers, healthcare workers, and voluntary youths coordinate to renovate houses, pave roads, deliver potable drinking water, and install broadband fiber cables.`,translationAr:`مبادرة حياة كريمة التاريخية لتطوير القرى المصرية.`},writingPrompt:{title:`Paragraph: Improving Facilities in My Neighborhood (تطوير مرافق الحي)`,prompt:`Write 100-110 words describing practical initiatives teenagers can undertake to improve their local community.`,targetWordsCount:105,rubric:[`Accurate use of -ed / -ing adjectives`,`Future arrangements with present continuous`,`Cohesive community theme`],modelAnswer:`Every citizen has a civic duty to elevate their local community. In our neighborhood, teenagers have launched an inspiring greening initiative. Next Saturday, we are planting thirty evergreen trees along the main pavement to provide shade and reduce air pollutants. We are also collaborating with the municipal council to renovate the dilapidated public playground so younger children have safe recreational space. Older residents were genuinely touched and offered us refreshing drinks. When community members unite with clear objectives, they foster solidarity, safeguard public property, and create cleaner surroundings for future generations.`}},examSuite:{level1_Foundation:[{id:`prep3_u3_l1_q1`,type:`mcq`,questionPrompt:`Public buildings, equipment, and medical services provided for public use are called ______.`,options:[`facilities`,`factories`,`accidents`,`arguments`],correctAnswer:`facilities`,explanationAr:`المرافق والخدمات العامة تُسمى facilities.`,marks:1,subSkill:`Vocabulary`}],level2_Contextual:[{id:`prep3_u3_l2_q1`,type:`fill_in_the_blank`,questionPrompt:`The students were so ______ when they heard that the new community library opened.`,options:[`excited`,`exciting`,`excite`,`excitement`],correctAnswer:`excited`,explanationAr:`لوصف مشاعر الطلاب نستخدم الصفة المنتهية بـ ed: excited.`,marks:1,subSkill:`Grammar`}],level3_AdvancedStructure:[{id:`prep3_u3_l3_q1`,type:`error_correction`,questionPrompt:`Correct the word between brackets: "We (travel) to Luxor next Tuesday; all tickets are booked."`,correctAnswer:`are travelling`,explanationAr:`للترتيبات المستقبلية المؤكدة (التذاكر محجوزة) نستخدم المضارع المستمر: are travelling.`,marks:2,subSkill:`Grammar`}],level4_MoeMockExam:[{id:`prep3_u3_l4_q1`,type:`mcq`,questionPrompt:`Practice MOE Mock: The Decent Life initiative primarily aims to improve living standards in rural ______ across Egypt.`,options:[`villages`,`islands`,`capitals`,`airports`],correctAnswer:`villages`,explanationAr:`تهدف مبادرة حياة كريمة في المقام الأول لتطوير قرى الريف المصري (villages).`,marks:2,subSkill:`Vocabulary`}],level5_HigherThinking:[{id:`prep3_u3_l5_q1`,type:`guided_writing`,questionPrompt:`Assess the long-term socio-economic return of investing in rural educational and healthcare infrastructure:`,correctAnswer:`Investing in rural schools and clinics eradicates multi-generational poverty, curtails urban migration pressures, and unlocks the latent workforce potential of rural youth. It guarantees balanced regional prosperity and economic resilience.`,explanationAr:`تقييم الأثر التنموي والاقتصادي طويل المدى للاستثمار في البنية التحتية التعليمية والصحية بالريف.`,marks:3,subSkill:`Writing`}]}}];function t(e,t){let n=[`A`,`B`,`C`,`D`],r=n.indexOf(e.correctAnswer);if(r===-1||!e.options||e.options.length!==4)return{...e,verificationStatus:`verified`};let i=t%4;if(r===i)return{...e,verificationStatus:`verified`};let a=[e.options[0],e.options[1],e.options[2],e.options[3]],o=a[i];return a[i]=a[r],a[r]=o,{...e,options:a,correctAnswer:n[i],verificationStatus:`verified`}}function n(e,n,r,i,a,o,s,c,l,u,d,f,p,m,h,g){let _=e*11+r*5+i*3,v=g.vocabGrammarMcqs.map((e,n)=>t(e,_+n)),y=g.readingPassage.mcqs.map((e,n)=>t(e,_+n+2)),b={...g,readingPassage:{...g.readingPassage,mcqs:y},vocabGrammarMcqs:v};return{stage:`Preparatory`,grade:e,gradeLabel:n,track:`New Hello`,textbookSeries:`New Hello! Prep ${e-6}`,verificationStatus:`verified`,sourceReference:`Egyptian MOE New Hello! Prep ${e-6} - Term ${r} Unit ${i}`,semester:r,unitNumber:i,unitTitle:a,unitTitleAr:o,theme:s,vocabularyModule:{keyWords:f.map(e=>({word:e.word,pos:e.pos,partOfSpeech:e.pos,ar:e.ar,meaningAr:e.ar,def:e.def,meaningEn:e.def,ex:e.ex,exampleSentence:e.ex,exAr:e.exAr})),collocations:p.map(e=>({phrase:e.phrase,meaningAr:e.meaningAr,example:e.example})),exercises:v.slice(0,3)},grammarModule:{ruleName:c,ruleNameAr:l,explanationSummary:u,detailedRules:d,exercises:v.slice(3,6)},readingModule:{passageTitle:b.readingPassage.title,passage:b.readingPassage.passage,criticalThinkingFocus:`Analytical inference on ${s}`,questions:y},listeningModule:{audioTitle:`${a}: Official Curriculum Dialogue Track`,speakerRoles:`Two Egyptian students / Teacher and student`,transcript:h,durationApprox:`3 mins`},unitExam:{examId:`prep_g${e}_u${i}_exam`,examTitle:`Prep ${e-6} - Unit ${i} MOE Standard Assessment (2026/2027)`,examTitleAr:`امتحان تقييم الوحدة ${i} - الصف ${e===7?`الأول`:e===8?`الثاني`:`الثالث`} الإعدادي`,durationMinutes:30,totalMarks:30,stage:`Preparatory`,questions:[...v.map(e=>({...e,id:`exam_${e.id}`})),...y.map(e=>({...e,id:`exam_${e.id}`}))],prepBlueprint:b}}}var r=n(7,`Prep 1`,1,4,`We're using technology!`,`نحن نستخدم التكنولوجيا الحديثة والأجهزة الذكية`,`Smartphones, tablets, laptops, chargers, 3D printers, video calls, internet safety`,`Present Continuous & Imperatives for Online Safety`,`المضارع المستمر وصيغة الأمر لإرشادات الأمان الرقمي`,`Use Present Continuous (am/is/are + verb-ing) for actions happening now. Use Imperatives (Infinitive verb / Don’t + infinitive) to give online safety rules: "Keep your password secret / Don’t send photos to strangers".`,[{title:`1. Present Continuous (المضارع المستمر)`,explanation:`Form: Subject + am/is/are + verb-ing. Keywords: now, at the moment, look!, listen!, at present. Rule for doubling: run -> running, sit -> sitting.`,examples:[`Ziad is charging his mobile phone with a new USB charger right now.`,`They are making a video call to their grandparents in Mansoura.`]},{title:`2. Imperatives for Online Safety (صيغة الأمر للأمان الرقمي)`,explanation:`Affirmative: Base verb ("Keep your password secret"). Negative: Don’t + base verb ("Don’t tell strangers your personal information").`,examples:[`Keep your passwords secret and tell an adult if you feel worried online.`,`Don’t make friends with people you don’t know on social networks.`]}],[{word:`laptop`,pos:`n.`,ar:`حاسب محمول / لابتوب`,def:`A computer that is portable and suitable for use while traveling.`,ex:`My sister is doing her English research project on her laptop.`,exAr:`تجري أختي بحثها في مادة اللغة الإنجليزية على حاسبها المحمول.`},{word:`tablet`,pos:`n.`,ar:`جهاز لوحي ذكي (تابلت)`,def:`A small portable computer that accepts input directly onto its screen.`,ex:`Egyptian preparatory students use tablets to access the Knowledge Bank.`,exAr:`يستخدم طلاب المرحلة الإعدادية في مصر الأجهزة اللوحية لتصفح بنك المعرفة.`},{word:`charger`,pos:`n.`,ar:`شاحن بطارية الهاتف`,def:`A device for charging a battery or battery-powered equipment.`,ex:`Can I borrow your phone charger? My battery is completely empty.`,exAr:`هل يمكنني استعارة شاحن هاتفك؟ بطاريتي فارغة تماماً.`},{word:`3D printer`,pos:`n.`,ar:`طابعة ثلاثية الأبعاد`,def:`A printer that can create physical three-dimensional objects from digital files.`,ex:`The school science club uses a 3D printer to make plastic models.`,exAr:`يستخدم نادي العلوم المدرسي طابعة ثلاثية الأبعاد لصنع مجسمات بلاستيكية.`},{word:`mouse`,pos:`n.`,ar:`فأرة التحكم بالحاسوب`,def:`A hand-held device that controls the cursor on a computer screen.`,ex:`Click the left button of the mouse to open the application.`,exAr:`انقر على الزر الأيسر للفأرة لفتح التطبيق.`},{word:`video call`,pos:`n.`,ar:`مكالمة فيديو مرئية`,def:`A phone call using an internet connection to see the person you are talking to.`,ex:`We made a video call to congratulate our uncle in Saudi Arabia.`,exAr:`أجرينا مكالمة فيديو لتهنئة عمنا في المملكة العربية السعودية.`},{word:`selfie`,pos:`n.`,ar:`صورة شخصية (سيلفي)`,def:`A photograph that one has taken of oneself with a smartphone.`,ex:`The tourists took a happy selfie in front of the Sphinx.`,exAr:`التقط السائحون صورة سيلفي سعيدة أمام تمثال أبي الهول.`},{word:`password`,pos:`n.`,ar:`كلمة مرور سرية`,def:`A secret word or phrase that must be used to gain admission to a system.`,ex:`Always choose a strong password with letters, numbers, and symbols.`,exAr:`اختر دائماً كلمة مرور قوية تحتوي على حروف وأرقام ورموز.`}],[{phrase:`charge the phone battery`,meaningAr:`يشحن بطارية الهاتف`,example:`Plug the cable into the wall to charge the phone battery.`},{phrase:`make a video call`,meaningAr:`يجري مكالمة فيديو`,example:`I will make a video call to discuss our class assignment.`},{phrase:`keep passwords secret`,meaningAr:`يحفظ كلمات المرور سراً`,example:`Good digital citizens always keep passwords secret from strangers.`}],`Modern technology has revolutionized the daily lives of Egyptian preparatory students. In contemporary classrooms, learners no longer depend exclusively on paper notebooks. Instead, they utilize portable tablets and laptops to browse the Egyptian Knowledge Bank (EKB) and complete digital quizzes. During computer studies periods, innovative teachers demonstrate how 3D printers can manufacture biological cell models in minutes. However, educational advisors remind students to balance screen time with outdoor physical exercise and to practice cybersecurity vigilantly.`,`Tamer: "What are you doing on your tablet, Nader?"
Nader: "I am designing a presentation about renewable energy for tomorrow’s science class."
Tamer: "Is the battery running low?"
Nader: "Yes, it is. I am looking for my USB charger right now."`,{dialogue:{title:`Finish the following dialogue between Ramy and Youssef about online safety:`,context:`Ramy is asking Youssef how to stay safe while using technology.`,turns:[{speaker:`Ramy`,text:`Hello Youssef! What are you doing on your laptop?`,isBlank:!1},{speaker:`Youssef`,isBlank:!0,blankNumber:1,expectedAnswer:`I am doing my English research homework.`,acceptableAnswers:[`I am doing my homework.`,`I am searching for information online.`],hintAr:`أخبره أنك تقوم بعمل واجب اللغة الإنجليزية والبحث.`},{speaker:`Ramy`,isBlank:!0,blankNumber:2,expectedAnswer:`How do you keep your online accounts safe?`,acceptableAnswers:[`What should you do to stay safe online?`,`How can we protect our passwords?`],hintAr:`اسأله كيف تحافظ على أمان حساباتك وكلمات مرورك على الإنترنت.`},{speaker:`Youssef`,text:`I always keep my passwords secret and never share them with strangers.`,isBlank:!1},{speaker:`Ramy`,text:`What should you do if an unknown person messages you?`,isBlank:!1},{speaker:`Youssef`,isBlank:!0,blankNumber:3,expectedAnswer:`You should tell your parents or a teacher immediately.`,acceptableAnswers:[`Tell an adult.`,`Don’t answer them and tell your dad.`],hintAr:`انصحه بإخبار والديه أو معلمه فوراً.`},{speaker:`Ramy`,isBlank:!0,blankNumber:4,expectedAnswer:`Can we send our personal photos to people we don’t know?`,acceptableAnswers:[`Is it safe to send photos to strangers?`],hintAr:`اسأله هل من الآمن إرسال الصور للغرباء.`},{speaker:`Youssef`,text:`No, you must never send private photos to anyone you don’t know!`,isBlank:!1},{speaker:`Ramy`,isBlank:!0,blankNumber:5,expectedAnswer:`Thank you for this valuable advice, Youssef!`,acceptableAnswers:[`Thanks for your helpful tips.`,`You are right, thank you.`],hintAr:`اشكره على هذه النصائح القيمة للأمان الرقمي.`}]},readingPassage:{title:`Reading Comprehension: Technology in Egyptian Schools`,passage:`Modern technology has revolutionized the daily lives of Egyptian preparatory students. In contemporary classrooms, learners no longer depend exclusively on paper notebooks. Instead, they utilize portable tablets and laptops to browse the Egyptian Knowledge Bank (EKB) and complete digital quizzes. During computer studies periods, innovative teachers demonstrate how 3D printers can manufacture biological cell models in minutes. However, educational advisors remind students to balance screen time with outdoor physical exercise and to practice cybersecurity vigilantly. Never share your passwords or phone number with strangers on social networks.`,mcqs:[{id:`prep1_u4_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What is the main idea of the reading passage?`,options:[`How modern technology enhances learning in Egyptian schools`,`Why computers are dangerous for everyone`,`The history of building paper factories`,`Playing video games all weekend`],correctAnswer:`A`,explanation:`The passage explores how modern technology supports Egyptian students.`,exam_trap_explanation:`Exam Trap (فخ الامتحان): Do not pick negative distractors. The passage provides a balanced, positive evaluation of modern technology in education.`},{id:`prep1_u4_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What does a 3D printer manufacture in the school science lab?`,options:[`Biological cell models in minutes`,`Paper library textbooks`,`Wooden classroom chairs`,`Sports leather footballs`],correctAnswer:`A`,explanation:`Paragraph explicitly states: 3D printers can manufacture biological cell models in minutes.`,exam_trap_explanation:`Look specifically for the item created in the science lab mentioned in the text.`},{id:`prep1_u4_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The underlined word "portable" in the text means:`,options:[`Easy to carry around and move`,`Extremely heavy and immobile`,`Made of broken glass`,`Very cheap and useless`],correctAnswer:`A`,explanation:`Portable means light and easy to transport.`,exam_trap_explanation:`Portable refers to devices like laptops and tablets that can be transported with ease.`}],openEnded:[{id:`prep1_u4_ro1`,question:`Mention two vital rules students must observe to stay safe online.`,questionAr:`اذكر قاعدتين أساسيتين يجب على الطلاب مراعاتهما للبقاء بأمان على الإنترنت.`,modelAnswer:`1) Never share passwords or private personal information with strangers. 2) Tell an adult (parents or teachers) if someone suspicious contacts you.`,rubric:`1 mark for each valid safety rule cited from the passage.`,maxMarks:2},{id:`prep1_u4_ro2`,question:`Why do educational advisors recommend balancing screen time with outdoor exercise?`,questionAr:`لماذا يوصي المستشارون التربويون بالموازنة بين وقت الشاشات وممارسة الرياضة في الهواء الطلق؟`,modelAnswer:`To ensure physical health, prevent eye strain, and encourage social interaction alongside academic digital learning.`,rubric:`Full mark for logical inference supported by the passage context.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep1_u4_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`My mobile phone is out of battery. Could you please lend me your ________?`,options:[`charger`,`curtain`,`mirror`,`carpet`],correctAnswer:`A`,explanation:`A charger is used to recharge mobile battery power.`,exam_trap_explanation:`Exam Trap (فخ الامتحان): Do not confuse charger (شاحن) with other household accessories.`},{id:`prep1_u4_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`To keep your social media account safe, always choose a strong secret ________.`,options:[`password`,`passport`,`postcard`,`paragraph`],correctAnswer:`A`,explanation:`A password secures digital accounts.`,exam_trap_explanation:`Exam Trap: Beware of similar-sounding words like passport (جواز سفر).`},{id:`prep1_u4_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Our technical club used a modern ________ to produce small plastic gear prototypes.`,options:[`3D printer`,`dishwasher`,`vacuum cleaner`,`microwave`],correctAnswer:`A`,explanation:`A 3D printer creates physical 3D objects from digital designs.`,exam_trap_explanation:`Exam Trap: 3D printer is the specialized digital manufacturing device in Prep 1 Unit 4.`},{id:`prep1_u4_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`Listen! The school band ________ a cheerful national anthem in the playground.`,options:[`is playing`,`played`,`plays`,`are play`],correctAnswer:`A`,explanation:`Keyword "Listen!" indicates an action happening right now (Present Continuous: is playing).`,exam_trap_explanation:`Exam Trap: "Listen!" triggers the Present Continuous (am/is/are + verb-ing).`},{id:`prep1_u4_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`________ tell your personal phone number or home address to strangers on the internet.`,options:[`Don’t`,`Doesn’t`,`Not`,`Aren’t`],correctAnswer:`A`,explanation:`Negative imperative begins with "Don’t + infinitive".`,exam_trap_explanation:`Exam Trap: Never use "Doesn’t" or "Not" to start a command or rule.`},{id:`prep1_u4_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Look at Hany! He ________ to the school library to borrow an encyclopedia.`,options:[`is running`,`runs`,`are running`,`ran`],correctAnswer:`A`,explanation:`Subject "He" requires singular auxiliary "is" + verb-ing with double "n" (running).`,exam_trap_explanation:`Exam Trap: Remember spelling rules: run ends in consonant-vowel-consonant, so double the n (running).`}],errorCorrection:[{id:`prep1_u4_ec1`,sentence:`Look! The students (take) a selfie in front of the pyramids.`,bracketWord:`take`,correctWord:`are taking`,explanation:`"Look!" requires Present Continuous. Plural subject "students" takes "are taking".`,exam_trap_explanation:`Exam Trap: Drop the silent -e before adding -ing (taking).`},{id:`prep1_u4_ec2`,sentence:`Ahmed is (charge) his tablet with a new white cable now.`,bracketWord:`charge`,correctWord:`charging`,explanation:`After auxiliary "is", the main verb takes -ing (charging).`,exam_trap_explanation:`Exam Trap: Auxiliary is/are must be followed by verb-ing.`},{id:`prep1_u4_ec3`,sentence:`Not (give) your secret password to anyone online.`,bracketWord:`Not give`,correctWord:`Don’t give`,explanation:`Negative imperative begins with "Don’t" followed by the base infinitive.`,exam_trap_explanation:`Exam Trap: The negative command form is always "Don’t + verb".`},{id:`prep1_u4_ec4`,sentence:`Listen! Mona (sing) a lovely traditional song.`,bracketWord:`sing`,correctWord:`is singing`,explanation:`"Listen!" signals the Present Continuous: singular subject takes "is singing".`,exam_trap_explanation:`Exam Trap: Do not omit the auxiliary verb "is".`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "Using Modern Technology Wisely"`,prompt:`Write a well-organized paragraph of 90 to 110 words about how you and your classmates use technology for study, and how to stay safe on the internet.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة حول كيفية استخدام التكنولوجيا في المذاكرة وطرق الأمان الرقمي.`,targetWords:`90 - 110 words`,guidancePoints:[`Devices you use (tablet, laptop)`,`Educational websites (EKB)`,`Safety rules (passwords, strangers)`],modelAnswer:`Modern technology plays an essential role in our educational routine. Every day, my classmates and I use portable tablets and laptops to search for scientific information on the Egyptian Knowledge Bank. We also use 3D printers in our technical workshop to build accurate geometrical models. However, technology must be used sensibly and responsibly. To stay safe online, I always keep my passwords strictly confidential and never share personal photos with strangers. If I encounter anything suspicious, I inform my parents immediately. Technology is a beneficial tool when harnessed with wisdom.`,rubricCriteria:[{criterion:`Content & Topic Relevance`,marks:3},{criterion:`Organization & Cohesive Flow`,marks:2},{criterion:`Grammar Accuracy & Tense Range`,marks:2},{criterion:`Punctuation, Capitalization & Spelling`,marks:2}]}}),i=n(7,`Prep 1`,1,5,`Holidays`,`الإجازات والرحلات والشواطئ المصرية العريقة`,`Holidays, camping, caves, waterfalls, sandcastles, souvenirs, deserts, Siwa oasis, Alexandria`,`Past Simple Tense (Regular & Irregular Verbs) and Questions with Did`,`الماضي البسيط والسؤال بـ Did`,`Use Past Simple for completed actions in the past. Regular verbs add -ed (visited, played). Irregular verbs change form (went, swam, saw). Questions: Did + subject + infinitive verb ("Did you swim in the sea? - Yes, I did").`,[{title:`1. Past Simple Form & Keywords (الماضي البسيط)`,explanation:`Keywords: yesterday, last week/month/year, in the past, ago. Negative: didn’t + bare verb ("We didn’t go to the cinema; we stayed on the beach").`,examples:[`Last summer, our family visited the stunning waterfalls at Wadi El-Rayan in Fayoum.`,`We swam in the calm sea and ate fresh grilled fish in Hurghada.`]},{title:`2. Wh- and Yes/No Questions in the Past (السؤال في الماضي)`,explanation:`Yes/No: Did + Subject + Verb? ("Did you sleep in a tent? - Yes, we did"). Wh-question: Wh-word + did + Subject + Verb? ("Where did you buy this souvenir? - In Khan el-Khalili").`,examples:[`Q: What did you see inside the deep mountain cave? — A: We saw fascinating rock formations.`,`Q: Did you build a big sandcastle on the beach? — A: Yes, we built a huge fortress!`]}],[{word:`beach`,pos:`n.`,ar:`شاطئ البحر الرملي`,def:`A strip of land covered with sand along the edge of a sea or lake.`,ex:`Children love building tall sandcastles on the golden beach in Alexandria.`,exAr:`يحب الأطفال بناء قلاع رملية عالية على الشاطئ الذهبي بالإسكندرية.`},{word:`camp`,pos:`v. / n.`,ar:`يخيم في معسكر / معسكر كشفي`,def:`Live for a time in a tent, especially while on holiday.`,ex:`Our scout troop camped near the peaceful olive groves in Siwa Oasis.`,exAr:`خيمت فرقتنا الكشفية بالقرب من بساتين الزيتون الهادئة في واحة سيوة.`},{word:`cave`,pos:`n.`,ar:`كهف جبلي طبيعي`,def:`A large natural underground chamber in a hillside or cliff.`,ex:`The hikers explored a cool stone cave in the Sinai mountains.`,exAr:`استكشف المتجولون كهفاً حجرياً بارداً في جبال سيناء.`},{word:`waterfall`,pos:`n.`,ar:`شلال مائي طبيعي متدفق`,def:`A cascade of water falling from a height.`,ex:`Wadi El-Rayan in Fayoum is famous for Egypt’s magnificent waterfalls.`,exAr:`يشتهر وادي الريان بالفيوم بشلالات مصر الطبيعية الرائعة.`},{word:`sandcastle`,pos:`n.`,ar:`قلعة رملية على الشاطئ`,def:`A model of a castle made of sand by a child on a beach.`,ex:`My little brother built a majestic sandcastle with seashell towers.`,exAr:`بنى أخي الصغير قلعة رملية مهيبة مزينة بأبراج من الأصداف.`},{word:`souvenir`,pos:`n.`,ar:`هدية تذكارية جميلة`,def:`A thing that is kept as a reminder of a person, place, or holiday.`,ex:`I bought a hand-carved alabaster pyramid as a souvenir from Luxor.`,exAr:`اشتريت هرماً من الألباستر المنحوت يدوياً كهدية تذكارية من الأقصر.`},{word:`desert`,pos:`n.`,ar:`صحراء شاسعة ورمال`,def:`A dry, barren area of land, especially one covered with sand.`,ex:`The White Desert in Egypt features extraordinary chalk rock sculptures.`,exAr:`تتميز الصحراء البيضاء في مصر بتكوينات طباشيرية صخرية مبهرة.`},{word:`jungle`,pos:`n.`,ar:`أدغال استوائية كثيفة الأشجار`,def:`An area of land overgrown with dense forest and tangled vegetation.`,ex:`Monkeys swing from tall trees in the tropical jungle.`,exAr:`تتأرجح القردة بين الأشجار العالية في الأدغال الاستوائية.`}],[{phrase:`build a sandcastle`,meaningAr:`يبني قلعة من الرمال`,example:`We built a sandcastle with four moats near the gentle waves.`},{phrase:`buy lovely souvenirs`,meaningAr:`يشتري هدايا تذكارية جميلة`,example:`Tourists buy lovely souvenirs from traditional bazaars.`},{phrase:`sleep in a tent`,meaningAr:`ينام في خيمة كشفية`,example:`During our desert safari, we slept in a cozy canvas tent under the stars.`}],`Last month, our preparatory school organized an unforgettable educational excursion to the Siwa Oasis. Located in the Western Desert, Siwa is renowned for its fresh natural springs, ancient mud-brick fortresses, and expansive palm dates groves. During the trip, we stayed in eco-friendly desert lodges and drank delicious Siwan herbal tea. In the afternoon, we climbed the Mountain of the Dead and learned how ancient Egyptians carved tombs into stone cliffs. Before returning to Cairo, every student bought traditional olive oil and embroidered shawls as souvenirs for their families.`,`Hatem: "Where did you go for your mid-year vacation, Karim?"
Karim: "We traveled to Dahab on the Red Sea coast!"
Hatem: "Did you swim in the Blue Hole?"
Karim: "Yes, I did! We saw vibrant coral reefs and magnificent marine fish."`,{dialogue:{title:`Finish the following dialogue between Hatem and Karim about their holiday:`,context:`Hatem is asking Karim about his recent family holiday to Dahab.`,turns:[{speaker:`Hatem`,text:`Hello Karim! Did you enjoy your mid-term holiday?`,isBlank:!1},{speaker:`Karim`,isBlank:!0,blankNumber:1,expectedAnswer:`Yes, I did. I had a wonderful holiday.`,acceptableAnswers:[`Yes, it was fantastic.`,`Yes, I enjoyed it very much.`],hintAr:`أجِب بالإيجاب وأخبره أن إجازتك كانت رائعة.`},{speaker:`Hatem`,isBlank:!0,blankNumber:2,expectedAnswer:`Where did you go?`,acceptableAnswers:[`Where did you travel?`,`Which city did you visit?`],hintAr:`اسأله أين ذهب أو سافر لقضاء الإجازة.`},{speaker:`Karim`,text:`We traveled to Dahab in South Sinai.`,isBlank:!1},{speaker:`Hatem`,isBlank:!0,blankNumber:3,expectedAnswer:`How did you travel there?`,acceptableAnswers:[`Did you travel by bus or by car?`,`How did you go there?`],hintAr:`اسأله عن وسيلة المواصلات التي سافر بها.`},{speaker:`Karim`,text:`We went by modern express bus.`,isBlank:!1},{speaker:`Hatem`,text:`Did you sleep in a hotel or in a tent?`,isBlank:!1},{speaker:`Karim`,isBlank:!0,blankNumber:4,expectedAnswer:`We camped in a comfortable tent on the beach.`,acceptableAnswers:[`We slept in a tent.`,`We stayed in a tent near the sea.`],hintAr:`أخبره أنكم خيمتم ونمتم في خيمة على الشاطئ.`},{speaker:`Hatem`,isBlank:!0,blankNumber:5,expectedAnswer:`What souvenirs did you buy from Dahab?`,acceptableAnswers:[`Did you buy any souvenirs?`],hintAr:`اسأله عن الهدايا التذكارية التي اشتراها.`}]},readingPassage:{title:`Reading Comprehension: An Unforgettable Trip to Siwa Oasis`,passage:`Last month, our preparatory school organized an unforgettable educational excursion to the Siwa Oasis. Located in the Western Desert, Siwa is renowned for its fresh natural springs, ancient mud-brick fortresses, and expansive palm dates groves. During the trip, we stayed in eco-friendly desert lodges and drank delicious Siwan herbal tea. In the afternoon, we climbed the Mountain of the Dead and learned how ancient Egyptians carved tombs into stone cliffs. Before returning to Cairo, every student bought traditional olive oil and embroidered shawls as souvenirs for their families.`,mcqs:[{id:`prep1_u5_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`Where is the Siwa Oasis located in Egypt?`,options:[`In the Western Desert`,`Along the Mediterranean coastline`,`In downtown Alexandria`,`Near Aswan High Dam`],correctAnswer:`A`,explanation:`Passage explicitly states: "Located in the Western Desert, Siwa is renowned..."`,exam_trap_explanation:`Exam Trap: Confirm geographic location directly in the first two sentences.`},{id:`prep1_u5_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What historical monument did the students climb during the excursion?`,options:[`The Mountain of the Dead`,`The Great Pyramid of Giza`,`The Cairo Tower`,`Qaitbay Citadel in Alexandria`],correctAnswer:`A`,explanation:`The students climbed the Mountain of the Dead and studied carved rock tombs.`,exam_trap_explanation:`Exam Trap: Don’t confuse Siwan monuments with Cairo or Giza landmarks.`},{id:`prep1_u5_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What does the word "souvenirs" refer to in the text?`,options:[`Gifts bought to remember a special place`,`Huge stone rocks in the desert`,`School exam test papers`,`Tickets for public buses`],correctAnswer:`A`,explanation:`Souvenirs are mementos or gifts kept to remember a journey.`,exam_trap_explanation:`Souvenir means هدية تذكارية.`}],openEnded:[{id:`prep1_u5_ro1`,question:`What did the students buy before returning home to Cairo?`,questionAr:`ماذا اشترى الطلاب كهدايا تذكارية قبل العودة إلى القاهرة؟`,modelAnswer:`They bought traditional Siwan olive oil and beautiful embroidered shawls as souvenirs for their families.`,rubric:`1 mark for olive oil, 1 mark for embroidered shawls.`,maxMarks:2},{id:`prep1_u5_ro2`,question:`Why do you think visiting historic oases like Siwa is valuable for young learners?`,questionAr:`في رأيك، لماذا تعد زيارة الواحات التاريخية مثل سيوة ذات قيمة كبيرة للطلاب؟`,modelAnswer:`It broadens their historical awareness, deepens pride in Egyptian heritage, and provides practical knowledge about diverse environments.`,rubric:`Full marks for any well-expressed logical answer.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep1_u5_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`Before boarding the international flight at Cairo Airport, you must show your ________.`,options:[`passport`,`sandcastle`,`cushion`,`drawer`],correctAnswer:`A`,explanation:`A passport is the official document required for air travel.`,exam_trap_explanation:`Exam Trap: Do not confuse passport (جواز سفر) with password (كلمة سر).`},{id:`prep1_u5_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`During our coastal trip, my sister bought an alabaster scarab as a ________ for her friend.`,options:[`souvenir`,`wardrobe`,`basin`,`traffic`],correctAnswer:`A`,explanation:`A souvenir is purchased to remember a trip.`,exam_trap_explanation:`Souvenir = هدية تذكارية.`},{id:`prep1_u5_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Water rushed down dramatically over the steep rocky cliff to create a magnificent ________.`,options:[`waterfall`,`curtain`,`mirror`,`sofa`],correctAnswer:`A`,explanation:`A waterfall is water flowing from a height over rocks.`,exam_trap_explanation:`Wadi El-Rayan is famed for waterfalls (شلالات).`},{id:`prep1_u5_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`Last Friday, our class ________ to the Egyptian Museum in Tahrir Square.`,options:[`went`,`go`,`goes`,`are going`],correctAnswer:`A`,explanation:`Keyword "Last Friday" indicates completed past action, so use the irregular past tense "went".`,exam_trap_explanation:`Exam Trap: Go is irregular; its past tense is "went", not "goed".`},{id:`prep1_u5_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`________ you see the ancient golden mask of King Tutankhamun during your visit?`,options:[`Did`,`Do`,`Are`,`Were`],correctAnswer:`A`,explanation:`Questions in Past Simple with a base main verb ("see") require auxiliary "Did".`,exam_trap_explanation:`Exam Trap: Never use "Were" with a bare verb like "see". Use "Did + subject + base verb".`},{id:`prep1_u5_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`We ________ swim in the lake because the water was dangerously cold.`,options:[`didn’t`,`don’t`,`aren’t`,`weren’t`],correctAnswer:`A`,explanation:`Past Simple negative with an action verb (swim) takes "didn’t".`,exam_trap_explanation:`Exam Trap: Use "didn’t" + infinitive verb for past actions.`}],errorCorrection:[{id:`prep1_u5_ec1`,sentence:`Did you (saw) the colorful coral reefs in Sharm El-Sheikh?`,bracketWord:`saw`,correctWord:`see`,explanation:`After the auxiliary "Did", the main verb MUST be in the base infinitive form (see).`,exam_trap_explanation:`Exam Trap: Did + subject + INFINITIVE (Did you see, NOT Did you saw).`},{id:`prep1_u5_ec2`,sentence:`Two days ago, I (buy) a beautiful papyrus painting in Luxor.`,bracketWord:`buy`,correctWord:`bought`,explanation:`"Two days ago" requires the Past Simple. The past of "buy" is "bought".`,exam_trap_explanation:`Exam Trap: Buy is irregular: buy -> bought.`},{id:`prep1_u5_ec3`,sentence:`We didn’t (stayed) in a hotel; we camped in a desert tent.`,bracketWord:`stayed`,correctWord:`stay`,explanation:`After "didn’t", use the bare infinitive without -ed (stay).`,exam_trap_explanation:`Exam Trap: didn’t + base infinitive.`},{id:`prep1_u5_ec4`,sentence:`Where (do) you spend your summer vacation last July?`,bracketWord:`do`,correctWord:`did`,explanation:`"Last July" requires the past auxiliary "did".`,exam_trap_explanation:`Exam Trap: Change present auxiliary "do" to past "did".`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "A Wonderful Holiday Trip in Egypt"`,prompt:`Write a paragraph of 90 to 110 words describing a memorable vacation you spent in an Egyptian city (such as Alexandria, Hurghada, or Luxor).`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة تصف رحلة إجازة رائعة قضيتها في إحدى المدن المصرية.`,targetWords:`90 - 110 words`,guidancePoints:[`Where you went and with whom`,`Activities you enjoyed (swimming, visiting sights)`,`Souvenirs you bought`],modelAnswer:`Last summer, my family and I traveled to Alexandria for a five-day vacation. We stayed in an apartment overlooking the shimmering Mediterranean Sea. Every morning, we swam in the refreshing water and built impressive sandcastles on the beach. In the afternoons, we toured the historic Qaitbay Citadel and explored the fascinating Alexandria Library. In the evenings, we strolled along the Corniche, eating delicious roasted corn and fresh ice cream. Before returning home, I bought charming seashell souvenirs for my cousins. It was truly an unforgettable holiday filled with joy and cultural discovery.`,rubricCriteria:[{criterion:`Content Relevance & Narrative Flow`,marks:3},{criterion:`Past Simple Grammar Accuracy`,marks:2},{criterion:`Holiday Lexicon & Collocations`,marks:2},{criterion:`Punctuation, Spelling & Mechanics`,marks:2}]}}),a=n(7,`Prep 1`,1,6,`Let's eat!`,`التغذية الصحية والأطعمة والوصفات المصرية اللذيذة`,`Healthy food, recipes, ingredients, cinnamon, raisins, nuts, hummus, crisps, fizzy drinks, salad`,`Countable vs. Uncountable Nouns & Quantifiers (Some, Any, Much, Many, A lot of)`,`الأسماء المعدودة وغير المعدودة ومحددات الكمية`,`Countable nouns have singular and plural forms (an apple -> apples; many apples). Uncountable nouns have only a singular form and do not take a/an (rice, sugar, milk, hummus; much sugar). Use "some" in affirmative sentences and polite offers. Use "any" in negative sentences and questions.`,[{title:`1. Countable vs. Uncountable Nouns (المعدود وغير المعدود)`,explanation:`Countable: a biscuit -> biscuits, an egg -> eggs. Uncountable: water, rice, cinnamon, cheese, juice, meat, soup. Uncountable nouns always take a singular verb ("Rice pudding is delicious").`,examples:[`There are some juicy apples in the fruit bowl on the table.`,`There is not much sugar left in the jar to make dessert.`]},{title:`2. Some vs. Any & Quantifiers (محددات الكمية)`,explanation:`Some: affirmative sentences ("We have some nuts") and polite requests ("Would you like some tea?"). Any: negative sentences ("There isn’t any milk") and general questions ("Do you have any raisins?").`,examples:[`Would you like some warm cinnamon tea with fresh mint?`,`Are there any crunchy crisps left in the kitchen cupboard?`]}],[{word:`recipe`,pos:`n.`,ar:`وصفة طهي وإعداد الطعام`,def:`A set of instructions for preparing a particular dish, including ingredients.`,ex:`My grandmother has a secret recipe for mouth-watering Egyptian rice pudding.`,exAr:`لدى جدتي وصفة سرية لإعداد أرز باللبن مصري شهي.`},{word:`ingredients`,pos:`n.`,ar:`مكونات ومقادير الأكلة`,def:`Any of the foods or substances that are combined to make a particular dish.`,ex:`Fresh milk, short-grain rice, and sugar are the essential ingredients.`,exAr:`الحليب الطازج والأرز قصير الحبة والسكر هي المكونات الأساسية.`},{word:`cinnamon`,pos:`n.`,ar:`قرفة عطرية لذيذة`,def:`An aromatic spice made from the peeled, dried bark of an Asian tree.`,ex:`Sprinkle ground cinnamon on top of the dessert for rich aroma.`,exAr:`رش القرفة المطحونة فوق الحلوى لإضفاء رائحة ونكهة زكية.`},{word:`raisins`,pos:`n.`,ar:`زبيب مجفف`,def:`A partially dried grape used in cooking, baking, and garnishing.`,ex:`We decorated the festive platter with golden raisins and toasted coconut.`,exAr:`زينا طبق الحلوى بالزبيب الذهبي وجوز الهند المحمص.`},{word:`nuts`,pos:`n.`,ar:`مكسرات وفول سوداني ومكسرات`,def:`Fruit consisting of a hard shell enclosing an edible kernel.`,ex:`Crushed almonds and hazelnuts are healthy nuts full of beneficial oils.`,exAr:`اللوز والبندق المطحونان مكسرات صحية غنية بالزيوت المفيدة.`},{word:`hummus`,pos:`n.`,ar:`حمص الشام المطحون بالطحينة`,def:`A dip made from mashed chickpeas, tahini, lemon juice, and garlic.`,ex:`Egyptian families love eating fresh baladi bread with creamy hummus dip.`,exAr:`تحب العائلات المصرية تناول الخبز البلدي الطازج مع غموس الحمص الكريمي.`},{word:`crisps`,pos:`n.`,ar:`رقائق شيبسي مقلية`,def:`Thin slices of potato fried until crisp and eaten as a snack.`,ex:`Avoid eating too many salty crisps because they contain unhealthy fats.`,exAr:`تجنب تناول الكثير من رقائق الشيبسي لأنها تحتوي على دهون غير صحية.`},{word:`fizzy drinks`,pos:`n.`,ar:`مشروبات غازية غير صحية`,def:`Carbonated sweet non-alcoholic drinks.`,ex:`Drinking water is much healthier than drinking sugary fizzy drinks.`,exAr:`شرب الماء أكثر فائدة وصحة من شرب المشروبات الغازية السكرية.`}],[{phrase:`healthy balanced diet`,meaningAr:`نظام غذائي متوازن وصحي`,example:`Eating fresh vegetables every day ensures a healthy balanced diet.`},{phrase:`sprinkle ground cinnamon`,meaningAr:`يرش القرفة المطحونة`,example:`Sprinkle ground cinnamon gently over warm baked pudding.`},{phrase:`avoid too much sugar`,meaningAr:`يتجنب الإكثار من السكر`,example:`Doctors recommend athletes avoid too much sugar before training.`}],`Maintaining a wholesome, balanced diet is the cornerstone of academic vitality for preparatory students. Nutritionists emphasize that the human body thrives on nutrient-rich foods such as fresh green salads, seasonal fruits, pulses, and lean dairy products. In Egyptian culinary tradition, dishes like koshari and lentil soup provide wholesome plant-based proteins, carbohydrates, and minerals. Conversely, consuming excessive processed snacks like salty crisps, chocolate bars, and artificial fizzy drinks causes sluggishness and dental decay. By drinking plenty of water and snacking on dried raisins and raw almonds, teenagers preserve strong immune systems and vibrant energy.`,`Omar: "What are your favorite ingredients for rice pudding, Tarek?"
Tarek: "I adore rice pudding with crushed nuts, golden raisins, and fragrant cinnamon!"
Omar: "Is there much sugar in this bowl?"
Tarek: "No, Mom only puts a little sugar to make it wholesome and healthy."`,{dialogue:{title:`Finish the following dialogue between Omar and Tarek about healthy eating:`,context:`Omar is asking Tarek about his favorite healthy snacks and recipes.`,turns:[{speaker:`Omar`,text:`Hello Tarek! What are you eating for your midday snack?`,isBlank:!1},{speaker:`Tarek`,isBlank:!0,blankNumber:1,expectedAnswer:`I am eating some fresh fruits and roasted nuts.`,acceptableAnswers:[`I am eating fresh fruit.`,`A healthy salad and nuts.`],hintAr:`أخبره أنك تتناول فواكه طازجة ومكسرات محمصة.`},{speaker:`Omar`,isBlank:!0,blankNumber:2,expectedAnswer:`Why do you prefer nuts instead of crisps?`,acceptableAnswers:[`Why don’t you eat crisps?`,`Are nuts healthier than crisps?`],hintAr:`اسأله لماذا يفضل المكسرات على الشيبسي المقلي.`},{speaker:`Tarek`,text:`Because nuts provide healthy protein and crisps contain too much salt and fat.`,isBlank:!1},{speaker:`Omar`,text:`What is your favorite traditional Egyptian dessert?`,isBlank:!1},{speaker:`Tarek`,isBlank:!0,blankNumber:3,expectedAnswer:`My favorite dessert is homemade rice pudding.`,acceptableAnswers:[`I love rice pudding.`,`Rice pudding with cinnamon.`],hintAr:`أخبره أن الحلوى المفضلة لديك هي الأرز باللبن بالقرفة.`},{speaker:`Omar`,isBlank:!0,blankNumber:4,expectedAnswer:`What ingredients do we need to make it?`,acceptableAnswers:[`What are its ingredients?`,`What do we need to cook it?`],hintAr:`اسأله عن المكونات والمقادير اللازمة لإعداده.`},{speaker:`Tarek`,text:`We need milk, rice, a little sugar, raisins, and a pinch of cinnamon.`,isBlank:!1},{speaker:`Omar`,isBlank:!0,blankNumber:5,expectedAnswer:`That sounds delicious and wholesome!`,acceptableAnswers:[`It sounds very tasty!`,`Great, thank you Tarek.`],hintAr:`عبر عن إعجابك بأن هذه الوصفة تبدو لذيذة وصحية.`}]},readingPassage:{title:`Reading Comprehension: Nutrition and Youth Vitality`,passage:`Maintaining a wholesome, balanced diet is the cornerstone of academic vitality for preparatory students. Nutritionists emphasize that the human body thrives on nutrient-rich foods such as fresh green salads, seasonal fruits, pulses, and lean dairy products. In Egyptian culinary tradition, dishes like koshari and lentil soup provide wholesome plant-based proteins, carbohydrates, and minerals. Conversely, consuming excessive processed snacks like salty crisps, chocolate bars, and artificial fizzy drinks causes sluggishness and dental decay. By drinking plenty of water and snacking on dried raisins and raw almonds, teenagers preserve strong immune systems and vibrant energy.`,mcqs:[{id:`prep1_u6_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What traditional Egyptian dishes provide wholesome plant protein according to the passage?`,options:[`Koshari and lentil soup`,`Salty potato crisps`,`Sugary fizzy sodas`,`Fried fast food burgers`],correctAnswer:`A`,explanation:`Passage mentions koshari and lentil soup as providing wholesome plant-based protein.`,exam_trap_explanation:`Exam Trap: Confirm textual evidence: "dishes like koshari and lentil soup provide wholesome plant-based proteins".`},{id:`prep1_u6_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What health problems are caused by consuming excessive sugary snacks and fizzy drinks?`,options:[`Physical sluggishness and dental decay`,`Improved memory and sharper vision`,`Strengthened heart muscles`,`Faster running athletic speed`],correctAnswer:`A`,explanation:`Passage explicitly states: "causes sluggishness and dental decay".`,exam_trap_explanation:`Exam Trap: Sluggishness (الخمول والكسل) and dental decay (تسوس الأسنان) are the direct consequences stated.`},{id:`prep1_u6_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The word "cornerstone" in paragraph 1 implies that a balanced diet is:`,options:[`An essential foundation for health`,`A useless and trivial factor`,`A very expensive luxury`,`An ancient stone wall`],correctAnswer:`A`,explanation:`Cornerstone means basic, indispensable foundation.`,exam_trap_explanation:`Cornerstone = حجر الزاوية والأساس المتين.`}],openEnded:[{id:`prep1_u6_ro1`,question:`Which natural snacks does the author recommend for teenagers seeking sustained energy?`,questionAr:`ما هي الوجبات الخفيفة الطبيعية التي يوصي بها الكاتب للحصول على طاقة مستدامة؟`,modelAnswer:`Snacking on dried raisins, raw almonds/nuts, and fresh seasonal fruits.`,rubric:`1 mark for dried raisins/fruits, 1 mark for raw almonds/nuts.`,maxMarks:2},{id:`prep1_u6_ro2`,question:`Why is drinking water superior to drinking artificial fizzy sodas?`,questionAr:`لماذا يعتبر شرب الماء أفضل بكثير من شرب المشروبات الغازية المصنعة؟`,modelAnswer:`Water hydrates the body naturally without harmful excessive refined sugars, artificial coloring, or acidic damage to teeth.`,rubric:`Full mark for logical nutritional reasoning.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep1_u6_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`Rice, milk, and sugar are the main ________ required to cook sweet rice pudding.`,options:[`ingredients`,`passports`,`chargers`,`caves`],correctAnswer:`A`,explanation:`Ingredients are the foods combined to make a dish.`,exam_trap_explanation:`Ingredients = مقادير ومكونات الأكلة.`},{id:`prep1_u6_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`We sprinkled fragrant brown ________ on top of the dessert to give it a delicious aroma.`,options:[`cinnamon`,`pavement`,`mirror`,`sofa`],correctAnswer:`A`,explanation:`Cinnamon is a sweet fragrant spice.`,exam_trap_explanation:`Cinnamon = قرفة.`},{id:`prep1_u6_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Nutritionists advise students to avoid drinking ________ because they erode tooth enamel.`,options:[`fizzy drinks`,`tap water`,`lentil soup`,`fresh milk`],correctAnswer:`A`,explanation:`Fizzy drinks are acidic and loaded with sugar.`,exam_trap_explanation:`Exam Trap: Fizzy drinks (مشروبات غازية) cause dental damage.`},{id:`prep1_u6_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`Is there ________ olive oil left in the salad dressing bottle?`,options:[`any`,`some`,`many`,`a few`],correctAnswer:`A`,explanation:`Use "any" in questions with uncountable nouns like olive oil.`,exam_trap_explanation:`Exam Trap: In standard questions, use "any", not "some".`},{id:`prep1_u6_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Would you like ________ freshly baked cinnamon biscuits with your mint tea?`,options:[`some`,`any`,`much`,`a little`],correctAnswer:`A`,explanation:`Use "some" in polite offers starting with "Would you like...".`,exam_trap_explanation:`Exam Trap: Polite offers take "some", even though they end with a question mark!`},{id:`prep1_u6_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`There is too ________ sugar in this glass of juice; it is unhealthily sweet!`,options:[`much`,`many`,`a few`,`several`],correctAnswer:`A`,explanation:`Sugar is uncountable, so use "too much".`,exam_trap_explanation:`Exam Trap: "Many" is for countable nouns (apples). Use "much" for uncountable nouns (sugar).`}],errorCorrection:[{id:`prep1_u6_ec1`,sentence:`Are there (some) raisins left in the kitchen cabinet?`,bracketWord:`some`,correctWord:`any`,explanation:`In general questions, use "any" instead of "some".`,exam_trap_explanation:`Exam Trap: Change some to any in questions.`},{id:`prep1_u6_ec2`,sentence:`There are too (much) students in the computer laboratory today.`,bracketWord:`much`,correctWord:`many`,explanation:`"Students" is a plural countable noun, so use "too many".`,exam_trap_explanation:`Exam Trap: Countable plural takes "many", NOT "much".`},{id:`prep1_u6_ec3`,sentence:`Would you like (any) warm lentil soup for dinner?`,bracketWord:`any`,correctWord:`some`,explanation:`In polite offers starting with "Would you like...", use "some".`,exam_trap_explanation:`Exam Trap: Polite offers take "some".`},{id:`prep1_u6_ec4`,sentence:`There (are) not much milk in the pitcher.`,bracketWord:`are`,correctWord:`is`,explanation:`Milk is an uncountable noun, so it takes a singular verb (is).`,exam_trap_explanation:`Exam Trap: Uncountable nouns take singular verbs (is, not are).`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "My Favorite Healthy Dish and Recipe"`,prompt:`Write a paragraph of 90 to 110 words about a nutritious Egyptian meal you like to prepare or eat, explaining its ingredients and why it is good for your body.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة حول وجبة مصرية صحية تحب تناولها أو إعدادها، موضحاً مكوناتها وفوائدها الصحية.`,targetWords:`90 - 110 words`,guidancePoints:[`Name of dish (Koshari, Lentil soup, Salad)`,`Key ingredients`,`Health benefits vs. fast food`],modelAnswer:`Eating nutritious food is vital to keep our bodies energized and minds sharp throughout the school day. My favorite healthy meal is traditional Egyptian lentil soup. To cook this comforting soup, my mother blends yellow lentils, sweet carrots, red tomatoes, and onions with aromatic spices like cumin and black pepper. We eat it hot with crunchy toasted baladi bread and fresh lemon slices. This meal is packed with plant-based protein, dietary fiber, and vitamins without any harmful artificial additives. I always prefer eating wholesome home-cooked dishes rather than buying greasy fast food.`,rubricCriteria:[{criterion:`Nutritional Content & Vocabulary Usage`,marks:3},{criterion:`Countable/Uncountable Grammar & Quantifiers`,marks:2},{criterion:`Paragraph Coherence & Sentence Linking`,marks:2},{criterion:`Punctuation, Capitalization & Spelling`,marks:2}]}}),o=n(8,`Prep 2`,1,4,`Into the past`,`في رحاب الماضي والآثار والمعابد المصرية الخالدة`,`Ancient Egypt, ruins, statues, temples, mosques, museum, protection of heritage`,`Past Continuous with When / While & Modals of Obligation (Must / Mustn’t)`,`الماضي المستمر مع While و When وأفعال الإلزام Must و Mustn’t`,`Use Past Continuous (was/were + verb-ing) for an action in progress in the past interrupted by a shorter action in Past Simple: "While I was studying, the phone rang". Use must/mustn’t for strict museum and archaeological rules: "You must protect monuments / You mustn’t touch ancient statues".`,[{title:`1. Past Continuous with While & When (الماضي المستمر مع الروابط)`,explanation:`While / As + Past Continuous, Past Simple. When + Past Simple, Past Continuous.`,examples:[`While we were walking through Karnak Temple, our tour guide explained the hieroglyphic inscriptions.`,`The students were examining ancient pottery when the bell rang.`]},{title:`2. Must & Mustn’t for Heritage Preservation (قواعد الإلزام والحظر في المتاحف)`,explanation:`Must + base verb: absolute obligation. Mustn’t + base verb: strict prohibition.`,examples:[`Visitors must follow museum instructions and stay behind security ropes.`,`You mustn’t touch ancient pharaonic statues or use flash photography.`]}],[{word:`ruins`,pos:`n.`,ar:`أطلال وبقايا أثرية`,def:`The physical remains of a building or city that has suffered destruction.`,ex:`The ancient Roman ruins in Alexandria attract historians from across the globe.`,exAr:`تجذب الأطلال الرومانية القديمة في الإسكندرية المؤرخين من كافة أنحاء العالم.`},{word:`statue`,pos:`n.`,ar:`تمثال منحوت بدقة`,def:`A carved or cast figure of a person or animal, especially life-size or larger.`,ex:`The colossal granite statue of Ramses II stands proudly in the Grand Egyptian Museum.`,exAr:`يقف تمثال رمسيس الثاني الجرانيتي الضخم بشموخ في المتحف المصري الكبير.`},{word:`temple`,pos:`n.`,ar:`معبد أثري عريق`,def:`A building devoted to the worship of a god or gods.`,ex:`Karnak Temple in Luxor is one of the largest religious complexes ever constructed.`,exAr:`يعد معبد الكرنك في الأقصر أحد أضخم المجمعات الدينية التي شيدت في التاريخ.`},{word:`mosque`,pos:`n.`,ar:`مسجد ومئذنة إسلامية`,def:`A Muslim place of worship.`,ex:`The Mosque of Sultan Hassan in Old Cairo is a masterpiece of Islamic architecture.`,exAr:`يعد مسجد السلطان حسن في القاهرة القديمة تحفة معمارية إسلامية فريدة.`},{word:`protect`,pos:`v.`,ar:`يحمي ويصون الآثار`,def:`Keep safe from harm or injury; preserve.`,ex:`Egyptians must protect their timeless cultural heritage for future generations.`,exAr:`يجب على المصريين حماية وصون تراثهم الثقافي الخالد للأجيال القادمة.`},{word:`historic`,pos:`adj.`,ar:`تاريخي وذو شأن عظيم`,def:`Famous or important in history.`,ex:`Cairo is home to historic gates and medieval minarets.`,exAr:`تضم القاهرة بوابات تاريخية ومآذن تعود للعصور الوسطى.`},{word:`ancient`,pos:`adj.`,ar:`قديم وأثري عريق`,def:`Belonging to the very distant past and no longer in existence.`,ex:`Ancient Egyptians were pioneers in medicine, mathematics, and astronomy.`,exAr:`كان المصريون القدماء رواداً في الطب والرياضيات وعلم الفلك.`},{word:`pyramid`,pos:`n.`,ar:`هرم حجري مهيب`,def:`A monumental structure with a square or triangular base and sloping sides.`,ex:`The Great Pyramid of Khufu is the sole surviving Wonder of the Ancient World.`,exAr:`هرم خوفو الأكبر هو الأثر الوحيد الباقي من عجائب العالم القديم.`}],[{phrase:`protect historic heritage`,meaningAr:`يحمي التراث التاريخي`,example:`Citizens collaborate to protect historic heritage from weathering.`},{phrase:`explore ancient temples`,meaningAr:`يستكشف المعابد القديمة`,example:`Tourists arrive in Luxor to explore ancient temples.`},{phrase:`follow museum guidelines`,meaningAr:`يتبع إرشادات المتحف`,example:`Schoolchildren must follow museum guidelines quietly.`}],`Egypt’s historical legacy is celebrated worldwide as a cradle of civilization. From the monumental Pyramids of Giza to the awe-inspiring rock temples of Abu Simbel, millions of travelers journey to Egypt to witness pharaonic ingenuity. Preserving these priceless antiquities requires dedicated conservation. When visiting archaeological sites, citizens and tourists must respect designated paths and keep areas pristine. While professional archaeologists were restoring the golden treasures in the Grand Egyptian Museum, they deployed advanced laser technology to cleanse delicate limestone carvings without causing friction.`,`Yasmine: "Where were you at ten o’clock yesterday morning, Salma?"
Salma: "I was touring the Grand Egyptian Museum with my preparatory class."
Yasmine: "What were you doing when the museum curator approached you?"
Salma: "While we were examining the King Tutankhamun gallery, he explained the royal papyrus scrolls."`,{dialogue:{title:`Finish the following dialogue between Yasmine and Salma about visiting the museum:`,context:`Yasmine is asking Salma about her educational visit to the museum.`,turns:[{speaker:`Yasmine`,text:`Hello Salma! Where did you go on your school trip yesterday?`,isBlank:!1},{speaker:`Salma`,isBlank:!0,blankNumber:1,expectedAnswer:`We went to the Grand Egyptian Museum.`,acceptableAnswers:[`We visited the Grand Egyptian Museum.`,`We went to the museum.`],hintAr:`أخبريها أنكم زرتم المتحف المصري الكبير.`},{speaker:`Yasmine`,isBlank:!0,blankNumber:2,expectedAnswer:`What did you see there?`,acceptableAnswers:[`What monuments did you see?`,`What did you admire most?`],hintAr:`اسأليها عما شاهدته داخل قاعات المتحف.`},{speaker:`Salma`,text:`We saw the colossal statue of Ramses II and King Tut’s golden treasures.`,isBlank:!1},{speaker:`Yasmine`,isBlank:!0,blankNumber:3,expectedAnswer:`What were you doing when the tour guide spoke to you?`,acceptableAnswers:[`What were you looking at when he called you?`],hintAr:`اسأليها عما كانت تفعله عندما تحدث إليهم المرشد السياحي.`},{speaker:`Salma`,text:`While we were admiring the royal chariot, he explained how it was preserved.`,isBlank:!1},{speaker:`Yasmine`,text:`Are visitors allowed to touch the ancient statues?`,isBlank:!1},{speaker:`Salma`,isBlank:!0,blankNumber:4,expectedAnswer:`No, visitors mustn’t touch any ancient monuments.`,acceptableAnswers:[`No, you must not touch them.`,`No, it is strictly forbidden.`],hintAr:`أكدي بحزم أنه يحظر لمس الآثار لحمايتها.`},{speaker:`Yasmine`,isBlank:!0,blankNumber:5,expectedAnswer:`I really hope our school organizes a visit there soon!`,acceptableAnswers:[`It sounds like a marvelous trip!`,`Thank you Salma.`],hintAr:`عبري عن أمنيتك بزيارة المتحف قريباً.`}]},readingPassage:{title:`Reading Comprehension: Safeguarding Ancient Egyptian Heritage`,passage:`Egypt’s historical legacy is celebrated worldwide as a cradle of civilization. From the monumental Pyramids of Giza to the awe-inspiring rock temples of Abu Simbel, millions of travelers journey to Egypt to witness pharaonic ingenuity. Preserving these priceless antiquities requires dedicated conservation. When visiting archaeological sites, citizens and tourists must respect designated paths and keep areas pristine. While professional archaeologists were restoring the golden treasures in the Grand Egyptian Museum, they deployed advanced laser technology to cleanse delicate limestone carvings without causing friction.`,mcqs:[{id:`prep2_u4_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What rock temples in southern Egypt are mentioned in the text?`,options:[`The rock temples of Abu Simbel`,`The Hanging Church in Cairo`,`The Citadel of Qaitbay`,`The Roman Amphitheatre`],correctAnswer:`A`,explanation:`Passage mentions: "the awe-inspiring rock temples of Abu Simbel".`,exam_trap_explanation:`Abu Simbel is the southern rock temple complex cited.`},{id:`prep2_u4_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What modern technique did archaeologists deploy to cleanse delicate limestone without damage?`,options:[`Advanced laser technology`,`Soap and chemical brushes`,`Harsh acid washing`,`Rough sandpaper polishing`],correctAnswer:`A`,explanation:`Passage explicitly states: "they deployed advanced laser technology".`,exam_trap_explanation:`Look for the scientific restoration technique mentioned in the last sentence.`},{id:`prep2_u4_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The word "pristine" in paragraph 1 means:`,options:[`Extremely clean and undamaged`,`Full of rubbish and litter`,`Very noisy and crowded`,`Broken into fragments`],correctAnswer:`A`,explanation:`Pristine means spotless, clean, and in original condition.`,exam_trap_explanation:`Pristine = نظيف ومصون في حالته الأصلية.`}],openEnded:[{id:`prep2_u4_ro1`,question:`Why must visitors stay on designated pathways when touring archaeological sites?`,questionAr:`لماذا يجب على الزائرين الالتزام بالمسارات المحددة عند زيارة المواقع الأثرية؟`,modelAnswer:`To prevent accidental erosion, avoid damaging fragile stone surfaces, and preserve antiquities for future generations.`,rubric:`1 mark for erosion prevention, 1 mark for heritage preservation.`,maxMarks:2},{id:`prep2_u4_ro2`,question:`How does modern technology assist archaeologists in preserving antiquities?`,questionAr:`كيف تساعد التكنولوجيا الحديثة علماء الآثار في صيانة وترميم القطع الأثرية؟`,modelAnswer:`Laser technology and digital scanning allow gentle cleaning and 3D modeling without damaging delicate historical materials.`,rubric:`Full marks for citing non-destructive restoration techniques.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep2_u4_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`The ancient Roman ________ in Alexandria contain broken columns and mosaics.`,options:[`ruins`,`chargers`,`passwords`,`cushions`],correctAnswer:`A`,explanation:`Ruins are the remains of ancient destroyed buildings.`,exam_trap_explanation:`Ruins = أطلال وبقايا أثرية.`},{id:`prep2_u4_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`It is our national duty to ________ Egyptian antiquities against pollution and vandalism.`,options:[`protect`,`damage`,`demolish`,`ignore`],correctAnswer:`A`,explanation:`Protect means keep safe from harm.`,exam_trap_explanation:`Protect = يحمي ويصون.`},{id:`prep2_u4_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`The towering ________ of Ramses II was carved with supreme precision from rose granite.`,options:[`statue`,`tent`,`sofa`,`ferry`],correctAnswer:`A`,explanation:`A statue is a carved figure of stone or bronze.`,exam_trap_explanation:`Colossal statue of Ramses II = تمثال رمسيس الضخم.`},{id:`prep2_u4_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`While we ________ through Luxor Temple, the heavy rain suddenly started.`,options:[`were walking`,`walked`,`are walk`,`was walking`],correctAnswer:`A`,explanation:`"While" is followed by the Past Continuous: plural "we" takes "were walking".`,exam_trap_explanation:`Exam Trap: Plural subject "we" takes "were walking", not "was walking".`},{id:`prep2_u4_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`You ________ touch the ancient glass display cases in the museum; it is forbidden!`,options:[`mustn’t`,`must`,`don’t have to`,`can`],correctAnswer:`A`,explanation:`"Mustn’t" expresses prohibition when an action is strictly forbidden.`,exam_trap_explanation:`Exam Trap: Forbidden = mustn’t (حظر وتحريم).`},{id:`prep2_u4_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`I was taking photos when the museum security guard ________ at my ticket.`,options:[`looked`,`was looking`,`were look`,`is looking`],correctAnswer:`A`,explanation:`"When" is typically followed by the Past Simple (looked) interrupting the ongoing action.`,exam_trap_explanation:`Exam Trap: When + Past Simple, while + Past Continuous.`}],errorCorrection:[{id:`prep2_u4_ec1`,sentence:`While Hany (watch) television, his father came back from work.`,bracketWord:`watch`,correctWord:`was watching`,explanation:`"While" requires the Past Continuous. Singular subject takes "was watching".`,exam_trap_explanation:`Exam Trap: While + was/were + verb-ing.`},{id:`prep2_u4_ec2`,sentence:`You (must) drop sweet wrappers on the temple floor; keep it clean!`,bracketWord:`must`,correctWord:`mustn’t`,explanation:`Context requires a prohibition against littering (mustn’t).`,exam_trap_explanation:`Exam Trap: Drop litter is forbidden, so use mustn’t.`},{id:`prep2_u4_ec3`,sentence:`They were studying ancient history when the power (go) out.`,bracketWord:`go`,correctWord:`went`,explanation:`"When" takes the Past Simple. The past of "go" is "went".`,exam_trap_explanation:`Exam Trap: Past of go is went.`},{id:`prep2_u4_ec4`,sentence:`Visitors (has to) buy an entry ticket before entering the gallery.`,bracketWord:`has to`,correctWord:`have to`,explanation:`Plural subject "Visitors" takes "have to", not "has to".`,exam_trap_explanation:`Exam Trap: Plural subject agreement: have to.`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "Protecting Egypt’s Timeless Heritage"`,prompt:`Write a paragraph of 90 to 110 words about why Egyptian antiquities are world-famous, and how school students can help preserve them.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة حول أهمية حماية الآثار المصرية ودور الطلاب في الحفاظ عليها.`,targetWords:`90 - 110 words`,guidancePoints:[`World-famous monuments (Pyramids, Karnak, GEM)`,`Economic and cultural significance`,`Rules visitors must follow`],modelAnswer:`Egypt possesses an invaluable wealth of historic monuments that embody the dawn of human civilization. Millions of international tourists visit our motherland annually to gaze at the majestic Giza Pyramids and explore the awe-inspiring temples of Luxor. These treasures not only stimulate our national economy through tourism, but also reinforce our cultural identity. As patriotic students, we must treat historic sites with deep veneration. When we tour archaeological reserves, we must never touch ancient carvings, write graffiti on stones, or drop litter. By championing heritage preservation, we ensure that Egypt’s glorious history shines bright for centuries to come.`,rubricCriteria:[{criterion:`Historical Content & Civic Pride`,marks:3},{criterion:`Modal Verbs (Must/Mustn’t) & Past Tense`,marks:2},{criterion:`Cohesion, Topic Sentence & Conclusion`,marks:2},{criterion:`Spelling, Punctuation & Mechanics`,marks:2}]}}),s=n(8,`Prep 2`,1,5,`Helping you, helping me`,`العمل الخيري والتطوعي ومساعدة ذوي الهمم والأيتام`,`Charities, donation, volunteers, disabled, kindness, orphanages, community service`,`Relative Clauses (Who, Which, Where) & Expressing Necessity (Have to / Has to)`,`ضمائر الوصل (Who, Which, Where) وأفعال الإلزام (Have to / Has to)`,`Use "who" for people ("A doctor is someone who cures patients"). Use "which" for things/animals ("A wheelchair is a device which helps disabled people move"). Use "where" for places ("An orphanage is a home where orphans live"). Use have to/has to for external rules.`,[{title:`1. Relative Pronouns: Who, Which, Where (ضمائر الوصل)`,explanation:`Who = refers to people. Which / That = refers to animals and inanimate objects. Where = refers to locations where actions happen.`,examples:[`Magdi Yacoub is the compassionate surgeon who established the Aswan Heart Centre.`,`The Resala charity is an organization which delivers warm blankets to rural families in winter.`]},{title:`2. Have to / Has to for Necessity (الإلزام والضرورة)`,explanation:`I/You/We/They + have to + verb. He/She/It + has to + verb. Negative: don’t have to / doesn’t have to.`,examples:[`Volunteers have to register their names at the youth center before joining.`,`She doesn’t have to pay for the medical surgery; the charitable foundation covers all costs.`]}],[{word:`charity`,pos:`n.`,ar:`جمعية ومؤسسة خيرية`,def:`An organization set up to provide help and raise money for those in need.`,ex:`The Egyptian Food Bank is a reputable charity that feeds vulnerable families.`,exAr:`بنك الطعام المصري جمعية خيرية موثوقة تقدم الغذاء للأسر الأكثر احتياجاً.`},{word:`donate`,pos:`v.`,ar:`يتبرع بالمال أو الملابس`,def:`Give money or goods for a good cause, for example to a charity.`,ex:`Kind citizens donate clothes and storybooks to orphanages before Eid.`,exAr:`يتبرع المواطنون الكرماء بالملابس والقصص لدور الأيتام قبل العيد.`},{word:`volunteer`,pos:`n. / v.`,ar:`متطوع للخير / يتطوع بدون أجر`,def:`A person who freely offers to take part in an enterprise or undertake a task.`,ex:`Youth volunteers painted classroom desks and planted shady trees.`,exAr:`تطوع الشباب لطلاء مقاعد الفصول وزراعة أشجار ظليلة.`},{word:`disabled`,pos:`adj.`,ar:`من ذوي الهمم والقدرات الخاصة`,def:`Having a physical or mental condition that limits movements or senses.`,ex:`Our school constructed paved ramps to facilitate access for disabled pupils.`,exAr:`أنشأت مدرستنا منحدرات ممهدة لتسهيل دخول الطلاب من ذوي الهمم.`},{word:`kindness`,pos:`n.`,ar:`إحسان وعطف ومعاملة طيبة`,def:`The quality of being friendly, generous, and considerate.`,ex:`Treating elderly neighbors with warm kindness earns divine blessings.`,exAr:`معاملة الجيران المسنين بإحسان وطيبة تجلب البركة ورضا الله.`},{word:`orphan`,pos:`n.`,ar:`طفل يتيم`,def:`A child whose parents are deceased.`,ex:`Islam and universal morals place immense virtue on caring for the orphan.`,exAr:`يحث الإسلام والأخلاق الإنسانية على رعاية وكفالة اليتيم.`},{word:`wheelchair`,pos:`n.`,ar:`كرسي متحرك لذوي الإعاقة الحركية`,def:`A chair on wheels, used when walking is difficult or impossible.`,ex:`The association gifted a modern electric wheelchair to the disabled athlete.`,exAr:`أهدت الجمعية كرسياً متحركاً كهربائياً حديثاً للبطل الرياضي من ذوي الهمم.`},{word:`community`,pos:`n.`,ar:`المجتمع المحلي والبيئة المحيطة`,def:`A group of people living in the same place or sharing common goals.`,ex:`A cohesive community thrives when members support one another.`,exAr:`يزدهر المجتمع المتماسك عندما يدعم أفراده بعضهم بعضاً.`}],[{phrase:`donate warm winter clothes`,meaningAr:`يتبرع بملابس شتوية دافئة`,example:`Students gather to donate warm winter clothes to the needy.`},{phrase:`volunteer at the children’s ward`,meaningAr:`يتطوع في جناح الأطفال بالمستشفى`,example:`Nurses volunteer at the children’s ward on public holidays.`},{phrase:`empower disabled citizens`,meaningAr:`يمكّن ذوي الهمم ويدعمهم`,example:`Modern legislation aims to empower disabled citizens in jobs.`}],`Voluntary community service is a hallmark of Egyptian social solidarity. Across governorates from Alexandria to Aswan, non-governmental charitable foundations mobilize thousands of university and preparatory students to uplift disadvantaged communities. These noble foundations build medical clinics which provide cost-free treatments to underprivileged citizens. Dedicated volunteers, who sacrifice their weekend leisure time, distribute food parcels, tutor orphans, and install clean water connections. Participating in voluntary work cultivates empathy, social cohesion, and active citizenship among youth.`,`Adel: "Where are you going with that heavy carton, Bassem?"
Bassem: "I am taking it to the local charity center which operates in our district."
Adel: "What is inside the box?"
Bassem: "Warm winter jackets which my brother and I collected for orphans."`,{dialogue:{title:`Finish the following dialogue between Adel and Bassem about voluntary charity work:`,context:`Adel is asking Bassem about his volunteer activities at the weekend.`,turns:[{speaker:`Adel`,text:`Hello Bassem! Where are you going this morning?`,isBlank:!1},{speaker:`Bassem`,isBlank:!0,blankNumber:1,expectedAnswer:`I am going to the local charity organization.`,acceptableAnswers:[`I am going to the charity center.`,`To the charity to help orphans.`],hintAr:`أخبره أنك ذاهب إلى الجمعية الخيرية بالحي.`},{speaker:`Adel`,isBlank:!0,blankNumber:2,expectedAnswer:`What do volunteers do there?`,acceptableAnswers:[`What kind of work do you do?`,`How do you help people there?`],hintAr:`اسأله عن نوع العمل التطوعي الذي يقوم به المتطوعون.`},{speaker:`Bassem`,text:`We prepare food packages and collect clothes for needy families.`,isBlank:!1},{speaker:`Adel`,isBlank:!0,blankNumber:3,expectedAnswer:`Do you have to work every day?`,acceptableAnswers:[`How many days do you volunteer?`,`Is it obligatory?`],hintAr:`اسأله هل يتعين عليه العمل كل يوم أم في عطلة نهاية الأسبوع فقط.`},{speaker:`Bassem`,text:`No, we don’t have to work every day; we only volunteer on Fridays and Saturdays.`,isBlank:!1},{speaker:`Adel`,isBlank:!0,blankNumber:4,expectedAnswer:`Can I join you as a volunteer this weekend?`,acceptableAnswers:[`Can I come with you?`,`May I volunteer too?`],hintAr:`اسأله هل يمكنك الانضمام والتطوع معه هذا الأسبوع.`},{speaker:`Bassem`,text:`Of course! We always welcome enthusiastic new volunteers.`,isBlank:!1},{speaker:`Adel`,isBlank:!0,blankNumber:5,expectedAnswer:`That is wonderful! See you on Friday morning.`,acceptableAnswers:[`Great! I will meet you on Friday.`,`Thank you Bassem!`],hintAr:`عبر عن سعادتك وحدد الموعد صباح الجمعة.`}]},readingPassage:{title:`Reading Comprehension: Social Solidarity and Youth Volunteerism`,passage:`Voluntary community service is a hallmark of Egyptian social solidarity. Across governorates from Alexandria to Aswan, non-governmental charitable foundations mobilize thousands of university and preparatory students to uplift disadvantaged communities. These noble foundations build medical clinics which provide cost-free treatments to underprivileged citizens. Dedicated volunteers, who sacrifice their weekend leisure time, distribute food parcels, tutor orphans, and install clean water connections. Participating in voluntary work cultivates empathy, social cohesion, and active citizenship among youth.`,mcqs:[{id:`prep2_u5_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What do dedicated volunteers sacrifice to help their communities?`,options:[`Their weekend leisure time`,`Their school textbooks`,`Their family homes`,`Their official identity cards`],correctAnswer:`A`,explanation:`Passage mentions: "Dedicated volunteers, who sacrifice their weekend leisure time...".`,exam_trap_explanation:`Volunteers freely give their personal free time (weekend leisure time).`},{id:`prep2_u5_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What psychological and moral virtues does volunteering cultivate in young people?`,options:[`Empathy, social cohesion, and active citizenship`,`Selfishness and arrogance`,`Greed and love of money`,`Laziness and indifference`],correctAnswer:`A`,explanation:`Passage explicitly states: "cultivates empathy, social cohesion, and active citizenship".`,exam_trap_explanation:`Look for positive moral virtues listed in the concluding sentence.`},{id:`prep2_u5_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The word "underprivileged" in the text refers to people who:`,options:[`Face financial hardship and need social support`,`Are extremely wealthy and own companies`,`Travel in luxury yachts`,`Refuse to work in charities`],correctAnswer:`A`,explanation:`Underprivileged means disadvantaged or poor.`,exam_trap_explanation:`Underprivileged = الأسر الأكثر احتياجاً والأقل حظاً.`}],openEnded:[{id:`prep2_u5_ro1`,question:`Mention two practical ways volunteers assist families in remote villages.`,questionAr:`اذكر وسيلتين عمليتين يساعد بهما المتطوعون الأسر في القرى النائية.`,modelAnswer:`1) Distributing food parcels and warm clothing. 2) Installing clean potable water connections and tutoring children.`,rubric:`1 mark for each valid charitable action cited from the text.`,maxMarks:2},{id:`prep2_u5_ro2`,question:`In your view, why is helping disabled citizens essential for a healthy society?`,questionAr:`في رأيك، لماذا تعد مساعدة ذوي الهمم أمراً أساسياً لنهضة المجتمع؟`,modelAnswer:`It guarantees equal rights, eliminates social isolation, and enables them to utilize their unique talents to contribute to national growth.`,rubric:`Full marks for logical, compassionate reasoning.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep2_u5_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`A person whose parents have died is called an ________.`,options:[`orphan`,`inventor`,`ancestor`,`archaeologist`],correctAnswer:`A`,explanation:`An orphan is a child whose parents have passed away.`,exam_trap_explanation:`Orphan = يتيم.`},{id:`prep2_u5_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`Generous people ________ money and food to charities to support the poor.`,options:[`donate`,`steal`,`waste`,`borrow`],correctAnswer:`A`,explanation:`Donate means give money or goods freely for a good cause.`,exam_trap_explanation:`Donate = يتبرع.`},{id:`prep2_u5_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Our school sports building installed smooth ramps to welcome students in ________.`,options:[`wheelchairs`,`submarines`,`helicopters`,`steamers`],correctAnswer:`A`,explanation:`Wheelchairs are used by individuals with physical mobility needs.`,exam_trap_explanation:`Wheelchairs = كراسي متحركة لذوي الهمم.`},{id:`prep2_u5_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`Dr. Magdi Yacoub is the world-renowned heart surgeon ________ established the Aswan clinic.`,options:[`who`,`which`,`where`,`when`],correctAnswer:`A`,explanation:`Use "who" for a person (surgeon).`,exam_trap_explanation:`Exam Trap: Dr. Yacoub is a person, so use "who", not "which".`},{id:`prep2_u5_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`This is the charitable foundation ________ volunteers organize food boxes every Ramadan.`,options:[`where`,`which`,`who`,`whose`],correctAnswer:`A`,explanation:`Use "where" for a place when an action occurs within it ("volunteers organize food boxes").`,exam_trap_explanation:`Exam Trap: The sentence describes an activity occurring at the location, so "where" is correct.`},{id:`prep2_u5_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Tomorrow is an official national holiday, so we ________ wake up early for school.`,options:[`don’t have to`,`mustn’t`,`has to`,`have to`],correctAnswer:`A`,explanation:`"Don’t have to" expresses lack of obligation/necessity (there is no need because it is a holiday).`,exam_trap_explanation:`Exam Trap: Lack of obligation on a holiday = don’t have to (لا داعي / لست مضطراً).`}],errorCorrection:[{id:`prep2_u5_ec1`,sentence:`A wheelchair is an assistive device (who) enables disabled individuals to move.`,bracketWord:`who`,correctWord:`which`,explanation:`"Wheelchair" is an inanimate object/device, so use "which" or "that", not "who".`,exam_trap_explanation:`Exam Trap: Inanimate objects take "which", not "who".`},{id:`prep2_u5_ec2`,sentence:`A charitable volunteer has to (helped) others with a joyful heart.`,bracketWord:`helped`,correctWord:`help`,explanation:`After "has to", use the base infinitive verb (help).`,exam_trap_explanation:`Exam Trap: Has to + infinitive.`},{id:`prep2_u5_ec3`,sentence:`This is the community school (which) my aunt teaches English.`,bracketWord:`which`,correctWord:`where`,explanation:`Teaching takes place inside the school (location of action), so use "where".`,exam_trap_explanation:`Exam Trap: Place with an action = where.`},{id:`prep2_u5_ec4`,sentence:`Do students (has to) wear their official uniform on sports day?`,bracketWord:`has to`,correctWord:`have to`,explanation:`In questions with the auxiliary "Do", use the base form "have to".`,exam_trap_explanation:`Exam Trap: Do/Does + subject + have to.`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "How Young People Can Help Their Community"`,prompt:`Write a paragraph of 90 to 110 words discussing practical voluntary activities teenagers can undertake to improve their local neighborhood and support those in need.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة حول الطرق والأنشطة التطوعية التي يمكن للشباب القيام بها لمساعدة مجتمعهم.`,targetWords:`90 - 110 words`,guidancePoints:[`Volunteering for charities`,`Helping orphans and disabled neighbors`,`Cleaning and beautifying public parks`],modelAnswer:`Serving one’s community is a noble civic duty that cultivates compassion and moral maturity among young people. There are numerous practical ways through which preparatory students can make a tangible difference in their local neighborhoods. Firstly, we can volunteer at local charities which collect food parcels and warm clothing for underprivileged families during winter. Secondly, we can assist disabled classmates by sharing class notes and carrying their schoolbags. Finally, youth can organize weekend campaigns to plant trees, paint school boundary walls, and clear plastic litter from public parks. When we unite to help others, our entire society becomes stronger, happier, and more harmonious.`,rubricCriteria:[{criterion:`Community Engagement & Ideas`,marks:3},{criterion:`Relative Pronouns & Obligation Modals`,marks:2},{criterion:`Paragraph Cohesion & Linking Markers`,marks:2},{criterion:`Spelling, Punctuation & Format`,marks:2}]}}),c=n(8,`Prep 2`,1,6,`Different environments`,`البيئات المختلفة والتغير المناخي وحماية الطبيعة`,`Environments, climate change, pollution, recycling, drought, floods, solar energy`,`Comparative and Superlative Adjectives & Equivalence with (as ... as)`,`المقارنة والتفضيل والتساوي بـ as ... as`,`Short adjectives: taller than / the tallest. Long adjectives: more dangerous than / the most dangerous. Equivalence: as + adjective + as ("Solar energy is as clean as wind power"). Negative equivalence: not as ... as.`,[{title:`1. Comparatives & Superlatives (المقارنة والتفضيل)`,explanation:`Comparative: short adj + -er + than / more + long adj + than. Superlative: the + short adj + -est / the most + long adj. Irregular: good -> better -> the best, bad -> worse -> the worst.`,examples:[`Renewable solar energy is much cleaner than burning fossil coal.`,`The Nile River is the longest river in the world, sustaining Egyptian agriculture.`]},{title:`2. Expressing Equivalence with As ... As (التساوي في الصفات)`,explanation:`As + adjective + as shows equal qualities. Not as / not so + adjective + as shows that one is less than the other.`,examples:[`Air pollution in rural countryside hamlets is not as severe as in bustling urban capitals.`,`Recycling aluminum cans is as important as saving electricity at home.`]}],[{word:`pollution`,pos:`n.`,ar:`التلوث البيئي`,def:`The presence in or introduction into the environment of a substance with harmful effects.`,ex:`Solar buses in Alexandria help diminish harmful urban air pollution.`,exAr:`تساعد حافلات النقل التي تعمل بالطاقة الشمسية بالإسكندرية في تقليل تلوث الهواء.`},{word:`drought`,pos:`n.`,ar:`جفاف قاحل وقلة الأمطار`,def:`A prolonged period of abnormally low rainfall, leading to a shortage of water.`,ex:`The severe drought in East Africa dried up rivers and threatened crops.`,exAr:`أدى الجفاف الشديد في شرق أفريقيا إلى جفاف الأنهار وتهديد المحاصيل.`},{word:`flood`,pos:`n.`,ar:`فيضان وسيول جارفة`,def:`An overflow of a large amount of water beyond its normal limits.`,ex:`Before the construction of the Aswan High Dam, the Nile flood covered farmland.`,exAr:`قبل بناء السد العالي في أسوان، كان فيضان النيل يغمر الأراضي الزراعية.`},{word:`recycle`,pos:`v.`,ar:`يعيد تدوير المخلفات`,def:`Convert waste into reusable material.`,ex:`Our school placed green bins to recycle plastic bottles and waste paper.`,exAr:`وضعت مدرستنا سلات خضراء لإعادة تدوير الزجاجات البلاستيكية والورق.`},{word:`climate change`,pos:`n.`,ar:`التغير المناخي العالمي`,def:`A long-term change in the earth’s climate, especially due to global warming.`,ex:`World nations met in Sharm El-Sheikh to discuss solutions to climate change.`,exAr:`اجتمعت دول العالم في شرم الشيخ لبحث حلول التغير المناخي.`},{word:`wildlife`,pos:`n.`,ar:`الحياة البرية والطيور النادرة`,def:`Wild animals and vegetation collectively.`,ex:`Wadi El-Gemal National Park protects endangered marine and desert wildlife.`,exAr:`تحمي محمية وادي الجمال الحياة البرية والبحرية المهددة بالانقراض.`},{word:`renewable energy`,pos:`n.`,ar:`الطاقة المتجددة النظيفة`,def:`Energy from a source that is not depleted when used, such as wind or solar power.`,ex:`The Benban Solar Park produces clean, renewable energy for millions.`,exAr:`ينتج مجمع بنبان للطاقة الشمسية طاقة نظيفة ومتجددة للملايين.`},{word:`rubbish`,pos:`n.`,ar:`قمامة ومخلفات`,def:`Waste material; refuse or litter.`,ex:`Never throw plastic rubbish into the River Nile or public canals.`,exAr:`إياك وإلقاء القمامة البلاستيكية في نهر النيل أو الترع والمجاري المائية.`}],[{phrase:`tackle climate change`,meaningAr:`يتصدى للتغير المناخي`,example:`Planting thousands of green trees helps tackle climate change.`},{phrase:`generate renewable electricity`,meaningAr:`يولّد كهرباء متجددة ونظيفة`,example:`Wind turbines in Zaafarana generate renewable electricity.`},{phrase:`recycle plastic waste`,meaningAr:`يعيد تدوير المخلفات البلاستيكية`,example:`Modern recycling factories turn plastic waste into building tiles.`}],`Global climate change represents one of the most pressing environmental challenges of the twenty-first century. Rising global temperatures cause extreme weather phenomena, including destructive coastal floods, heatwaves, and prolonged agricultural droughts. Egypt has taken decisive steps toward green transformation by championing renewable energy. Giant projects such as the Benban Solar Complex in Aswan generate electricity without greenhouse gas emissions. Furthermore, city councils encourage residents to segregate rubbish and recycle discarded plastic and glass containers. Protecting our planet begins with individual habits like conserving tap water and walking instead of driving.`,`Hesham: "Which do you think is better for our city, electric buses or diesel buses?"
Khaled: "Electric buses are far better because they are cleaner and not as noisy as diesel buses!"
Hesham: "Is renewable energy more expensive to build initially?"
Khaled: "Yes, but in the long run, it is much cheaper and safeguards our health."`,{dialogue:{title:`Finish the following dialogue between Hesham and Khaled about protecting the environment:`,context:`Hesham is asking Khaled about renewable energy and recycling in Egypt.`,turns:[{speaker:`Hesham`,text:`Hello Khaled! What article are you reading on your tablet?`,isBlank:!1},{speaker:`Khaled`,isBlank:!0,blankNumber:1,expectedAnswer:`I am reading an article about climate change and renewable energy.`,acceptableAnswers:[`An article about the environment.`,`It is about solar energy.`],hintAr:`أخبره أنك تقرأ مقالاً عن التغير المناخي والطاقة المتجددة.`},{speaker:`Hesham`,isBlank:!0,blankNumber:2,expectedAnswer:`Why is renewable energy better than burning coal?`,acceptableAnswers:[`Why is solar energy clean?`,`Is it better than fossil fuels?`],hintAr:`اسأله لماذا تعد الطاقة المتجددة أفضل من الفحم والوقود الأحفوري.`},{speaker:`Khaled`,text:`Because renewable energy does not cause greenhouse gas pollution or harm the air.`,isBlank:!1},{speaker:`Hesham`,text:`Where is Egypt’s largest solar park located?`,isBlank:!1},{speaker:`Khaled`,isBlank:!0,blankNumber:3,expectedAnswer:`It is located in Benban near Aswan.`,acceptableAnswers:[`In Benban, Aswan.`,`In southern Egypt in Aswan.`],hintAr:`أخبره أنه يقع في قرية بنبان بمحافظة أسوان.`},{speaker:`Hesham`,isBlank:!0,blankNumber:4,expectedAnswer:`How can students help protect the environment at school?`,acceptableAnswers:[`What can we do in our school?`],hintAr:`اسأله كيف يمكن للطلاب حماية البيئة داخل المدرسة.`},{speaker:`Khaled`,text:`We can recycle plastic bottles and plant more trees in the garden.`,isBlank:!1},{speaker:`Hesham`,isBlank:!0,blankNumber:5,expectedAnswer:`That is a fantastic idea! Let’s start a green club.`,acceptableAnswers:[`I totally agree with you.`,`Great idea!`],hintAr:`أثنِ على الفكرة واقترح بدء مبادرة تدوير مدرسية.`}]},readingPassage:{title:`Reading Comprehension: Climate Change and the Green Energy Revolution`,passage:`Global climate change represents one of the most pressing environmental challenges of the twenty-first century. Rising global temperatures cause extreme weather phenomena, including destructive coastal floods, heatwaves, and prolonged agricultural droughts. Egypt has taken decisive steps toward green transformation by championing renewable energy. Giant projects such as the Benban Solar Complex in Aswan generate electricity without greenhouse gas emissions. Furthermore, city councils encourage residents to segregate rubbish and recycle discarded plastic and glass containers. Protecting our planet begins with individual habits like conserving tap water and walking instead of driving.`,mcqs:[{id:`prep2_u6_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What landmark Egyptian solar project is mentioned in the passage?`,options:[`The Benban Solar Complex in Aswan`,`The High Dam hydro station`,`The Zaafarana wind farm`,`The Alexandria port station`],correctAnswer:`A`,explanation:`Passage explicitly names: "The Benban Solar Complex in Aswan".`,exam_trap_explanation:`Benban in Aswan is the premier solar energy project mentioned.`},{id:`prep2_u6_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What extreme weather phenomena are triggered by rising global temperatures?`,options:[`Destructive coastal floods, heatwaves, and droughts`,`Gentle harmless breezes and mild snow`,`Decrease in sea levels worldwide`,`Cooler summers and warmer glaciers`],correctAnswer:`A`,explanation:`Paragraph 1 mentions coastal floods, heatwaves, and prolonged agricultural droughts.`,exam_trap_explanation:`Look for the three extreme weather consequences specified in sentence 2.`},{id:`prep2_u6_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The word "segregate" in the passage means:`,options:[`Separate into different categories`,`Mix together into one heap`,`Burn with petroleum fire`,`Throw into canal water`],correctAnswer:`A`,explanation:`Segregate rubbish means separate recyclable items (plastic, glass, paper).`,exam_trap_explanation:`Segregate = يفصل ويصنف المخلفات.`}],openEnded:[{id:`prep2_u6_ro1`,question:`Mention two daily personal habits citizens can adopt to safeguard the environment.`,questionAr:`اذكر عادتين شخصيتين يوميتين يمكن للمواطنين تبنيهما لحماية البيئة.`,modelAnswer:`1) Conserving fresh tap water. 2) Walking or cycling short distances instead of driving cars, and segregating rubbish for recycling.`,rubric:`1 mark for water conservation, 1 mark for sustainable mobility / recycling.`,maxMarks:2},{id:`prep2_u6_ro2`,question:`Why is solar energy considered superior to generating power by burning coal?`,questionAr:`لماذا تعد الطاقة الشمسية متفوقة على توليد الطاقة عن طريق حرق الفحم؟`,modelAnswer:`Because solar energy is an infinite clean resource that produces no harmful carbon greenhouse emissions, protecting human respiratory health and slowing global warming.`,rubric:`Full marks for citing zero emissions and environmental protection.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep2_u6_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`When an area suffers from a severe lack of rain for months, it experiences a ________.`,options:[`drought`,`flood`,`waterfall`,`cushion`],correctAnswer:`A`,explanation:`A drought is a prolonged shortage of rain and water.`,exam_trap_explanation:`Drought (جفاف) vs. Flood (فيضان).`},{id:`prep2_u6_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`Students placed dedicated bins in the courtyard to ________ empty beverage cans.`,options:[`recycle`,`destroy`,`burn`,`ignore`],correctAnswer:`A`,explanation:`Recycle means process waste into new reusable products.`,exam_trap_explanation:`Recycle = يعيد تدوير.`},{id:`prep2_u6_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Solar and wind installations produce clean, ________ energy that never depletes.`,options:[`renewable`,`poisonous`,`unhealthy`,`polluted`],correctAnswer:`A`,explanation:`Renewable energy comes from natural sources that replenish themselves.`,exam_trap_explanation:`Renewable energy = طاقة متجددة نظيفة.`},{id:`prep2_u6_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`The Nile is ________ river in the world, stretching over 6,600 kilometers.`,options:[`the longest`,`longer than`,`longest`,`as long`],correctAnswer:`A`,explanation:`Superlative form for short adjective "long" is "the longest".`,exam_trap_explanation:`Exam Trap: Superlatives require the definite article "the": the longest.`},{id:`prep2_u6_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Cycling a bicycle to school is ________ dangerous as driving a speeding motorcycle.`,options:[`not as`,`more`,`most`,`as`],correctAnswer:`A`,explanation:`Negative equivalence structure "not as + adjective + as" indicates less danger.`,exam_trap_explanation:`Exam Trap: "not as dangerous as" means cycling is less dangerous.`},{id:`prep2_u6_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Benban solar farm is far ________ than ancient coal-fired generating plants.`,options:[`cleaner`,`clean`,`the cleanest`,`cleanest`],correctAnswer:`A`,explanation:`Comparative of "clean" followed by "than" is "cleaner".`,exam_trap_explanation:`Exam Trap: Look for "than" to trigger the comparative form (cleaner than).`}],errorCorrection:[{id:`prep2_u6_ec1`,sentence:`Solar power is (more clean) than burning heavy fuel oil.`,bracketWord:`more clean`,correctWord:`cleaner`,explanation:`"Clean" is a short one-syllable adjective; its comparative is "cleaner", not "more clean".`,exam_trap_explanation:`Exam Trap: Short adjectives take -er (cleaner, not more clean).`},{id:`prep2_u6_ec2`,sentence:`Cairo is (the bigger) city in Egypt and the Middle East.`,bracketWord:`the bigger`,correctWord:`the biggest`,explanation:`Superlative requires "-est" with double "g": the biggest.`,exam_trap_explanation:`Exam Trap: Superlative is "the biggest".`},{id:`prep2_u6_ec3`,sentence:`Plastic rubbish is as harmful (then) chemical sewage in canals.`,bracketWord:`then`,correctWord:`as`,explanation:`The equivalence structure is "as ... as", not "as ... then".`,exam_trap_explanation:`Exam Trap: as + adjective + as.`},{id:`prep2_u6_ec4`,sentence:`Air pollution in small villages is (bad) than in overcrowded city centers.`,bracketWord:`bad`,correctWord:`better`,explanation:`Air in small villages is cleaner/better than in cities. Comparative of good is better.`,exam_trap_explanation:`Exam Trap: In context of air quality, rural air is cleaner/better.`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "Protecting Our Environment from Pollution"`,prompt:`Write a paragraph of 90 to 110 words about what causes environmental pollution, and how young citizens can help make Egypt cleaner and greener.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة حول أسباب التلوث البيئي وكيفية جعل مصر بيئة أنظف وأكثر خضرة.`,targetWords:`90 - 110 words`,guidancePoints:[`Sources of pollution (plastic waste, car smoke)`,`Renewable energy (solar, wind)`,`Role of recycling and planting trees`],modelAnswer:`Protecting the environment is one of the most critical responsibilities facing our generation. Today, environmental pollution threatens human health and wildlife through toxic factory smoke, vehicle exhaust, and plastic discarded in canals. To combat this grave challenge, Egypt is investing in magnificent green energy projects such as the Benban Solar Park. However, environmental preservation also demands individual citizen action. We must stop throwing single-use plastic bottles into the Nile and start recycling our household waste. Furthermore, planting trees along school streets purifies the air and creates lovely shade. If every student adopts sustainable habits, we can safeguard Egypt’s natural beauty forever.`,rubricCriteria:[{criterion:`Ecological Awareness & Content`,marks:3},{criterion:`Comparative & Superlative Structures`,marks:2},{criterion:`Cohesion, Topic Sentence & Flow`,marks:2},{criterion:`Punctuation, Spelling & Grammar`,marks:2}]}}),l=n(9,`Prep 3`,1,4,`Have you ever traveled by plane?`,`تجارب السفر والمغامرات الحياتية والرياضات المائية`,`Life experiences, flying, airports, festivals, snorkeling, concerts, adventurous journeys`,`Present Perfect Tense with Ever, Never, Already, and Yet`,`المضارع التام مع ever و never و already و yet`,`Use Present Perfect (have/has + past participle) for past experiences connected to the present without a specific past time. Use "ever" in questions ("Have you ever snorkeled?"). Use "never" in negative sentences without not ("I have never seen a shark"). Use "yet" in negative sentences and questions at the end. Use "already" for actions completed sooner than expected.`,[{title:`1. Present Perfect with Ever & Never (خبرات وتجارب الحياة)`,explanation:`Form: Subject + have/has + P.P. "Ever" is used in questions asking about life experience. "Never" expresses negative experience without using "not".`,examples:[`Have you ever flown on an airplane from Cairo International Airport?`,`Nader has never climbed a mountain, but he has snorkeled in Dahab.`]},{title:`2. Already vs. Yet (Already و Yet في المضارع التام)`,explanation:`"Already" emphasizes that something happened before now. "Yet" is placed at the end of negative statements and questions.`,examples:[`We have already booked our flight tickets to Hurghada online.`,`The international passengers haven’t boarded the airplane yet.`]}],[{word:`snorkel`,pos:`v. / n.`,ar:`يسبح بأنبوب تنفس وغطس سطحي`,def:`Swim underwater while breathing through a tube called a snorkel.`,ex:`Tourists snorkel along the vibrant coral reefs of Ras Mohammed in Sharm.`,exAr:`يسبح السائحون بأنبوب التنفس السطحي بين الشعاب المرجانية في رأس محمد.`},{word:`festival`,pos:`n.`,ar:`مهرجان واحتفال شعبي وثقافي`,def:`A day or period of celebration, typically for religious or cultural reasons.`,ex:`The Ismailia International Folklore Festival welcomes dance troupes from around the world.`,exAr:`يستقبل مهرجان الإسماعيلية الدولي للفنون الشعبية فرقاً راقصة من شتى أنحاء العالم.`},{word:`airport`,pos:`n.`,ar:`مطار دولي للسفر الجوي`,def:`A complex of runways and buildings for the take-off, landing, and maintenance of aircraft.`,ex:`Sphinx International Airport welcomes flights to western Giza.`,exAr:`يستقبل مطار سفنكس الدولي رحلات الطيران إلى غرب الجيزة.`},{word:`concert`,pos:`n.`,ar:`حفل موسيقي غنائي راقٍ`,def:`A musical performance given in public, typically by several performers.`,ex:`The Egyptian Philharmonic Orchestra performed a dazzling concert at the Opera House.`,exAr:`قدمت أوركسترا دار الأوبرا المصرية حفلاً موسيقياً مبهراً.`},{word:`experience`,pos:`n. / v.`,ar:`تجربة وخبرة حياتية ثرية`,def:`Practical contact with and observation of facts or events.`,ex:`Scuba diving with friendly dolphins was the most thrilling experience of my youth.`,exAr:`كان الغوص مع الدلافين الأليفة أكثر التجارب إثارة في حياتي.`},{word:`tent`,pos:`n.`,ar:`خيمة سفاري مجهزة`,def:`A portable shelter made of cloth, supported by one or more poles.`,ex:`Bedouin guides pitched our secure canvas tent in the desert valley.`,exAr:`نصب المرشدون البدو خيمتنا القماشية في الوادي الصحراوي.`},{word:`passport`,pos:`n.`,ar:`جواز سفر رسمي`,def:`An official document issued by a government certifying identity and citizenship.`,ex:`The passport control officer stamped my passport with an entry visa.`,exAr:`ختم ضابط مراقبة الجوازات وثيقة سفري بتأشيرة الدخول.`},{word:`luggage`,pos:`n.`,ar:`حقائب وأمتعة السفر`,def:`Suitcases or other bags in which to pack personal belongings for traveling.`,ex:`Passengers checked their luggage at the airline departure desk.`,exAr:`قام المسافرون بوزن وتسليم حقائبهم في صالة المغادرة.`}],[{phrase:`fly on an airplane`,meaningAr:`يسافر على متن طائرة`,example:`I have never flown on an airplane across the Mediterranean Sea.`},{phrase:`snorkel in the Red Sea`,meaningAr:`يغطس بأنبوب تنفس في البحر الأحمر`,example:`Students snorkel in the Red Sea to study marine biology.`},{phrase:`attend a folklore festival`,meaningAr:`يحضر مهرجاناً للفنون الشعبية`,example:`We attended an international folklore festival in Luxor.`}],`Traveling introduces young individuals to diverse civilizations, broadening intellectual horizons beyond textbooks. In Egypt, countless preparatory students embark on domestic journeys to witness natural wonders firsthand. Many teenagers have already snorkeled among exotic coral reefs in Marsa Alam, while others have experienced camping under starry skies in the White Desert. However, traveling also demands personal discipline. Navigating airports, managing luggage, and respecting local customs instill maturity. Whether boarding a local railway train or flying on a jumbo jet, travel transforms character and builds lifelong friendships.`,`Sherif: "Have you ever traveled by airplane, Mazen?"
Mazen: "No, I have never flown, but I have already traveled to Luxor by sleeper train!"
Sherif: "Have you ever snorkeled in the Red Sea?"
Mazen: "Yes! I went snorkeling in Hurghada last July and saw magnificent sea turtles."`,{dialogue:{title:`Finish the following dialogue between Sherif and Mazen about travel experiences:`,context:`Sherif is interviewing Mazen about exciting adventures and journeys he has experienced.`,turns:[{speaker:`Sherif`,text:`Hello Mazen! Have you ever traveled outside your hometown?`,isBlank:!1},{speaker:`Mazen`,isBlank:!0,blankNumber:1,expectedAnswer:`Yes, I have. I have visited several cities in Egypt.`,acceptableAnswers:[`Yes, I have traveled to Alexandria and Sinai.`,`Yes, I have.`],hintAr:`أخبره بالإيجاب وأنك زرت مدناً مصرية عدة.`},{speaker:`Sherif`,isBlank:!0,blankNumber:2,expectedAnswer:`Have you ever traveled by airplane?`,acceptableAnswers:[`Have you ever flown on a plane?`,`Did you travel by plane?`],hintAr:`اسأله هل سافر من قبل على متن طائرة.`},{speaker:`Mazen`,text:`No, I have never traveled by airplane, but I have traveled by sleeper train.`,isBlank:!1},{speaker:`Sherif`,isBlank:!0,blankNumber:3,expectedAnswer:`Where did you take the sleeper train to?`,acceptableAnswers:[`Where did you go on the train?`,`Which city did you visit?`],hintAr:`اسأله إلى أي مدينة سافر بالقطار.`},{speaker:`Mazen`,text:`We took the train all the way to Aswan to see the High Dam and Philae Temple.`,isBlank:!1},{speaker:`Sherif`,text:`Have you ever tried water sports like snorkeling?`,isBlank:!1},{speaker:`Mazen`,isBlank:!0,blankNumber:4,expectedAnswer:`Yes, I have already tried snorkeling in Hurghada.`,acceptableAnswers:[`Yes, I have snorkeled in the Red Sea.`,`Yes, I have.`],hintAr:`أخبره أنك مارست الغطس السطحي بأنبوب التنفس في الغردقة.`},{speaker:`Sherif`,isBlank:!0,blankNumber:5,expectedAnswer:`What an adventurous experience!`,acceptableAnswers:[`That sounds wonderful!`,`You are very lucky.`],hintAr:`عبر عن إعجابك بهذه المغامرة الحياتية الشيقة.`}]},readingPassage:{title:`Reading Comprehension: Broadening Horizons Through Travel`,passage:`Traveling introduces young individuals to diverse civilizations, broadening intellectual horizons beyond textbooks. In Egypt, countless preparatory students embark on domestic journeys to witness natural wonders firsthand. Many teenagers have already snorkeled among exotic coral reefs in Marsa Alam, while others have experienced camping under starry skies in the White Desert. However, traveling also demands personal discipline. Navigating airports, managing luggage, and respecting local customs instill maturity. Whether boarding a local railway train or flying on a jumbo jet, travel transforms character and builds lifelong friendships.`,mcqs:[{id:`prep3_u4_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What benefits does traveling offer to young learners according to the passage?`,options:[`Broadening intellectual horizons and building maturity`,`Making students forget their mother tongue`,`Encouraging them to skip school lessons`,`Spending all their money on sweets`],correctAnswer:`A`,explanation:`Passage mentions: "broadening intellectual horizons beyond textbooks" and "instill maturity".`,exam_trap_explanation:`Look for positive developmental virtues cited in the first sentence.`},{id:`prep3_u4_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`Where did Egyptian students camp under starry skies according to the text?`,options:[`In the White Desert`,`In downtown Cairo hotels`,`At Giza railway station`,`Inside an airport hangar`],correctAnswer:`A`,explanation:`Passage mentions: "camping under starry skies in the White Desert".`,exam_trap_explanation:`The White Desert is the camping destination specified in the text.`},{id:`prep3_u4_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The word "exotic" in paragraph 1 means:`,options:[`Strikingly colorful, rare, and fascinating`,`Very ugly and dangerous`,`Extremely cheap and broken`,`Common and uninteresting`],correctAnswer:`A`,explanation:`Exotic means unusual, colourful, and attractive from distant waters.`,exam_trap_explanation:`Exotic = جذاب، فريد، وغير مألوف.`}],openEnded:[{id:`prep3_u4_ro1`,question:`Mention two practical responsibilities travelers must handle when journeying abroad.`,questionAr:`اذكر مسؤوليتين عمليتين يجب على المسافرين إدارتهما عند السفر.`,modelAnswer:`1) Navigating airport terminals and safely managing personal luggage. 2) Respecting indigenous local customs and cultures.`,rubric:`1 mark for airport/luggage management, 1 mark for respecting customs.`,maxMarks:2},{id:`prep3_u4_ro2`,question:`How does exploring natural wonders in Egypt deepen students’ patriotism?`,questionAr:`كيف يعمق استكشاف العجائب الطبيعية في مصر من الانتماء الوطني لدى الطلاب؟`,modelAnswer:`By experiencing the scenic beauty, ancient heritage, and unique geography of Egypt firsthand, students develop profound pride in their homeland.`,rubric:`Full marks for any logical patriotic reflection.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep3_u4_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`We put on our masks and breathing tubes to ________ among the vibrant coral reefs.`,options:[`snorkel`,`climb`,`skate`,`cook`],correctAnswer:`A`,explanation:`Snorkel means swim with a breathing tube near the surface.`,exam_trap_explanation:`Snorkel = يسبح بأنبوب تنفس سطحي.`},{id:`prep3_u4_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`Thousands of music lovers gathered at Cairo Opera House to attend the symphony ________.`,options:[`concert`,`passport`,`luggage`,`tent`],correctAnswer:`A`,explanation:`A concert is a musical performance given in public.`,exam_trap_explanation:`Concert = حفل موسيقي غنائي.`},{id:`prep3_u4_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Before passing through customs at the airport, you must collect your heavy ________.`,options:[`luggage`,`recipes`,`cushions`,`droughts`],correctAnswer:`A`,explanation:`Luggage refers to travel bags and suitcases.`,exam_trap_explanation:`Luggage = حقائب وأمتعة السفر (اسم غير معدود).`},{id:`prep3_u4_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`Have you ________ flown in a helicopter over the River Nile?`,options:[`ever`,`never`,`yet`,`since`],correctAnswer:`A`,explanation:`In Present Perfect questions asking about life experience, use "ever".`,exam_trap_explanation:`Exam Trap: Questions about life experience use "ever", not "never".`},{id:`prep3_u4_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Hany has ________ seen the Red Sea; this will be his very first coastal trip!`,options:[`never`,`ever`,`yet`,`already`],correctAnswer:`A`,explanation:`The sentence means he has zero experience up to now, so use "never".`,exam_trap_explanation:`Exam Trap: "Never" provides a negative meaning without the word "not".`},{id:`prep3_u4_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`The train has not arrived at Alexandria station ________; we are still waiting.`,options:[`yet`,`already`,`ever`,`never`],correctAnswer:`A`,explanation:`Negative Present Perfect sentences ending with a time adverb take "yet".`,exam_trap_explanation:`Exam Trap: "Yet" comes at the end of negative sentences and questions.`}],errorCorrection:[{id:`prep3_u4_ec1`,sentence:`Have you ever (see) a wild dolphin while swimming in Hurghada?`,bracketWord:`see`,correctWord:`seen`,explanation:`In the Present Perfect, "have + subject" must be followed by the Past Participle (seen).`,exam_trap_explanation:`Exam Trap: Irregular verb P.P.: see -> saw -> seen.`},{id:`prep3_u4_ec2`,sentence:`Dina has already (finish) packing her travel suitcases for tomorrow.`,bracketWord:`finish`,correctWord:`finished`,explanation:`After "has already", use the past participle form (finished).`,exam_trap_explanation:`Exam Trap: Has + P.P. (finished).`},{id:`prep3_u4_ec3`,sentence:`I have never (eat) sushi before in my life.`,bracketWord:`eat`,correctWord:`eaten`,explanation:`After "have never", use the past participle (eaten).`,exam_trap_explanation:`Exam Trap: eat -> ate -> eaten.`},{id:`prep3_u4_ec4`,sentence:`Has the flight landed at Cairo Airport (already)?`,bracketWord:`already`,correctWord:`yet`,explanation:`Questions asking if an expected event has occurred by now end with "yet".`,exam_trap_explanation:`Exam Trap: Questions about expected events take "yet" at the end.`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "An Exciting Journey I Have Experienced"`,prompt:`Write a paragraph of 90 to 110 words describing an adventurous journey or trip you have taken with your school or family in Egypt.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة تصف رحلة أو مغامرة شيقة قمت بها مع مدرستك أو عائلتك.`,targetWords:`90 - 110 words`,guidancePoints:[`Destination and how you traveled`,`Activities you tried (snorkeling, camping, visiting monuments)`,`How the journey impacted you`],modelAnswer:`Traveling across Egypt’s diverse governorates offers exhilarating life experiences that remain etched in memory. Last mid-year vacation, my family and I traveled to the coastal resort of Dahab in South Sinai. It was my very first time camping in a canvas tent directly beside the turquoise Red Sea waters. During the trip, I snorkeled at the famous Blue Hole, where I marveled at vibrant coral gardens and rare butterflyfish. We also took a sunset camel ride across the sandy desert valleys. This voyage taught me to appreciate nature and deepened my confidence. I eagerly anticipate exploring more of Egypt’s wonders soon.`,rubricCriteria:[{criterion:`Adventure Narrative & Detail`,marks:3},{criterion:`Present Perfect & Past Tense Mastery`,marks:2},{criterion:`Sentence Connectors & Paragraph Flow`,marks:2},{criterion:`Spelling, Punctuation & Mechanics`,marks:2}]}}),u=n(9,`Prep 3`,1,5,`Young role models`,`القدوة ونماذج الشباب المبتكرين والعلماء العباقرة`,`Role models, innovators, app designers, champions, tournaments, chess, programming`,`Present Perfect with Since & For vs. Past Simple`,`المضارع التام مع Since و For والفرق بينه وبين الماضي البسيط`,`Use "since" with a specific starting point in time (since 2018, since last week, since 7 o’clock, since he was young). Use "for" with a duration of time (for five years, for two hours, for a long time). Past Simple is used for finished actions with a definite past time.`,[{title:`1. Since vs. For with Present Perfect (Since و For في المضارع التام)`,explanation:`Since + starting point (since Monday, since 2020, since childhood). For + period of time (for 3 days, for 6 years, for a decade).`,examples:[`Fatma has studied artificial intelligence since she was twelve years old.`,`Egyptian young software engineers have won international coding tournaments for three consecutive years.`]},{title:`2. Present Perfect vs. Past Simple (الفرق بين المضارع التام والماضي البسيط)`,explanation:`Present Perfect: action started in the past and continues, or has a present result. Past Simple: action finished at a specific past time ("He graduated in 2022").`,examples:[`Zaki has designed three award-winning mobile educational apps so far.`,`He won the national informatics olympiad last December in Cairo.`]}],[{word:`champion`,pos:`n.`,ar:`بطل رياضي أو علمي متوج`,def:`A person who has defeated all rivals in a competition.`,ex:`Hana Goda is an inspiring young Egyptian table tennis champion.`,exAr:`هنا جودة بطلة مصرية شابة وملهمة في تنس الطاولة.`},{word:`tournament`,pos:`n.`,ar:`بطولة ومنافسة رسمية`,def:`A series of contests between a number of competitors, competing for an overall prize.`,ex:`Our school football squad qualified for the national preparatory tournament.`,exAr:`تأهل فريق مدرستنا لكرة القدم للمنافسة في البطولة الإعدادية القومية.`},{word:`genius`,pos:`n.`,ar:`عبقري وفذ استثنائي`,def:`Exceptional intellectual or creative power or other natural ability.`,ex:`The young Egyptian software engineer was hailed as a computer programming genius.`,exAr:`أُشيد بمهندس البرمجيات المصري الشاب كعبقري في برمجة الحواسيب.`},{word:`app designer`,pos:`n.`,ar:`مصمم تطبيقات الهواتف الذكية`,def:`A professional who creates software applications for mobile devices.`,ex:`An ambitious teenage app designer created an app helping blind students read.`,exAr:`ابتكر مصمم تطبيقات شاب تطبيقاً ذكياً يساعد الطلاب المكفوفين على القراءة.`},{word:`competition`,pos:`n.`,ar:`مسابقة وتنافس علمي`,def:`An event or contest in which people compete against one another.`,ex:`Over five hundred innovative students entered the Young Scientist competition.`,exAr:`شارك أكثر من خمسمائة طالب مبتكر في مسابقة العالم الشاب.`},{word:`innovate`,pos:`v.`,ar:`يبتكر ويجدد الأفكار`,def:`Make changes in something established, especially by introducing new methods.`,ex:`Egyptian youth innovate smart irrigation devices to save agricultural water.`,exAr:`يبتكر الشباب المصريون أجهزة ري ذكية لتوفير المياه الزراعية.`},{word:`inspire`,pos:`v.`,ar:`يلهم ويحفز الآخرين للنجاح`,def:`Fill someone with the urge or ability to do or feel something creative.`,ex:`Stories of triumphant Paralympians inspire millions to overcome difficulties.`,exAr:`تلهم قصص أبطال البارالمبياد الملايين للتغلب على الصعاب.`},{word:`award`,pos:`n. / v.`,ar:`جائزة ووسام تقدير / يمنح جائزة`,def:`A prize or other mark of recognition given in honor of an achievement.`,ex:`The Minister of Education presented the gold medal award to the top students.`,exAr:`سلّم وزير التربية والتعليم جائزة الميدالية الذهبية للطلاب المتفوقين.`}],[{phrase:`win an international tournament`,meaningAr:`يفوز ببطولة دولية`,example:`Egyptian squash stars win international tournaments with pride.`},{phrase:`design a mobile application`,meaningAr:`يصمم تطبيقاً للهواتف الذكية`,example:`Young students design mobile applications to solve community problems.`},{phrase:`serve as an inspiring role model`,meaningAr:`يمثل قدوة ملهمة للجميع`,example:`Dr. Mostafa El-Sayed serves as an inspiring role model for Arab youth.`}],`Across the Arab Republic of Egypt, ambitious young innovators and sports champions are setting brilliant benchmarks of excellence. From robotics prodigies designing solar-powered irrigation pumps to table tennis prodigies conquering international championships, young Egyptians demonstrate boundless potential. Many of these role models have practiced their disciplines since early childhood. Through perseverance, they transform challenges into victories. For example, several teenage software app designers have created assistive tools that empower disabled learners in Egyptian schools. Their triumphant achievements demonstrate that age is never a barrier to making transformative societal contributions.`,`Nour: "Who is your role model, Zeinab?"
Zeinab: "Fatma Ali, the young Egyptian scientist who designed a water purification device."
Nour: "How long has she worked on this environmental invention?"
Zeinab: "She has developed it for three years, and she won first prize in 2025!"`,{dialogue:{title:`Finish the following dialogue between Nour and Zeinab about young role models:`,context:`Nour and Zeinab are discussing inspiring Egyptian teenagers who achieved national distinction.`,turns:[{speaker:`Nour`,text:`Hello Zeinab! Have you read about the Egyptian Science Fair winners?`,isBlank:!1},{speaker:`Zeinab`,isBlank:!0,blankNumber:1,expectedAnswer:`Yes, I have. The young inventors were truly inspiring.`,acceptableAnswers:[`Yes, I have read about them.`,`Yes, they are amazing!`],hintAr:`أخبريها بأنك قرأت عنهم وأنهم كانوا ملهمين بحق.`},{speaker:`Nour`,isBlank:!0,blankNumber:2,expectedAnswer:`Who was your favorite young role model in the competition?`,acceptableAnswers:[`Who inspired you most?`,`Which innovator did you like?`],hintAr:`اسأليها عن نموذج القدوة الشاب المفضل لديها في المسابقة.`},{speaker:`Zeinab`,text:`My favorite was Kareem, a 15-year-old app designer who built a learning tool for deaf children.`,isBlank:!1},{speaker:`Nour`,isBlank:!0,blankNumber:3,expectedAnswer:`How long has he been coding applications?`,acceptableAnswers:[`How long has he worked on coding?`,`When did he start coding?`],hintAr:`اسأليها منذ متى وهو يبرمج التطبيقات الذكية.`},{speaker:`Zeinab`,text:`He has practiced computer programming since he was ten years old.`,isBlank:!1},{speaker:`Nour`,text:`Did he win an official medal for his invention?`,isBlank:!1},{speaker:`Zeinab`,isBlank:!0,blankNumber:4,expectedAnswer:`Yes, he won the Ministry Innovation Gold Award last month.`,acceptableAnswers:[`Yes, he won first prize.`,`Yes, he did.`],hintAr:`أكدي فوزه بجائزة الابتكار الذهبية من الوزارة الشهر الماضي.`},{speaker:`Nour`,isBlank:!0,blankNumber:5,expectedAnswer:`He is truly an exceptional role model for all Egyptian students!`,acceptableAnswers:[`What a genius!`,`I am very proud of him.`],hintAr:`عبري عن فخرك بأنه قدوة رائعة لجميع الطلاب.`}]},readingPassage:{title:`Reading Comprehension: Young Egyptian Pioneers Shaping Tomorrow`,passage:`Across the Arab Republic of Egypt, ambitious young innovators and sports champions are setting brilliant benchmarks of excellence. From robotics prodigies designing solar-powered irrigation pumps to table tennis prodigies conquering international championships, young Egyptians demonstrate boundless potential. Many of these role models have practiced their disciplines since early childhood. Through perseverance, they transform challenges into victories. For example, several teenage software app designers have created assistive tools that empower disabled learners in Egyptian schools. Their triumphant achievements demonstrate that age is never a barrier to making transformative societal contributions.`,mcqs:[{id:`prep3_u5_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What assistive innovations have teenage software designers created?`,options:[`Digital tools that empower disabled learners in schools`,`Video games about car racing`,`Commercial advertising billboards`,`Fast food delivery websites`],correctAnswer:`A`,explanation:`Passage mentions: "created assistive tools that empower disabled learners in Egyptian schools".`,exam_trap_explanation:`Look for assistive tools designed for disabled learners.`},{id:`prep3_u5_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What fundamental truth do these young achievers demonstrate to the world?`,options:[`Age is never a barrier to making transformative societal contributions`,`Only adult professors can solve scientific problems`,`Sports are more important than science education`,`Success requires wealth and family connections`],correctAnswer:`A`,explanation:`Concluded clearly: "Their triumphant achievements demonstrate that age is never a barrier...".`,exam_trap_explanation:`Age is never a barrier = العمر ليس عائقاً أمام الإنجاز.`},{id:`prep3_u5_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The word "prodigies" in paragraph 1 refers to young people who:`,options:[`Possess exceptional natural talent and genius`,`Refuse to study or attend tournaments`,`Always arrive late for examinations`,`Live in foreign countries forever`],correctAnswer:`A`,explanation:`Prodigy means a young person endowed with exceptional abilities.`,exam_trap_explanation:`Prodigy = معجزة، نابغة، عبقري في سن مبكرة.`}],openEnded:[{id:`prep3_u5_ro1`,question:`Mention two fields where young Egyptians have excelled on the world stage.`,questionAr:`اذكر مجالين تميز فيهما الشباب المصريون على الساحة العالمية.`,modelAnswer:`1) Robotics, programming, and solar engineering. 2) International sports championships (such as squash and table tennis).`,rubric:`1 mark for science/robotics, 1 mark for international sports.`,maxMarks:2},{id:`prep3_u5_ro2`,question:`What qualities must a young person cultivate to achieve lasting success?`,questionAr:`ما هي الصفات التي يجب أن يتحلى بها الشاب لتحقيق نجاح دائم ومستمر؟`,modelAnswer:`Perseverance, discipline, continuous self-education, passion, and a genuine desire to serve society.`,rubric:`Full marks for citing perseverance and moral dedication.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep3_u5_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`Hana Goda won the gold medal in the African table tennis ________.`,options:[`tournament`,`passport`,`luggage`,`recipe`],correctAnswer:`A`,explanation:`A tournament is an official sporting contest.`,exam_trap_explanation:`Tournament = بطولة رياضية.`},{id:`prep3_u5_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`The teenage software developer created a smartphone ________ that translates sign language.`,options:[`app`,`statue`,`temple`,`cave`],correctAnswer:`A`,explanation:`App is short for application software.`,exam_trap_explanation:`App = تطبيق برمجي للهواتف الذكية.`},{id:`prep3_u5_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Because of his extraordinary mathematical abilities, the boy was described as a young ________.`,options:[`genius`,`beggar`,`passenger`,`tourist`],correctAnswer:`A`,explanation:`A genius has exceptional intellectual ability.`,exam_trap_explanation:`Genius = عبقري وفذ.`},{id:`prep3_u5_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`Youssef has played chess for Egypt ________ he was seven years old.`,options:[`since`,`for`,`ago`,`in`],correctAnswer:`A`,explanation:`Use "since" with a past starting clause ("he was seven years old").`,exam_trap_explanation:`Exam Trap: Clause with past simple takes "since", not "for".`},{id:`prep3_u5_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`The young engineers have developed this solar water pump ________ three years.`,options:[`for`,`since`,`already`,`ever`],correctAnswer:`A`,explanation:`"Three years" is a period/duration of time, so use "for".`,exam_trap_explanation:`Exam Trap: Duration of time (3 years) takes "for". Starting point takes "since".`},{id:`prep3_u5_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`The robotics club ________ the national first prize in Cairo last month.`,options:[`won`,`has won`,`wins`,`is winning`],correctAnswer:`A`,explanation:`Specific past time indicator "last month" requires the Past Simple (won).`,exam_trap_explanation:`Exam Trap: Definite past time (last month) forbids Present Perfect. Use Past Simple (won).`}],errorCorrection:[{id:`prep3_u5_ec1`,sentence:`Tamer has lived in Ismailia (for) 2015.`,bracketWord:`for`,correctWord:`since`,explanation:`"2015" is a specific starting point year, so use "since", not "for".`,exam_trap_explanation:`Exam Trap: Specific year takes "since".`},{id:`prep3_u5_ec2`,sentence:`Noura has practiced rhythmic gymnastics (since) five years.`,bracketWord:`since`,correctWord:`for`,explanation:`"Five years" is a duration of time, so use "for", not "since".`,exam_trap_explanation:`Exam Trap: Duration of years takes "for".`},{id:`prep3_u5_ec3`,sentence:`In 2024, our school team (has won) the robotics trophy in Cairo.`,bracketWord:`has won`,correctWord:`won`,explanation:`"In 2024" indicates a completed past event; use Past Simple (won).`,exam_trap_explanation:`Exam Trap: Finished past year takes Past Simple.`},{id:`prep3_u5_ec4`,sentence:`How long (do) you studied English at this preparatory school?`,bracketWord:`do`,correctWord:`have`,explanation:`"How long" with past participle "studied" requires auxiliary "have" for Present Perfect.`,exam_trap_explanation:`Exam Trap: How long have you studied.`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "A Young Role Model I Greatly Admire"`,prompt:`Write a paragraph of 90 to 110 words about an inspiring young Egyptian role model (in sports, science, or technology) who has achieved distinction and helped others.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة حول شخصية شابة مصرية ملهمة تعتبرها قدوة لك في الرياضة أو العلوم.`,targetWords:`90 - 110 words`,guidancePoints:[`Who the role model is`,`What they achieved and how long they worked`,`Why they inspire you`],modelAnswer:`Having an inspiring role model motivates teenagers to strive for excellence and serve their community with pride. The young person I admire most is Hana Goda, the phenomenal Egyptian table tennis champion. She began training passionately at the tender age of four and has practiced tirelessly for over nine years. Through her sheer discipline and mental resilience, she has conquered numerous African and international championships, becoming the youngest player to top the world under-fifteen rankings. What inspires me most about Hana is her modesty, sportsmanship, and dedication to her school studies alongside sports. She proves that with perseverance, young Egyptians can reach the pinnacle of global achievement.`,rubricCriteria:[{criterion:`Inspirational Content & Biography`,marks:3},{criterion:`Present Perfect (Since/For) & Past Simple Accuracy`,marks:2},{criterion:`Lexical Richness & Paragraph Flow`,marks:2},{criterion:`Spelling, Punctuation & Format`,marks:2}]}}),d=n(9,`Prep 3`,1,6,`What's the matter?`,`الصحة النفسية ومواجهة التنمر الإلكتروني والمشاعر الإنسانية`,`Mental health, feelings, cyberbullying, anxiety, supportive, embarrassment, empathy`,`Modal Verbs of Deduction & Advice: Should, Must, Might, Can’t`,`أفعال الاستنتاج والنصيحة (Should, Must, Might, Can’t)`,`Must (sure something is true: "He must be proud"). Can’t (sure something is impossible: "She can’t be asleep; her lights are on"). Might (uncertain: "They might come later"). Should / Shouldn’t (advice: "You should talk to a counselor / You shouldn’t reply to cyberbullies").`,[{title:`1. Modals of Deduction in the Present (أفعال الاستنتاج في المضارع)`,explanation:`Must + infinitive: 99% sure it is true. Can’t + infinitive: 99% sure it is impossible. Might + infinitive: possible, not sure (maybe).`,examples:[`Ziad won first prize in mathematics; he must be extremely thrilled!`,`Salma can’t be at school right now; today is an official Friday holiday.`]},{title:`2. Should / Shouldn’t for Digital Wellbeing & Advice (النصيحة ومواجهة التنمر)`,explanation:`Should + base verb: good idea to do. Shouldn’t + base verb: harmful to do.`,examples:[`If you experience online cyberbullying, you should tell your parents or school social worker immediately.`,`You shouldn’t post hurtful comments or spread unverified rumors on social media.`]}],[{word:`cyberbullying`,pos:`n.`,ar:`التنمر والمضايقة الإلكترونية`,def:`The use of electronic communication to bully or intimidate a person.`,ex:`Schools enforce strict anti-cyberbullying policies to protect teenagers.`,exAr:`تطبق المدارس سياسات صارمة لمكافحة التنمر الإلكتروني لحماية المراهقين.`},{word:`anxious`,pos:`adj.`,ar:`قلق ومتوتر بشأن المستقبل`,def:`Experiencing worry, unease, or nervousness, typically about an imminent event.`,ex:`Students often feel slightly anxious before the final preparatory board exams.`,exAr:`غالباً ما يشعر الطلاب ببعض القلق والتوتر قبل امتحانات الشهادة الإعدادية.`},{word:`embarrassing`,pos:`adj.`,ar:`مسبب للحرج والارتباك`,def:`Causing someone to feel awkward, self-conscious, or ashamed.`,ex:`Tripping on the school stage was an embarrassing moment, but everyone laughed kindly.`,exAr:`كان التعثر على مسرح المدرسة موقفاً محرجاً، لكن الجميع تبسم بلطف.`},{word:`supportive`,pos:`adj.`,ar:`داعم ومساند ومشجع للآخرين`,def:`Providing encouragement or emotional help.`,ex:`Teachers and parents are deeply supportive when pupils face learning hurdles.`,exAr:`يقدم المعلمون وأولياء الأمور دعماً وتشجيعاً كبيراً عندما يواجه الطلاب صعوبات.`},{word:`mental health`,pos:`n.`,ar:`الصحة النفسية والاتزان العاطفي`,def:`A person’s condition with regard to their psychological and emotional well-being.`,ex:`Practicing sports, getting sufficient sleep, and talking to friends promote sound mental health.`,exAr:`ممارسة الرياضة والنوم الكافي والحديث مع الأصدقاء يعزز الصحة النفسية السليمة.`},{word:`empathy`,pos:`n.`,ar:`التعاطف والشعور بآلام الآخرين`,def:`The ability to understand and share the feelings of another.`,ex:`Showing empathy toward grieving classmates cements true friendship.`,exAr:`إظهار التعاطف مع الزملاء الحزانى يوثق عرى الصداقة الحقيقية.`},{word:`upset`,pos:`adj.`,ar:`منزعج ومحبط وحزين`,def:`Unhappy, disappointed, or worried.`,ex:`Tarek was upset because his football team lost the championship match.`,exAr:`كان طارق منزعجاً ومحبطاً لأن فريقه خسر المباراة النهائية.`},{word:`breathe`,pos:`v.`,ar:`يتنفس بهدوء وعمق للاسترخاء`,def:`Take air into the lungs and expel it.`,ex:`When you feel tense, take a pause and breathe slowly and deeply.`,exAr:`عندما تشعر بالتوتر، توقف قليلاً وتنفس ببطء وعمق.`}],[{phrase:`tackle online cyberbullying`,meaningAr:`يتصدى للتنمر الإلكتروني`,example:`Youth must know how to block bullies and tackle online cyberbullying.`},{phrase:`promote sound mental health`,meaningAr:`يعزز الصحة النفسية السليمة`,example:`Regular exercise and balanced sleep promote sound mental health.`},{phrase:`express heartfelt empathy`,meaningAr:`يعبر عن تعاطف صادق`,example:`Good friends express heartfelt empathy when someone feels down.`}],`Mental and emotional wellbeing is just as crucial as physical fitness for teenagers navigating the preparatory years. Academic expectations, physical transformations, and social pressures can occasionally cause feelings of anxiety or self-doubt. In the modern digital age, the scourge of cyberbullying on social media networks poses an additional challenge. Educational experts stress that students must never suffer in silence. If you encounter cruel messages or malicious comments online, you should block the perpetrators and confide in a trusted adult or school social worker. Cultivating empathy, practicing mindfulness, and sustaining honest friendships foster emotional resilience and happiness.`,`Layla: "What’s the matter, Mariam? You look worried and pale."
Mariam: "Someone sent a cruel, anonymous comment on my social media photo."
Layla: "You shouldn’t respond to them! Block the account and show it to your mother right away."
Mariam: "You are right. Talking to someone supportive makes me feel much calmer."`,{dialogue:{title:`Finish the following dialogue between Layla and Mariam about handling online stress:`,context:`Layla notices that Mariam looks upset after receiving an unpleasant message online.`,turns:[{speaker:`Layla`,text:`Hello Mariam! What’s the matter? You look very upset.`,isBlank:!1},{speaker:`Mariam`,isBlank:!0,blankNumber:1,expectedAnswer:`Someone wrote a mean, hurtful comment on my online photo.`,acceptableAnswers:[`I received a bad message online.`,`Someone is cyberbullying me.`],hintAr:`أخبريها أن شخصاً كتب تعليقاً مسيئاً ومحرجاً على صورتك.`},{speaker:`Layla`,isBlank:!0,blankNumber:2,expectedAnswer:`Did you reply to that rude person?`,acceptableAnswers:[`Did you answer them?`,`What did you do?`],hintAr:`اسأليها هل ردت على هذا الشخص المسيء.`},{speaker:`Mariam`,text:`No, I haven’t replied yet, but I feel very anxious and embarrassed.`,isBlank:!1},{speaker:`Layla`,isBlank:!0,blankNumber:3,expectedAnswer:`You shouldn’t reply to bullies; you should block their account immediately.`,acceptableAnswers:[`Don’t reply and block them.`,`You should block them.`],hintAr:`انصحيها بألا ترد وأن تقوم بحظر الحساب فوراً.`},{speaker:`Mariam`,text:`Who should I talk to about this problem?`,isBlank:!1},{speaker:`Layla`,isBlank:!0,blankNumber:4,expectedAnswer:`You should tell your parents or the school social worker.`,acceptableAnswers:[`Tell your mom or our teacher.`,`Talk to a trusted adult.`],hintAr:`انصحيها بإخبار والديها أو الأخصائي الاجتماعي بالمدرسة.`},{speaker:`Mariam`,isBlank:!0,blankNumber:5,expectedAnswer:`Thank you for being so supportive and kind, Layla!`,acceptableAnswers:[`Thanks for your great advice!`,`You are a true friend.`],hintAr:`اشكريها على مساندتها ودعمها النفسي الرائع.`}]},readingPassage:{title:`Reading Comprehension: Safeguarding Mental Wellbeing in the Digital Era`,passage:`Mental and emotional wellbeing is just as crucial as physical fitness for teenagers navigating the preparatory years. Academic expectations, physical transformations, and social pressures can occasionally cause feelings of anxiety or self-doubt. In the modern digital age, the scourge of cyberbullying on social media networks poses an additional challenge. Educational experts stress that students must never suffer in silence. If you encounter cruel messages or malicious comments online, you should block the perpetrators and confide in a trusted adult or school social worker. Cultivating empathy, practicing mindfulness, and sustaining honest friendships foster emotional resilience and happiness.`,mcqs:[{id:`prep3_u6_rq1`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`What is just as crucial as physical fitness for teenagers according to the text?`,options:[`Mental and emotional wellbeing`,`Owning expensive brand smartphones`,`Watching television all evening`,`Winning computer gaming contests`],correctAnswer:`A`,explanation:`Passage begins: "Mental and emotional wellbeing is just as crucial as physical fitness...".`,exam_trap_explanation:`First sentence equates mental wellbeing with physical health.`},{id:`prep3_u6_rq2`,skill:`Reading`,question_type:`mcq`,difficulty:`hots`,question:`What immediate steps should a student take when encountering cyberbullying online?`,options:[`Block the perpetrator and confide in a trusted adult`,`Reply with angry rude messages`,`Delete all school homework files`,`Refuse to eat food or sleep`],correctAnswer:`A`,explanation:`Passage instructs: "block the perpetrators and confide in a trusted adult or school social worker".`,exam_trap_explanation:`Blocking the bully and informing adults is the safe, responsible advice.`},{id:`prep3_u6_rq3`,skill:`Reading`,question_type:`mcq`,difficulty:`standard`,question:`The word "perpetrators" in paragraph 1 refers to people who:`,options:[`Commit harmful or bullying actions against others`,`Work as doctors in hospitals`,`Win gold medals in sports tournaments`,`Plant trees in community parks`],correctAnswer:`A`,explanation:`Perpetrator means someone who commits an offensive or harmful act.`,exam_trap_explanation:`Perpetrators = مرتكبو الأفعال المؤذية والمتنمرون.`}],openEnded:[{id:`prep3_u6_ro1`,question:`Mention two daily habits that foster emotional resilience and happiness in teenagers.`,questionAr:`اذكر عادتين يوميتين تعززان الصلابة النفسية والسعادة لدى المراهقين.`,modelAnswer:`1) Cultivating empathy and practicing deep breathing/mindfulness. 2) Sustaining honest, supportive friendships and getting adequate rest.`,rubric:`1 mark for empathy/mindfulness, 1 mark for supportive friendships.`,maxMarks:2},{id:`prep3_u6_ro2`,question:`Why do educational experts urge students to "never suffer in silence"?`,questionAr:`لماذا يشدد الخبراء التربويون على ضرورة ألا يعاني الطلاب في صمت؟`,modelAnswer:`Because sharing worries with trusted parents or counselors provides immediate emotional relief, prevents depression, and allows adults to intervene against cyberbullies.`,rubric:`Full marks for highlighting the benefits of seeking help and intervention.`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep3_u6_vg1`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`Sending cruel or threatening messages on social media to intimidate others is called ________.`,options:[`cyberbullying`,`recycling`,`snorkeling`,`cinnamon`],correctAnswer:`A`,explanation:`Cyberbullying is bullying via digital communication.`,exam_trap_explanation:`Cyberbullying = التنمر الإلكتروني.`},{id:`prep3_u6_vg2`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`standard`,question:`True friends are always ________ when you face difficult challenges or feel sad.`,options:[`supportive`,`cruel`,`embarrassing`,`anxious`],correctAnswer:`A`,explanation:`Supportive means offering encouragement and emotional backing.`,exam_trap_explanation:`Supportive = داعم ومساند.`},{id:`prep3_u6_vg3`,skill:`Vocabulary`,question_type:`mcq`,difficulty:`hots`,question:`Having the capacity to understand and share the emotional feelings of others is called ________.`,options:[`empathy`,`drought`,`ferry`,`monument`],correctAnswer:`A`,explanation:`Empathy is the ability to share another person’s feelings.`,exam_trap_explanation:`Empathy = التعاطف والمشاركة الوجدانية.`},{id:`prep3_u6_vg4`,skill:`Grammar`,question_type:`mcq`,difficulty:`standard`,question:`If someone sends you a spiteful message online, you ________ tell your parents immediately.`,options:[`should`,`shouldn’t`,`mustn’t`,`can’t`],correctAnswer:`A`,explanation:`"Should" is used to give wise advice (you should tell an adult).`,exam_trap_explanation:`Exam Trap: It is strongly recommended to inform parents, so use "should".`},{id:`prep3_u6_vg5`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Hatem studied diligently day and night and scored 100%; he ________ be delighted!`,options:[`must`,`can’t`,`might`,`shouldn’t`],correctAnswer:`A`,explanation:`Deduction of strong certainty: scoring 100% means he is definitely delighted (must be).`,exam_trap_explanation:`Exam Trap: Certainty that something is true = "must + infinitive".`},{id:`prep3_u6_vg6`,skill:`Grammar`,question_type:`mcq`,difficulty:`hots`,question:`Noha ________ be in Cairo today; I saw her boarding the early morning train to Aswan.`,options:[`can’t`,`must`,`might`,`should`],correctAnswer:`A`,explanation:`Deduction of impossibility: seeing her on the train to Aswan means she cannot be in Cairo (can’t be).`,exam_trap_explanation:`Exam Trap: Deduction that something is impossible = "can’t + infinitive".`}],errorCorrection:[{id:`prep3_u6_ec1`,sentence:`You (should) reply to angry cyberbullies; block them instead.`,bracketWord:`should`,correctWord:`shouldn’t`,explanation:`It is bad advice to reply to bullies, so use the negative "shouldn’t".`,exam_trap_explanation:`Exam Trap: Replying to bullies escalates harassment, so use shouldn’t.`},{id:`prep3_u6_ec2`,sentence:`Ali has not slept for 24 hours; he (can’t) be exhausted.`,bracketWord:`can’t`,correctWord:`must`,explanation:`Not sleeping for 24 hours makes exhaustion a certainty (must be).`,exam_trap_explanation:`Exam Trap: Logical certainty = must be exhausted.`},{id:`prep3_u6_ec3`,sentence:`When you feel nervous, take a deep breath to (felt) calmer.`,bracketWord:`felt`,correctWord:`feel`,explanation:`After the infinitive marker "to", use the base verb "feel".`,exam_trap_explanation:`Exam Trap: to + base verb (feel).`},{id:`prep3_u6_ec4`,sentence:`They (must) be asleep; all their bedroom lights are still brightly lit.`,bracketWord:`must`,correctWord:`can’t`,explanation:`If the lights are brightly lit, it is impossible that they are asleep (can’t be).`,exam_trap_explanation:`Exam Trap: Deduction of impossibility = can’t.`}],writingTask:{type:`paragraph`,title:`A paragraph of 90-110 words about: "How to Stand Up Against Cyberbullying"`,prompt:`Write a paragraph of 90 to 110 words about the dangers of cyberbullying on social media and what steps teenagers should take to protect their emotional wellbeing.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمة حول مخاطر التنمر الإلكتروني وكيفية تصدي المراهقين له وحماية سلامتهم النفسية.`,targetWords:`90 - 110 words`,guidancePoints:[`What cyberbullying is`,`Rules to protect yourself (blocking, not replying)`,`The importance of talking to supportive parents or teachers`],modelAnswer:`Cyberbullying has emerged as a detrimental hazard affecting the mental wellbeing of many teenagers today. It occurs when malicious individuals use social media networks to circulate hurtful comments, untruthful rumors, or embarrassing pictures. To combat this menace, students must adhere to clear digital guidelines. Firstly, you should never retaliate with angry replies, as this only encourages the bully. Secondly, you must immediately block the offensive account and save screenshots as evidence. Most importantly, teenagers should never suffer in silence. Always confide in your parents or the school social worker. By showing empathy and mutual support, we can create a compassionate digital environment.`,rubricCriteria:[{criterion:`Emotional Wellness & Digital Safety Concepts`,marks:3},{criterion:`Modal Verbs (Should/Must/Can’t) Accuracy`,marks:2},{criterion:`Cohesion, Topic Progression & Conclusion`,marks:2},{criterion:`Punctuation, Spelling & Sentence Mechanics`,marks:2}]}});function f(e,t,n,r,i,a,o,s,c,l,u,d,f,p,m){let h=d[0]||{word:`community`,ar:`مجتمع`,def:`a group of people living in the same place`,ex:`We must help our community.`,exAr:`يجب أن نساعد مجتمعنا.`},g=d[1]||{word:`volunteer`,ar:`متطوع`,def:`a person who works for free to help others`,ex:`He is a volunteer at the hospital.`,exAr:`هو متطوع في المستشفى.`},_=d[2]||{word:`proud`,ar:`فخور`,def:`feeling pleased about achievements`,ex:`Parents are proud of their children.`,exAr:`الآباء فخورون بأبنائهم.`},v=f[0]||{phrase:`do voluntary work`,meaningAr:`يقوم بعمل تطوعي`,example:`They do voluntary work every weekend.`};f[1];let y={dialogue:{title:`Finish the following dialogue about ${i}:`,context:`Two Egyptian prep students are discussing ${i.toLowerCase()} and school activities.`,turns:[{speaker:`Hazem`,text:`Hello, Omar! What are you learning about in Unit ${r}?`,isBlank:!1},{speaker:`Omar`,isBlank:!0,blankNumber:1,expectedAnswer:`We are learning about ${i.toLowerCase()}.`,acceptableAnswers:[`We're studying ${i}.`,`It is about ${i}.`,`I'm reading about ${i}.`],hintAr:`أخبره بما تدرسونه في هذه الوحدة (${a})`},{speaker:`Hazem`,text:`That sounds interesting! What does the word "${h.word}" mean?`,isBlank:!1},{speaker:`Omar`,isBlank:!0,blankNumber:2,expectedAnswer:`It means "${h.ar}" in Arabic.`,acceptableAnswers:[`It means ${h.ar}.`,`It means ${h.def}.`,`It means to help others.`],hintAr:`وضح معنى الكلمة بالعربية: ${h.ar}`},{speaker:`Hazem`,isBlank:!0,blankNumber:3,expectedAnswer:`How can we practice this in our daily life?`,acceptableAnswers:[`What should we do?`,`How do you apply it?`,`Can you give an example?`],hintAr:`اسأل سؤالاً عن كيفية التطبيق العملي`},{speaker:`Omar`,text:`We can ${v.phrase} and support our teachers and classmates.`,isBlank:!1},{speaker:`Hazem`,text:`Do you think studying hard makes our parents proud?`,isBlank:!1},{speaker:`Omar`,isBlank:!0,blankNumber:4,expectedAnswer:`Yes, of course, they feel very proud of us.`,acceptableAnswers:[`Yes, absolutely.`,`Yes, they do.`,`Certainly, they are proud.`],hintAr:`أجب بالإيجاب مؤكداً شعور الفخر`},{speaker:`Hazem`,isBlank:!0,blankNumber:5,expectedAnswer:`Thank you for sharing this inspiring information with me.`,acceptableAnswers:[`Thanks a lot!`,`Good luck with your studies.`,`Great, let us study together.`],hintAr:`عبّر عن الشكر أو تمني التوفيق`}]},readingPassage:{title:`${i}: Official Comprehension Text`,passage:p,mcqs:[{id:`prep_g${e}_u${r}_r_mcq1`,skill:`Reading`,difficulty:`standard`,question:`What is the general main idea of this reading passage?`,options:[`Avoiding all extracurricular responsibilities at school`,`Understanding the fundamental concepts of ${i} and its societal value`,`Focusing purely on entertainment without academic effort`,`Traveling abroad without planning or preparation`],correctAnswer:`B`,explanation:`The passage explores the core theme of ${i} and practical life lessons.`,exam_trap_explanation:`Examiners look for the holistic theme rather than isolated narrative details.`,verificationStatus:`verified`},{id:`prep_g${e}_u${r}_r_mcq2`,skill:`Reading`,difficulty:`hots`,question:`In the passage, the word "${h.word}" contextually refers to:`,options:[`a sudden negative outcome`,`an impossible educational challenge`,h.def,`a temporary disagreement between peers`],correctAnswer:`C`,explanation:`"${h.word}" is defined as: ${h.def}.`,exam_trap_explanation:`Contextual synonym questions in Prep exams demand finding the standard lexical definition rather than colloquial usage.`,verificationStatus:`verified`},{id:`prep_g${e}_u${r}_r_mcq3`,skill:`Reading`,difficulty:`standard`,question:`According to the text, how do successful students achieve their goals?`,options:[`By ignoring teacher guidance and studying alone`,`By relying solely on last-minute memorization`,`By postponing homework until the final week`,`By being persistent, disciplined, and practicing ${v.phrase}`],correctAnswer:`D`,explanation:`The text highlights consistency, ethical diligence, and collaboration.`,exam_trap_explanation:`Avoid distractors that contain negative or passive study habits.`,verificationStatus:`verified`}],openEnded:[{id:`prep_g${e}_u${r}_r_oe1`,question:`Infer from the passage: Why is "${h.word}" regarded as essential for Egyptian prep students?`,questionAr:`استنتج من النص: لماذا يُعد مفهوم (${h.ar}) ضرورياً لطلاب المرحلة الإعدادية في مصر؟`,modelAnswer:`It fosters personal responsibility, cooperative problem-solving, and civic commitment within the school and wider community.`,rubric:`Relevance to text (1 Mark) · Grammatical and lexical correctness (1 Mark)`,maxMarks:2},{id:`prep_g${e}_u${r}_r_oe2`,question:`Suggest a suitable alternative title for the reading passage, providing your rationale.`,questionAr:`اقترح عنواناً مناسباً آخر للنص القرائي مع ذكر السبب بإيجاز.`,modelAnswer:`A suitable title is "Pathways to Excellence in ${i}", because the text focuses on diligence, moral character, and purposeful learning.`,rubric:`Appropriate title (1 Mark) · Valid logical reason (1 Mark)`,maxMarks:2}]},vocabGrammarMcqs:[{id:`prep_g${e}_u${r}_mcq1`,skill:`Vocabulary`,difficulty:`standard`,question:`The term "${h.word}" means ____________ in Arabic.`,options:[h.ar,`إهمال متعمد`,`مغامرة خطيرة`,`خسارة مادية`],correctAnswer:`A`,explanation:`"${h.word}" corresponds directly to "${h.ar}".`,exam_trap_explanation:`Beware of distractors that sound similar in Arabic but have completely unrelated meanings.`,verificationStatus:`verified`},{id:`prep_g${e}_u${r}_mcq2`,skill:`Vocabulary`,difficulty:`standard`,question:`Which word is defined as: "${g.def}"?`,options:[`nuisance`,g.word,`critic`,`pessimist`],correctAnswer:`B`,explanation:`"${g.word}" is defined as ${g.def}.`,exam_trap_explanation:`Always verify the core definition provided in the New Hello Student Book.`,verificationStatus:`verified`},{id:`prep_g${e}_u${r}_mcq3`,skill:`Vocabulary`,difficulty:`hots`,question:`Which academic collocation accurately completes: "Students should always ____________"?`,options:[`break basic rules`,`lose their textbooks`,v.phrase,`quarrel constantly`],correctAnswer:`C`,explanation:`"${v.phrase}" is the official MOE target collocation for this unit.`,exam_trap_explanation:`Collocation questions test natural word partnerships; verbs cannot be arbitrarily interchanged.`,verificationStatus:`verified`},{id:`prep_g${e}_u${r}_mcq4`,skill:`Grammar`,difficulty:`standard`,question:`Identify the grammatically correct sentence illustrating: ${s}:`,options:[`He don’t complete his homework.`,`They was finishing yesterday.`,`She have completed two book.`,u[0]?.examples[0]||`He always completes his homework on time.`],correctAnswer:`D`,explanation:`Follows the target grammar rule: ${u[0]?.explanation}`,exam_trap_explanation:`Watch for subject-verb agreement pitfalls like "he don’t" or auxiliary confusion.`,verificationStatus:`verified`},{id:`prep_g${e}_u${r}_mcq5`,skill:`Grammar`,difficulty:`hots`,question:`Choose the correct form according to Egyptian Ministry specifications:`,options:[u[0]?.examples[1]||`We are looking forward to achieving high scores.`,`We looking forward achieve high scores.`,`We look forward achieve score.`,`We are looked forward achieving.`],correctAnswer:`A`,explanation:`Follows proper tense, verb complementation, and structural rules.`,exam_trap_explanation:`Ministry examinations frequently test verbs followed by gerunds or specific prepositions.`,verificationStatus:`verified`},{id:`prep_g${e}_u${r}_mcq6`,skill:`Grammar`,difficulty:`hots`,question:`In a ministerial dialogue question, which answer structure is fully accurate?`,options:[`Yes, I does because it good.`,u[1]?.examples[0]||`Yes, I usually do because it benefits everyone.`,`No, he didn’t went to school.`,`Because she are very intelligent.`],correctAnswer:`B`,explanation:`Maintains consistent tense and auxiliary verb alignment.`,exam_trap_explanation:`Remember that "didn’t" must be followed by infinitive, and third-person pronouns require singular verbs.`,verificationStatus:`verified`}],errorCorrection:[{id:`prep_g${e}_u${r}_err1`,sentence:`He (not like) waking up late on school mornings.`,bracketWord:`not like`,correctWord:`doesn't like`,explanation:`In the present simple with singular subject "he", negative form is "doesn't + infinitive".`,explanationAr:`مع المفرد الغائب (He) يُنفى المضارع البسيط باستخدام doesn't + المصدر.`,exam_trap_explanation:`Do not write "don’t like" or "isn’t like".`},{id:`prep_g${e}_u${r}_err2`,sentence:`They are keen on (read) informative historical articles.`,bracketWord:`read`,correctWord:`reading`,explanation:`Prepositions such as "on", "in", "at", and "about" are followed by the verb-ing (gerund).`,explanationAr:`حروف الجر يتبعها دائماً اسم أو فعل مضاف له -ing.`,exam_trap_explanation:`Students frequently forget to add -ing after prepositions like "keen on".`},{id:`prep_g${e}_u${r}_err3`,sentence:`How (many) water do you drink during summer days?`,bracketWord:`many`,correctWord:`much`,explanation:`Water is an uncountable noun, so we ask about its quantity using "How much", not "How many".`,explanationAr:`الماء اسم لا يُعد وبالتالي نستخدم How much وليس How many.`,exam_trap_explanation:`Remember: "How many" is strictly for countable plural nouns.`},{id:`prep_g${e}_u${r}_err4`,sentence:`Yesterday, Omar (go) to the Cairo International Book Fair.`,bracketWord:`go`,correctWord:`went`,explanation:`"Yesterday" is an explicit time marker signaling the past simple tense, so the irregular past of "go" is "went".`,explanationAr:`كلمة Yesterday تدل على الماضي البسيط، والتصريف الثاني لفعل go هو went.`,exam_trap_explanation:`Avoid adding -ed to irregular verbs like "goed".`}],writingTask:{type:`paragraph`,title:`Write a paragraph of (90-110) words on: "${i}"`,prompt:`Write a coherent, well-structured paragraph of about 90 to 110 words discussing "${i}". Highlight key vocabulary (${h.word}, ${g.word}), describe how young Egyptians apply these values, and conclude with a piece of moral advice for your peers.`,promptAr:`اكتب فقرة من 90 إلى 110 كلمات عن "${a}"، موظفاً المفردات الأساسية والنصائح الإيجابية.`,targetWords:`90 - 110 words`,guidancePoints:[`Introduce the importance of ${i.toLowerCase()} in our lives.`,`Describe how students can ${v.phrase} and cooperate with each other.`,`Conclude with an encouraging summary advice for fellow classmates.`],modelAnswer:`${i} plays a vital role in our daily lives and educational journey. As Egyptian prep students, it is essential to understand that dedication, cooperation, and respect form the foundation of our success. For instance, when we ${v.phrase}, we not only assist our community but also develop essential life skills. Moreover, being ${_.word} of our heritage encourages us to study harder. In conclusion, every student should embrace positive values, respect teachers, and strive to build a brighter future for Egypt.`,rubricCriteria:[{criterion:`Task Relevance & Ideas (Content)`,marks:4},{criterion:`Vocabulary Choice & Collocations`,marks:3},{criterion:`Grammar Accuracy & Punctuation`,marks:3}]}};return{stage:`Preparatory`,grade:e,gradeLabel:t,track:`New Hello`,textbookSeries:`New Hello! Prep ${e-6}`,verificationStatus:`verified`,sourceReference:`Egyptian MOE New Hello! Prep ${e-6}, Term ${n}, Unit ${r} (${i})`,semester:n,unitNumber:r,unitTitle:i,unitTitleAr:a,theme:o,vocabularyModule:{keyWords:d.map(e=>({word:e.word,pos:e.pos,partOfSpeech:e.pos,ar:e.ar,meaningAr:e.ar,def:e.def,meaningEn:e.def,ex:e.ex,exampleSentence:e.ex,exAr:e.exAr})),collocations:f.map(e=>({phrase:e.phrase,meaningAr:e.meaningAr,example:e.example})),exercises:y.vocabGrammarMcqs.slice(0,3)},grammarModule:{ruleName:s,ruleNameAr:c,explanationSummary:l,detailedRules:u,exercises:y.vocabGrammarMcqs.slice(3,6)},readingModule:{passageTitle:y.readingPassage.title,passage:y.readingPassage.passage,criticalThinkingFocus:`Analytical inference on ${o}`,questions:y.readingPassage.mcqs},listeningModule:{audioTitle:`${i}: Official Curriculum Dialogue Track`,speakerRoles:`Student A & Student B`,transcript:m,durationApprox:`3 mins`},unitExam:{examId:`prep_g${e}_u${r}_exam`,examTitle:`Prep ${e-6} - Unit ${r} MOE Standard Assessment (2026/2027)`,examTitleAr:`امتحان تقييم الوحدة ${r} - الصف ${e===7?`الأول`:e===8?`الثاني`:`الثالث`} الإعدادي`,durationMinutes:30,totalMarks:30,stage:`Preparatory`,questions:[...y.vocabGrammarMcqs,...y.readingPassage.mcqs].map(e=>({...e,id:`exam_${e.id}`})),prepBlueprint:y}}}var p=[{stage:`Preparatory`,grade:7,gradeLabel:`Prep 1 - الصف الأول الإعدادي`,gradeLabelAr:`الصف الأول الإعدادي (New Hello Prep 1 - 2026/2027)`,track:`New Hello`,description:`Family bonds, volunteer work, school schedules, subjects, inspirational Egyptian personalities, past weekend outings, and world wonders.`,semesters:[{semester:1,semesterLabel:`Term 1 - الفصل الدراسي الأول (Units 1 to 6 - New Hello)`,units:[f(7,`Prep 1`,1,1,`My Family and Me`,`عائلتي وأنا (العمل التطوعي والهوايات)`,`Family relations, musical instruments, voluntary work, chess, twins, orphanages`,`Possessive Adjectives vs. Possessive Pronouns & Present Simple`,`صفات وضمائر الملكية والمضارع البسيط`,`Possessive adjectives (my, your, his, her, our, their) are followed by a NOUN. Possessive pronouns (mine, yours, his, hers, ours, theirs) stand alone WITHOUT a noun. Present Simple expresses permanent facts and repeated habits.`,[{title:`1. Possessives Masterclass (صفات وضمائر الملكية)`,explanation:`Rule: Possessive Adjective + Noun ("This is my bag"). Possessive Pronoun stands alone ("This bag is mine"). Notice that "its" has no possessive pronoun form.`,examples:[`This is my tennis racket, and that blue one is yours.`,`Hany gave his sister her novel, but he forgot his.`]},{title:`2. Ministry Dialogue Strategy: How to Solve Dialogue Questions (دليل إتقان المحادثة)`,explanation:`Step 1: Read the full dialogue to understand context and roles. Step 2: Form Yes/No questions with Aux + Subj + Verb ("Do you play chess? - Yes, I do"). Step 3: Form Wh-questions with Wh-word + Aux + Subj + Verb ("Where do you do voluntary work? - At the children’s hospital").`,examples:[`Q: Where do you do voluntary work? — A: I do voluntary work at the children’s hospital.`,`Q: Can you play the drums? — A: Yes, I can play the drums in the school band.`]}],[{word:`voluntary`,pos:`adj.`,ar:`تطوعي بدون أجر`,def:`Done willingly without being paid, for charity.`,ex:`Hany does voluntary work at the children’s hospital every Saturday.`,exAr:`يقوم هاني بعمل تطوعي في مستشفى الأطفال كل يوم سبت.`},{word:`twins`,pos:`n.`,ar:`توأم متطابق أو متآخٍ`,def:`Two children born to the same mother at the same time.`,ex:`Hazem and Hatem are identical twins; they have the same smile.`,exAr:`حازم وحاتم توأم متطابق، ولديهما نفس الابتسامة.`},{word:`drums`,pos:`n.`,ar:`طبول وآلات إيقاعية`,def:`A musical percussion instrument played with sticks.`,ex:`Rami plays the drums rhythmically in the school musical band.`,exAr:`يعزف رامي على الطبول بإيقاع رائع في فرقة المدرسة الموسيقية.`},{word:`orphanage`,pos:`n.`,ar:`دار رعاية الأيتام`,def:`A residential institution devoted to the care of orphans.`,ex:`Our class visited the local orphanage to donate storybooks.`,exAr:`زار فصلنا دار الأيتام المحلية للتبرع بالقصص المصورة.`},{word:`chess`,pos:`n.`,ar:`لعبة الشطرنج الاستراتيجية`,def:`A board game of strategic skill for two players.`,ex:`My grandfather taught me to play chess patiently.`,exAr:`علمني جدي كيف ألعب الشطرنج بصبر وذكاء.`},{word:`band`,pos:`n.`,ar:`فرقة موسيقية مدرسية`,def:`A group of musicians who play music together.`,ex:`The school band won first prize in the national music contest.`,exAr:`فازت فرقة المدرسة الموسيقية بالجائزة الأولى في مسابقة الموسيقى.`},{word:`interview`,pos:`n.`,ar:`مقابلة حوارية رسمية`,def:`A meeting of people face to face for consultation.`,ex:`The school radio broadcaster conducted an interview with our top athlete.`,exAr:`أجرى مذيع إذاعة المدرسة مقابلة مع بطلنا الرياضي المتفوق.`},{word:`hobby`,pos:`n.`,ar:`هواية واهتمام شخصي`,def:`An activity done regularly in one’s leisure time for pleasure.`,ex:`Reading historical biographies is my favorite leisure hobby.`,exAr:`قراءة السير التاريخية هي هوايتي المفضلة في وقت الفراغ.`},{word:`granddaughter`,pos:`n.`,ar:`الحفيدة`,def:`The daughter of someone’s son or daughter.`,ex:`Grandmother smiles whenever she hugs her young granddaughter.`,exAr:`تبتسم الجدة كلما احتضنت حفيدتها الصغيرة.`},{word:`grandson`,pos:`n.`,ar:`الحفيد`,def:`The son of someone’s son or daughter.`,ex:`Grandpa is proud of his hardworking grandson.`,exAr:`يفتخر الجد بحفيده المجتهد المتفوق.`},{word:`male`,pos:`adj. / n.`,ar:`مذكر / ذكر`,def:`Relating to the sex that produces gametes, especially spermatozoa.`,ex:`All male and female students participate in sports day.`,exAr:`يشارك جميع الطلاب الذكور والإناث في اليوم الرياضي.`},{word:`female`,pos:`adj. / n.`,ar:`مؤنث / أنثى`,def:`Relating to the sex that can bear offspring.`,ex:`The female handball team won the national cup.`,exAr:`فاز فريق كرة اليد للإناث بكأس البطولة القومية.`},{word:`cousin`,pos:`n.`,ar:`ابن أو ابنة العم/الخال`,def:`A child of one’s uncle or aunt.`,ex:`My cousin Tamer lives next door to us.`,exAr:`يعيش ابن عمي تامر في المنزل المجاور لنا.`},{word:`diary`,pos:`n.`,ar:`مذكرات ويوميات شخصية`,def:`A daily written record of personal events and feelings.`,ex:`Hannah writes down her reflections in her secret diary every night.`,exAr:`تدون هنا خواطرها في دفتر يومياتها كل ليلة.`},{word:`athletics`,pos:`n.`,ar:`ألعاب القوى والجمباز`,def:`Physical sports such as running, jumping, and throwing.`,ex:`Habiba Marzouk excels in international rhythmic gymnastics athletics.`,exAr:`تتفوق حبيبة مرزوق في منافسات ألعاب القوى والجمباز الإيقاعي الدولي.`},{word:`gymnast`,pos:`n.`,ar:`لاعب جمباز محترف`,def:`A person trained in gymnastics exercises.`,ex:`An Olympic gymnast trains for six hours every single day.`,exAr:`يتدرب لاعب الجمباز الأولمبي ست ساعات كل يوم.`},{word:`busy`,pos:`adj.`,ar:`مشغول بأعمال مفيدة`,def:`Having a great deal to do; occupied.`,ex:`Even when she is busy, she balances study with rigorous sports training.`,exAr:`حتى عندما تكون مشغولة، توازن بين دراستها وتدريبها الرياضي الشاق.`},{word:`balance`,pos:`v.`,ar:`يوازن بين متطلبات الحياة`,def:`To keep or put in a steady position; equalize.`,ex:`Top students balance study, family time, and healthy athletic exercise.`,exAr:`يوازن الطلاب المتفوقون بين الدراسة ووقت العائلة والرياضة الصحية.`},{word:`train`,pos:`v.`,ar:`يتدرب بجدية`,def:`To undergo a course of exercise and education in skill.`,ex:`Swimmers train hard to qualify for the national championships.`,exAr:`يتدرب السباحون بجد للتأهل لبطولات الجمهورية.`},{word:`achieve`,pos:`v.`,ar:`يحقق وينجز الأهداف`,def:`Successfully bring about or reach a desired objective by effort.`,ex:`With persistent dedication, Egyptian youth achieve their ambitious dreams.`,exAr:`بالعزيمة والإصرار، يحقق الشباب المصري أحلامهم الطموحة.`}],[{phrase:`do voluntary work`,meaningAr:`يقوم بعمل تطوعي خيري`,example:`Our scouts group does voluntary work at the community center.`},{phrase:`play musical instruments`,meaningAr:`يعزف على آلات موسيقية`,example:`Students learn to play musical instruments in music class.`},{phrase:`balance school and sport`,meaningAr:`يوازن بين المدرسة والرياضة`,example:`Champions know how to balance school and competitive sport.`},{phrase:`listen to the teacher`,meaningAr:`ينصت للمعلم باهتمام`,example:`Attentive students always listen to the teacher carefully.`},{phrase:`proud of her achievements`,meaningAr:`فخور بإنجازاتها وبطولاتها`,example:`Egypt is proud of Habiba Marzouk’s gymnastics achievements.`}],`Family life and personal dedication shape young Egyptians! Hazem and Hatem are twin brothers who attend prep school in Giza. Both boys are passionate about sports and community service. Every Friday afternoon, they visit an orphanage in their neighborhood to teach young children how to play chess and read English stories. "Voluntary work makes our hearts full of happiness," Hazem says. Their sister, Salma, is a dedicated gymnast who trains five hours a day. She balances her academic curriculum with rigorous athletics, dreaming of representing Egypt at the Olympic Games.`,`Hazem: "Hello, Rami! What are your plans for this weekend?"
Rami: "Hello, Hazem! My twin brother and I are doing voluntary work at the children’s hospital."
Hazem: "That is wonderful! Do you play musical instruments there?"
Rami: "Yes, I play the drums and Hatem plays the guitar to cheer up the children."`),f(7,`Prep 1`,1,2,`It’s My Favorite Subject`,`مادتي المفضلة والجدول المدرسي`,`School subjects, timetable, library, school bell, daily routine, computer studies`,`Possessive (’s / s’) & Adverbs of Frequency with Prepositions of Time`,`الملكية وظروف التكرار وحروف جر الوقت`,`Use singular (’s) for singular nouns: "the teacher’s book". Use (s’) for regular plurals ending in s: "the girls’ school". For irregular plurals, use (’s): "the children’s playground". Prepositions of time: "at + time" (at 7:30), "on + days" (on Monday), "in + months/parts of day" (in the morning).`,[{title:`1. Possessive (’s / s’) Rules (قواعد الملكية الدقيقة)`,explanation:`Singular noun -> add ’s: "My sister’s pen". Regular plural -> add only apostrophe ’: "The boys’ bags". Irregular plural without s -> add ’s: "The children’s library".`,examples:[`This is the girls’ playground; the boys’ playground is across the field.`,`The teacher’s red pen is on the desk.`]},{title:`2. Adverbs of Frequency & Position (موقع ظروف التكرار)`,explanation:`Always (100%), Usually (80%), Often (70%), Sometimes (50%), Never (0%). They go BEFORE main verbs, but AFTER verb "to be" (am/is/are).`,examples:[`We always listen to our computer studies teacher.`,`Hany is never late for the morning assembly.`]}],[{word:`timetable`,pos:`n.`,ar:`جدول الحصص الدراسية`,def:`A chart showing the departure and arrival times or class schedules.`,ex:`Check your weekly school timetable to see when science class meets.`,exAr:`تحقق من جدول حصصك الأسبوعي لمعرفة موعد حصة العلوم.`},{word:`drama`,pos:`n.`,ar:`المسرح والفنون التمثيلية`,def:`The performance of plays or theater as a school subject.`,ex:`We act out historical scenes during our weekly drama lessons.`,exAr:`نمثل مشاهد تاريخية خلال حصص الدراما والمسرح الأسبوعية.`},{word:`computer studies`,pos:`n.`,ar:`مادة الحاسب الآلي وتكنولوجيا المعلومات`,def:`The study of computer hardware, programming, and software.`,ex:`In computer studies, we learned how to design interactive presentations.`,exAr:`في مادة الحاسب الآلي، تعلمنا كيفية تصميم عروض تقديمية تفاعلية.`},{word:`bell`,pos:`n.`,ar:`جرس الحصة المدرسية`,def:`A metal instrument that rings to signal the start or end of a lesson.`,ex:`The school bell rings at eight o’clock to begin our first class.`,exAr:`يرن جرس المدرسة في تمام الثامنة لبدء الحصة الأولى.`},{word:`library`,pos:`n.`,ar:`المكتبة المدرسية`,def:`A room containing collections of books and periodicals for reading.`,ex:`Students borrow encyclopedias and science books from the library.`,exAr:`يستعير الطلاب الموسوعات وكتب العلوم من المكتبة.`},{word:`break`,pos:`n.`,ar:`الفسحة المدرسية ووقت الراحة`,def:`A pause in work or during the school day for recreation.`,ex:`During the break, we eat our healthy snacks and chat in the playground.`,exAr:`أثناء الفسحة، نتناول وجباتنا الخفيفة الصحية ونتحادث في الفناء.`},{word:`hall`,pos:`n.`,ar:`فناء / ردهة المدرسة الكبرى`,def:`A large room in a school for assemblies and community gatherings.`,ex:`All students gather in the main assembly hall for the principal’s speech.`,exAr:`يجتمع جميع الطلاب في ردهة المدرسة الكبرى للاستماع لكلمة المدير.`},{word:`typical`,pos:`adj.`,ar:`نموذجي ومعتاد في الروتين`,def:`Having the distinctive qualities of a particular type of person or thing.`,ex:`On a typical weekday, my alarm rings at six o’clock in the morning.`,exAr:`في يوم دراسي نموذجي، يرن منبهي في السادسة صباحاً.`},{word:`quarter past`,pos:`idiom`,ar:`وربع (في التوقيت: 15 دقيقة)`,def:`Fifteen minutes past the specified hour.`,ex:`Our math period starts promptly at quarter past nine.`,exAr:`تبدأ حصة الرياضيات بدقة في التاسعة والربع.`},{word:`quarter to`,pos:`idiom`,ar:`إلا ربع (في التوقيت: 45 دقيقة)`,def:`Fifteen minutes before the specified hour.`,ex:`We pack our backpacks at quarter to two in the afternoon.`,exAr:`نجمع حقائبنا المدرسية في تمام الثانية إلا ربع ظهراً.`},{word:`religion`,pos:`n.`,ar:`التربية الدينية والأخلاق`,def:`The school subject covering moral values and spiritual teachings.`,ex:`Religious education promotes honesty, tolerance, and respect for all.`,exAr:`تعزز مادة التربية الدينية الصدق والتسامح والاحترام للجميع.`},{word:`science`,pos:`n.`,ar:`العلوم والاكتشافات`,def:`The intellectual study of the physical and natural world through observation.`,ex:`We conducted an exciting experiment in the science laboratory.`,exAr:`أجرينا تجربة مشوقة ومثيرة في معمل العلوم.`},{word:`social studies`,pos:`n.`,ar:`الدراسات الاجتماعية والجغرافيا`,def:`The study of human society, geography, and Egyptian history.`,ex:`Social studies teaches us about the pharaohs and the geography of the Nile.`,exAr:`تعلمنا الدراسات الاجتماعية عن الفراعنة وجغرافيا نهر النيل.`},{word:`home economics`,pos:`n.`,ar:`مادة الاقتصاد المنزلي`,def:`Cooking and other aspects of household management taught in school.`,ex:`Students learn healthy cooking skills in home economics.`,exAr:`يتعلم الطلاب مهارات الطهي الصحي في حصة الاقتصاد المنزلي.`},{word:`art`,pos:`n.`,ar:`التربية الفنية والرسم`,def:`The expression of human creative skill and imagination.`,ex:`I painted a panoramic view of the Citadel in my art class.`,exAr:`رسمت لوحة بانورامية لقلعة صلاح الدين في حصة التربية الفنية.`},{word:`languages`,pos:`n.`,ar:`اللغات الحية (العربية والإنجليزية)`,def:`Systems of communication used by particular countries or communities.`,ex:`Mastering foreign languages opens doors to international scholarships.`,exAr:`إتقان اللغات الأجنبية يفتح الأبواب للمنح الدراسية الدولية.`},{word:`punctual`,pos:`adj.`,ar:`منضبط ودقيق في المواعيد`,def:`Happening or doing something at the agreed or proper time.`,ex:`Punctual students arrive before the school gate closes.`,exAr:`يصل الطلاب المنضبطون قبل إغلاق بوابة المدرسة.`},{word:`journey`,pos:`n.`,ar:`رحلة يومية إلى المدرسة`,def:`An act of travelling from one place to another.`,ex:`My daily journey to school takes twenty minutes by metro.`,exAr:`تستغرق رحلتي اليومية إلى المدرسة عشرين دقيقة بالمترو.`},{word:`canoe`,pos:`n.`,ar:`زورق خفيف للتنقل المائي`,def:`A narrow, light boat propelled with a paddle.`,ex:`In some river communities, children travel to school in a canoe.`,exAr:`في بعض المجتمعات النهرية، يسافر الأطفال إلى المدرسة في زورق.`},{word:`snowmobile`,pos:`n.`,ar:`مركبة جليدية للتنقل الشتوي`,def:`A motorized vehicle for traveling over snow.`,ex:`In polar regions, children ride a snowmobile over winter ice.`,exAr:`في المناطق القطبية، يركب الأطفال مركبة جليدية فوق الثلج.`}],[{phrase:`ring the school bell`,meaningAr:`يرن جرس المدرسة للحصص`,example:`The janitor rings the school bell at the end of each period.`},{phrase:`borrow books from the library`,meaningAr:`يستعير كتباً من المكتبة`,example:`We borrow illustrated history books from the library.`},{phrase:`have computer studies`,meaningAr:`يحضر حصة الحاسب الآلي`,example:`We have computer studies on Tuesday morning.`},{phrase:`on school days`,meaningAr:`في الأيام الدراسية`,example:`I wake up at half past six on school days.`},{phrase:`a long journey to school`,meaningAr:`رحلة طويلة للوصول للمدرسة`,example:`Walking through desert dunes is a long journey to school for some children.`}],`A typical day at an Egyptian preparatory school is vibrant and purposeful! At quarter to eight, students assemble in the courtyard for the morning salute to the flag. When the bell rings at eight o’clock, we move to our classrooms. My favorite subject is computer studies because our teacher shows us how to program creative educational games. On Wednesdays, we have two periods of science in the modern laboratory, followed by art. During break, students sit in the courtyard to eat sandwiches, while others visit the library to borrow books.`,`Amira: "What’s your favorite subject on today’s timetable, Dina?"
Dina: "My favorite subject is English! We have it at quarter past ten."
Amira: "Who is your English teacher this term?"
Dina: "Miss Mona is our teacher. She is always energetic and kind."`),f(7,`Prep 1`,1,3,`Different People`,`شخصيات ملهمة وملامح متنوعة`,`Physical features (curly, straight, blonde, dark, beard, mustache), Mohamed Salah, Alice in Wonderland, kindness`,`Have got / Has got & Modal Can / Can’t for Abilities`,`التعبير عن الملامح الجسدية بفعل Have got والقدرة بـ Can`,`I/You/We/They have got (haven’t got). He/She/It has got (hasn’t got). Question: "Has he got dark curly hair? - Yes, he has." Modal CAN + base verb expresses physical and mental ability: "He can run very fast".`,[{title:`1. Describing Physical Appearance (وصف الملامح الجسدية)`,explanation:`Form: Subject + have/has got + adjective + hair/eyes. Remember: Adjectives go in order: Size -> Shape -> Color -> Noun ("She has got long curly dark hair").`,examples:[`Mohamed Salah has got curly dark hair and a neat beard.`,`Alice has got straight blonde hair and curious bright eyes.`]},{title:`2. Expressing Abilities with Can / Can’t (التعبير عن القدرات)`,explanation:`Form: Subject + can / cannot (can’t) + infinitive without to. Question: "Can you score goals? - Yes, I can."`,examples:[`Mohamed Salah can run fast and score sensational goals.`,`He is generous, so he can give donations to help his village.`]}],[{word:`curly`,pos:`adj.`,ar:`شعر مجعد / كيرلي`,def:`Having curls, waves, or spirals.`,ex:`Mohamed Salah is famous for his trademark curly hair.`,exAr:`يشتهر محمد صلاح بشعره المجعد المميز.`},{word:`straight`,pos:`adj.`,ar:`شعر أملس وناعم`,def:`Extending or moving uniformly in one direction without a curve.`,ex:`Noura has got straight brown hair tied with a ribbon.`,exAr:`لدى نورا شعر أملس بني ومربوط بشريطة أنيقة.`},{word:`dark`,pos:`adj.`,ar:`داكن / أسود اللون`,def:`Having a color reflecting little light, such as black or dark brown.`,ex:`Many Egyptians have got striking dark eyes and lashes.`,exAr:`يمتلك العديد من المصريين عيوناً ورموشاً داكنة وجذابة.`},{word:`blonde`,pos:`adj.`,ar:`أشقر الشعر`,def:`Having fair or pale yellow hair.`,ex:`Alice in Wonderland is depicted with long blonde hair.`,exAr:`تُوصف أليس في بلاد العجائب بأنها ذات شعر أشقر طويل.`},{word:`beard`,pos:`n.`,ar:`لحية مهذبة`,def:`A growth of hair on the chin and lower cheeks of a man’s face.`,ex:`Our grandfather trims his distinguished grey beard every Friday.`,exAr:`يهذب جدنا لحيته الرمادية الموقرة كل يوم جمعة.`},{word:`mustache`,pos:`n.`,ar:`شارب / شنب`,def:`A strip of hair left to grow on the upper lip.`,ex:`Uncle Ahmed wears a traditional Egyptian mustache.`,exAr:`يتميز العم أحمد بشارب مصري تقليدي مهذب.`},{word:`generous`,pos:`adj.`,ar:`كريم ومعطاء لأهله`,def:`Showing a readiness to give more of something than is strictly necessary.`,ex:`Mohamed Salah is generous; he built a school and hospital in his village.`,exAr:`محمد صلاح كريم؛ فقد بنى مدرسة ومستشفى في قريته الأصلية.`},{word:`sensible`,pos:`adj.`,ar:`عاقل وحكيم في تصرفاته`,def:`Chosen in accordance with wisdom or prudence; reasonable.`,ex:`Alice tries to make sensible decisions in a world of nonsense.`,exAr:`تحاول أليس اتخاذ قرارات عاقلة وحكيمة في عالم العجائب.`},{word:`brave`,pos:`adj.`,ar:`شجاع وجريء`,def:`Ready to face and endure danger or pain; showing courage.`,ex:`The brave firefighter rescued the scared kitten from the tree.`,exAr:`أنقذ رجل الإطفاء الشجاع القطة الخائفة من أعلى الشجرة.`},{word:`strange`,pos:`adj.`,ar:`غريب وغير مألوف`,def:`Unusual, unexpected, or surprising in a way that causes curiosity.`,ex:`Alice encountered many strange talking animals in Wonderland.`,exAr:`قابلت أليس العديد من الحيوانات الناطقة الغريبة في بلاد العجائب.`},{word:`score`,pos:`v.`,ar:`يسجل ويحرز أهدافاً`,def:`Gain a point or goal in a competitive game or match.`,ex:`The striker was thrilled to score the decisive goal in the 90th minute.`,exAr:`فرح المهاجم كثيراً بتسجيل الهدف الحاسم في الدقيقة التسعين.`},{word:`fan`,pos:`n.`,ar:`مشجع ومحب وفيّ`,def:`A person who has a strong interest in or admiration for sports.`,ex:`Millions of passionate Egyptian football fans cheered for the national team.`,exAr:`هتف الملايين من مشجعي كرة القدم المصريين المخلصين لمنتخبهم الوطني.`},{word:`donation`,pos:`n.`,ar:`تبرع مالي أو عيني للخير`,def:`Something that is given to a charity, especially money.`,ex:`Generous citizens give donations to build children’s cancer wards.`,exAr:`يقدم المواطنون الكرماء تبرعات لبناء أقسام علاج سرطان الأطفال.`},{word:`character`,pos:`n.`,ar:`شخصية في قصة أو رواية`,def:`A person in a novel, play, or movie.`,ex:`The Queen of Hearts is a bossy character in the story.`,exAr:`ملكة القلوب شخصية متسلطة في القصة.`},{word:`speed`,pos:`n.`,ar:`سرعة حركية فائقة`,def:`The rate at which someone or something is able to move or operate.`,ex:`Salah’s incredible running speed terrifies European defenders.`,exAr:`سرعة صلاح الفائقة في الجري تخيف مدافعي الفرق الأوروبية.`},{word:`smile`,pos:`n. / v.`,ar:`ابتسامة مشرقة`,def:`A pleased, kind, or amused facial expression.`,ex:`He always greets young fans with a warm, humble smile.`,exAr:`يرحب دائماً بالمشجعين الصغار بابتسامة دافئة ومتواضعة.`},{word:`glasses`,pos:`n.`,ar:`نظارة طبية للقراءة`,def:`A pair of lenses set in a frame worn on the face to aid sight.`,ex:`My grandfather wears reading glasses to read the morning newspaper.`,exAr:`يرتدي جدي نظارة طبية لقراءة جريدة الصباح.`},{word:`kindness`,pos:`n.`,ar:`عطف ورقة وإحسان`,def:`The quality of being friendly, generous, and considerate.`,ex:`Treating younger pupils with kindness builds a harmonious school.`,exAr:`معاملة التلاميذ الصغار برفق وإحسان تبني مدرسة متناغمة.`},{word:`short`,pos:`adj.`,ar:`قصير القامة`,def:`Measuring a small distance from head to toe.`,ex:`Although he is relatively short, his agile agility makes him elusive.`,exAr:`رغم قصر قامته النسبي، فإن رشاقته الحركية تجعله صعب الإيقاف.`},{word:`tall`,pos:`adj.`,ar:`طويل القامة وفارع`,def:`Of great or more than average height.`,ex:`Basketball players are typically very tall and athletic.`,exAr:`يتميز لاعبو كرة السلة عادة بأنهم طوال القامة ورياضيون جداً.`}],[{phrase:`score sensational goals`,meaningAr:`يحرز أهدافاً مذهلة`,example:`Mohamed Salah can score sensational goals from tight angles.`},{phrase:`give money to charities`,meaningAr:`يتبرع بالأموال للجمعيات الخيرية`,example:`Kind stars give money to charities to help poor villages.`},{phrase:`run very fast`,meaningAr:`يجري بسرعة فائقة`,example:`Athletes can run very fast to beat world records.`},{phrase:`talk to his fans`,meaningAr:`يتحدث إلى مشجعيه بتواضع`,example:`He takes time to talk to his young fans and take photos.`},{phrase:`make sensible decisions`,meaningAr:`يتخذ قرارات عاقلة وحكيمة`,example:`Wise students make sensible decisions about their study routines.`}],`Mohamed Salah is my ultimate role model! He is an Egyptian sports hero who plays for Liverpool and the Egyptian national team. He has got dark curly hair, brown eyes, and a warm, trimmed beard. Salah is not exceptionally tall, but he is incredibly fast and agile. What makes him truly beloved across the globe is his generosity and humility. He has given millions of pounds to build clean water stations, modern schools, and hospitals in his hometown of Nagrig. He always smiles and takes time to sign autographs for children.`,`Tarek: "Who is your favorite sports star, Youssef?"
Youssef: "Mohamed Salah, without a doubt! He is an incredible player."
Tarek: "Has he got straight blonde hair?"
Youssef: "No! He has got curly dark hair, a warm smile, and a neat beard."`),r,i,a]}]},{stage:`Preparatory`,grade:8,gradeLabel:`Prep 2 - الصف الثاني الإعدادي`,gradeLabelAr:`الصف الثاني الإعدادي (New Hello Prep 2 - 2026/2027)`,track:`New Hello`,description:`Teen habits, street food vendors, doctors and heroic nurses, smart gadgets of the future, nutrition, and environmental stewardship.`,semesters:[{semester:1,semesterLabel:`Term 1 - الفصل الدراسي الأول (Units 1 to 6 - New Hello)`,units:[f(8,`Prep 2`,1,1,`Coming Home`,`العودة للمنزل وروتين المراهقين`,`Daily routines, texting friends, sharing bedrooms, sofa, block of flats, hobbies`,`Present Simple vs. Adverbs of Frequency & Wh-Question Formulations`,`المضارع البسيط وروتين المراهقين وتكوين الأسئلة`,`Use Present Simple for daily repetitive routines. Form questions: Question word + do/does + subject + infinitive verb ("What time do you text your friends? - I usually text them after dinner").`,[{title:`1. Present Simple for Teen Habits (المضارع البسيط للروتين اليومي)`,explanation:`Affirmative: I/We/They text, He/She/It texts. Negative: don’t / doesn’t + bare verb. Time expressions: every day, in the evening, on weekends.`,examples:[`Dina usually does her homework on the living room sofa.`,`My brother doesn’t share a bedroom; he has his own room.`]},{title:`2. Wh-Questions in Dialogue Solvers (تكوين الأسئلة في المحادثة)`,explanation:`Question word (What, Where, When, Who, Why, How often) + Auxiliary (do / does / did) + Subject + Main Verb.`,examples:[`Q: How often do you play chess with your father? — A: I usually play once a week.`,`Q: What time do you wake up on school days? — A: I always wake up at 6:30 AM.`]}],[{word:`routine`,pos:`n.`,ar:`روتين ونمط يومي متكرر`,def:`A sequence of actions regularly followed.`,ex:`My morning routine includes eating breakfast and brushing my teeth.`,exAr:`يشمل روتيني الصباحي تناول الإفطار وغسل أسناني بالفرشاة.`},{word:`text`,pos:`v.`,ar:`يراسل نصياً عبر الهاتف`,def:`Send a text message to someone on a mobile phone.`,ex:`I text my best friend to ask about the math homework.`,exAr:`أراسل صديقي المفضل نصياً لأسأله عن واجب الرياضيات.`},{word:`block of flats`,pos:`n.`,ar:`عمارة سكنية متعددة الشقق`,def:`A large building containing many apartments.`,ex:`My grandparents live on the fourth floor of a modern block of flats.`,exAr:`يعيش جدي وجدتي في الطابق الرابع بعمارة سكنية حديثة.`},{word:`sofa`,pos:`n.`,ar:`أريكة مريحة في غرفة المعيشة`,def:`A long comfortable seat with a back and arms.`,ex:`Dad relaxes on the living room sofa and reads the newspaper.`,exAr:`يستريح الأبي على أريكة غرفة المعيشة ويقرأ الجريدة.`},{word:`share`,pos:`v.`,ar:`يشارك ويتشارك مع الآخرين`,def:`Have a portion of something with another or others.`,ex:`I share a sunny bedroom with my younger brother Ziad.`,exAr:`أتشارك غرفة نوم مشمسة مع أخي الأصغر زياد.`},{word:`interview`,pos:`n. / v.`,ar:`مقابلة شخصية حوارية`,def:`A formal consultation to evaluate or obtain facts.`,ex:`The journalist held an interview with the prize-winning scientist.`,exAr:`أجرى الصحفي مقابلة مع العالم الحائز على الجائزة.`},{word:`prefer`,pos:`v.`,ar:`يفضل أمراً على آخر`,def:`Like one thing or person better than another.`,ex:`I prefer studying in the quiet library rather than in noisy cafes.`,exAr:`أفضل المذاكرة في المكتبة الهادئة بدلاً من المقاهي الصاخبة.`},{word:`weekend`,pos:`n.`,ar:`عطلة نهاية الأسبوع`,def:`Saturday and Sunday (or Friday and Saturday in Egypt).`,ex:`On the weekend, our whole family travels to Alexandria.`,exAr:`في عطلة نهاية الأسبوع، تسافر عائلتنا بأكملها إلى الإسكندرية.`},{word:`baker’s`,pos:`n.`,ar:`مخبز العيش والفطائر`,def:`A shop where bread and cakes are made and sold.`,ex:`Dad buys fresh warm baladi bread from the local baker’s every morning.`,exAr:`يشتري أبي خبزاً بلدياً طازجاً ودافئاً من مخبز الحي كل صباح.`},{word:`cook`,pos:`v. / n.`,ar:`يطهو / طباخ ماهر`,def:`Prepare food by combining and heating ingredients.`,ex:`Mom and I cook healthy lentil soup on cold winter evenings.`,exAr:`نطهو أنا وأمي شوربة عدس صحية في أمسيات الشتاء الباردة.`},{word:`drawer`,pos:`n.`,ar:`درج المكتب لتخزين الأشياء`,def:`A box-shaped container that fits into a piece of furniture.`,ex:`I keep my stationery and rulers organized in my desk drawer.`,exAr:`أحتفظ بأدواتي ومساطري مرتبة في درج مكتبي.`},{word:`wardrobe`,pos:`n.`,ar:`دولاب الملابس`,def:`A large, tall cupboard in which clothes may be hung or stored.`,ex:`Hang your clean school uniform neatly inside your wardrobe.`,exAr:`علق زيك المدرسي النظيف بعناية داخل دولاب الملابس.`},{word:`mirror`,pos:`n.`,ar:`مرآة زجاجية عاكسة`,def:`A reflective surface of glass coated with metal.`,ex:`Look in the bathroom mirror before leaving home.`,exAr:`انظر في مرآة الحمام للتأكد من هندامك قبل مغادرة المنزل.`},{word:`curtains`,pos:`n.`,ar:`ستائر النوافذ الجميلة`,def:`Pieces of cloth hung to cover a window.`,ex:`Open the white curtains to let the bright sunshine into the room.`,exAr:`افتح الستائر البيضاء لتسمح لأشعة الشمس المشرقة بدخول الغرفة.`},{word:`cushion`,pos:`n.`,ar:`وسادة مقعد مريحة`,def:`A soft bag of fabric stuffed with feathers or foam.`,ex:`There are colorful cushions on our comfortable sofa.`,exAr:`توجد وسائد ملونة على أريكتنا المريحة.`},{word:`carpet`,pos:`n.`,ar:`سجادة مفروشة على الأرض`,def:`A floor covering made of thick woven fabric.`,ex:`We bought a hand-woven oriental carpet from Khan el-Khalili.`,exAr:`اشترينا سجادة شرقية منسوجة يدوياً من خان الخليلي.`},{word:`lamp`,pos:`n.`,ar:`مصباح إضاءة ومكتب`,def:`A device for giving light, especially one with an electric bulb.`,ex:`I turn on my desk lamp whenever I study after sunset.`,exAr:`أشعل مصباح مكتبي كلما ذاكرت بعد غروب الشمس.`},{word:`basin`,pos:`n.`,ar:`حوض غسيل الأيدي والوجه`,def:`A bowl for water with taps and a drain in a bathroom.`,ex:`Wash your hands thoroughly in the bathroom basin.`,exAr:`اغسل يديك جيداً في حوض الحمام.`},{word:`shelf`,pos:`n.`,ar:`رف خشبي للكتب`,def:`A flat length of wood attached to a wall to display objects.`,ex:`I arrange my English dictionaries neatly on the wooden shelf.`,exAr:`أنظم قواميسي الإنجليزية بدقة على الرف الخشبي.`},{word:`tidy`,pos:`adj. / v.`,ar:`مرتب ومنظم / يرتب غرفته`,def:`Arranged neatly and in order; clean up.`,ex:`Keep your study desk tidy so you can concentrate well.`,exAr:`حافظ على ترتيب مكتب مذاكرتك لتتمكن من التركيز جيداً.`}],[{phrase:`text my friends`,meaningAr:`يراسل أصدقاءه عبر الهاتف`,example:`I relax on the sofa and text my friends after doing homework.`},{phrase:`share a bedroom`,meaningAr:`يتشارك غرفة النوم مع أخيه`,example:`My brother and I share a bedroom happily.`},{phrase:`do homework on the sofa`,meaningAr:`يحل الواجب جالساً على الأريكة`,example:`It is comfortable to read and do homework on the sofa.`},{phrase:`have a busy routine`,meaningAr:`يمتلك جدولاً يومياً حافلاً`,example:`Prep students have a busy routine full of school and sports.`},{phrase:`listen to music on headphones`,meaningAr:`يستمع للموسيقى بسماعات الأذن`,example:`He listens to soft music on his headphones while reading.`}],`Dina and Reem are best friends who attend prep school in Alexandria. On weekdays, Dina’s alarm buzzes at 6:00 AM. She washes her face, puts on her school uniform, and eats a breakfast of fava beans and eggs with her parents. "I live in a tall block of flats overlooking the Mediterranean," Dina says. "My bedroom is sunny and tidy. I share it with my sister Maya. We have two white beds, a shared wardrobe, and a bookshelf full of adventure novels. In the evening, after completing my school projects, I love sitting on the sofa to text my friends and talk about our weekend plans."`,`Reem: "Hi Dina! What do you usually do after school?"
Dina: "Hi Reem! I usually help my mother cook lunch, and then I do my English exercises."
Reem: "Do you have your own bedroom?"
Dina: "No, I share a cozy bedroom with my sister Maya."`),f(8,`Prep 2`,1,2,`How Are You Feeling?`,`كيف تشعر؟ (المهن وأحوال الشارع)`,`Street food sellers, nurses, police officers, sign language, calligraphy, adverbs of manner`,`Present Continuous vs. Present Simple & Adverbs of Manner (-ly)`,`المضارع المستمر وظروف الطريقة (بإضافة ly)`,`Use Present Continuous (am/is/are + verb-ing) for actions happening RIGHT NOW or temporary situations. Adverbs of manner describe HOW an action is done. Form: Adjective + "-ly" (quick -> quickly, careful -> carefully). Irregular adverbs: good -> well, fast -> fast, hard -> hard.`,[{title:`1. Present Continuous for Actions Now (المضارع المستمر للأحداث الجارية)`,explanation:`Form: am/is/are + v-ing. Key words: now, at the moment, look!, listen!, at present. Rule: Verbs ending in -e drop the e (write -> writing).`,examples:[`The street food seller is preparing hot falafel sandwiches at the moment.`,`Look! The traffic police officer is directing cars safely.`]},{title:`2. Adverbs of Manner: Form and Irregulars (ظروف الطريقة)`,explanation:`Adjectives describe nouns ("He is a careful driver"). Adverbs describe verbs ("He drives carefully"). Note: good becomes WELL, fast stays FAST, hard stays HARD.`,examples:[`The nurse treats the injured patients kindly and patiently.`,`He speaks English very well because he practices every day.`]}],[{word:`street food seller`,pos:`n.`,ar:`بائع طعام الشارع المتجول`,def:`A vendor who prepares and sells fresh food from a mobile cart.`,ex:`The street food seller serves hot, crispy falafel to morning commuters.`,exAr:`يقدم بائع طعام الشارع الفلافل الساخنة المقرمشة للركاب في الصباح.`},{word:`calligraphy`,pos:`n.`,ar:`فن الخط العربي البديع`,def:`Decorative handwriting or handwritten lettering with specialized pens.`,ex:`My grandfather practices Arabic calligraphy with black ink and reed pens.`,exAr:`يمارس جدي فن الخط العربي بالحبر الأسود وأقلام البوص.`},{word:`sign language`,pos:`n.`,ar:`لغة الإشارة للصم والبكم`,def:`A system of communication using visual gestures and signs.`,ex:`She learned sign language to communicate with deaf and mute children.`,exAr:`تعلمت لغة الإشارة لتتواصل بسهولة مع الأطفال الصم والبكم.`},{word:`patient`,pos:`n. / adj.`,ar:`مريض / صبور وحليم`,def:`A person receiving medical care; or able to accept delays calmly.`,ex:`The nurse checks the patient’s pulse patiently and gently.`,exAr:`تفحص الممرضة نبض المريض بصبر ورقة بالغة.`},{word:`ward`,pos:`n.`,ar:`عنبر المرضى بالمستشفى`,def:`A separate room or division in a hospital for patients.`,ex:`The pediatric ward is painted with cheerful cartoon animals.`,exAr:`عنبر الأطفال بالمستشفى مزين برسومات كرتونية مرحة ومبهجة.`},{word:`police officer`,pos:`n.`,ar:`ضابط شرطة يحفظ الأمن`,def:`A member of a police force who enforces traffic and laws.`,ex:`The police officer is directing morning traffic outside the school.`,exAr:`يقوم ضابط الشرطة بتنظيم حركة المرور الصباحية أمام المدرسة.`},{word:`stall`,pos:`n.`,ar:`كشك أو عربة بيع طعام`,def:`A stand, booth, or compartment for the sale of goods in a market.`,ex:`Uncle Tarek parks his food stall near the metro station every morning.`,exAr:`يوقف العم طارق عربة طعامه بالقرب من محطة المترو كل صباح.`},{word:`crowded`,pos:`adj.`,ar:`مزدحم وممتلئ بالناس`,def:`Full of people, leaving little or no room for movement.`,ex:`Downtown Cairo markets are crowded on Friday afternoons.`,exAr:`تكون أسواق وسط البلد في القاهرة مزدحمة في فترة بعد ظهر الجمعة.`},{word:`repair`,pos:`v.`,ar:`يصلح العطل والأجهزة`,def:`Fix or mend a thing suffering from damage or a fault.`,ex:`The technician is repairing my broken laptop screen.`,exAr:`يقوم الفني بإصلاح شاشة حاسوبي المحمول المعطلة الآن.`},{word:`sewing`,pos:`n.`,ar:`الخياطة والحياكة اليدوية`,def:`The craft of fastening or joining objects using stitches with needle.`,ex:`Grandma teaches my sister the traditional craft of embroidery sewing.`,exAr:`تعلم الجدة أختي حرفة التطريز والخياطة التقليدية الجميلة.`},{word:`disabled`,pos:`adj.`,ar:`من ذوي الهمم والاحتياجات`,def:`Having a physical or mental condition that limits movements or senses.`,ex:`Modern public buses have ramps to welcome disabled passengers.`,exAr:`تحتوي حافلات النقل الحديثة على منحدرات لاستقبال الركاب من ذوي الهمم.`},{word:`deaf`,pos:`adj.`,ar:`أصم فاقد لحاسة السمع`,def:`Lacking the power of hearing or having impaired hearing.`,ex:`Sign language enables deaf individuals to express complex feelings.`,exAr:`تمكن لغة الإشارة الصم من التعبير عن مشاعرهم وأفكارهم بدقة.`},{word:`loudly`,pos:`adv.`,ar:`بصوت مرتفع وصاخب`,def:`In a way that produces much noise; audibly.`,ex:`Please do not speak loudly inside the hospital corridors.`,exAr:`من فضلك لا تتحدث بصوت مرتفع داخل ممرات المستشفى.`},{word:`quietly`,pos:`adv.`,ar:`بهدوء وسكينة`,def:`In a quiet manner; making little or no noise.`,ex:`Students work quietly during their reading examination.`,exAr:`يعمل الطلاب بهدوء وسكينة أثناء امتحان القراءة.`},{word:`politely`,pos:`adv.`,ar:`بأدب ولباقة رفيعة`,def:`In a respectful and considerate manner.`,ex:`Always answer your teachers and parents politely.`,exAr:`أجب دائماً على معلميك ووالديك بأدب واحترام.`},{word:`dangerously`,pos:`adv.`,ar:`بشكل محفوف بالخطر`,def:`In a way that is likely to cause problems or injury.`,ex:`Motorcyclists who ride without helmets are driving dangerously.`,exAr:`سائقو الدراجات النارية بدون خوذة يقودون بتهور وبشكل محفوف بالخطر.`},{word:`happily`,pos:`adv.`,ar:`بسعادة وسرور`,def:`In a happy manner; with joy and satisfaction.`,ex:`The children played happily in the neighborhood park.`,exAr:`لعب الأطفال بسعادة وفرح في حديقة الحي.`},{word:`safely`,pos:`adv.`,ar:`بأمان وسلامة`,def:`In a way that is not likely to cause or lead to harm.`,ex:`Cross the wide street safely at the designated pedestrian crossing.`,exAr:`اعبر الشارع العريض بأمان عند ممر المشاة المخصص.`},{word:`carefully`,pos:`adv.`,ar:`بحذر وحيطة وعناية`,def:`In a way that deliberately avoids harm or error.`,ex:`Handle hot glass test tubes carefully in the laboratory.`,exAr:`تعامل مع أنابيب الاختبار الزجاجية الساخنة بحذر في المعمل.`},{word:`badly`,pos:`adv.`,ar:`بشكل رديء أو سيئ`,def:`In an unsatisfactory, inadequate, or unsuccessful way.`,ex:`The athlete played badly because he had a sprained ankle.`,exAr:`لعب الرياضي بشكل غير موفق بسبب التواء في كاحله.`}],[{phrase:`park his food stall`,meaningAr:`يوقف عربة طعامه في مكان مخصص`,example:`Uncle Kamal parks his food stall near the busy bus stop.`},{phrase:`communicate with deaf people`,meaningAr:`يتواصل مع الصم بلغة الإشارة`,example:`Volunteers learn to communicate with deaf people using sign language.`},{phrase:`look after patients`,meaningAr:`يعتني بالمرضى في المستشفى`,example:`Heroic nurses look after sick patients throughout the night.`},{phrase:`drive carefully`,meaningAr:`يقود سيارته بحذر وأمان`,example:`Drivers must drive carefully when it rains heavily.`},{phrase:`speak politely to customers`,meaningAr:`يتحدث بلباقة مع الزبائن`,example:`Shop assistants speak politely to all customers.`}],`On a busy morning in downtown Cairo, hardworking citizens serve their community with passion! Uncle Kamal is a street food seller who prepares fresh foul and taameya sandwiches. "I park my food stall here at six o’clock in the morning," he smiles. "People are hurrying to catch the metro, so I prepare their food quickly and hygienically." Across the street at the children’s hospital, Nurse Mona is looking after young patients in the surgical ward. She speaks softly and treats every child with loving care. In the school next door, students are learning sign language so they can communicate warmly with deaf peers.`,`Amal: "Look, what is that man doing on the corner?"
Nour: "He is a street food seller. He is preparing hot falafel for morning workers."
Amal: "He is moving very quickly!"
Nour: "Yes, and he always greets his customers politely."`),f(8,`Prep 2`,1,3,`Great Jobs`,`وظائف عظيمة وقدوات مصرية ملهمة`,`Inspirational Egyptian heroes, heart surgeons, Dr. Magdi Yacoub, Sameera Moussa, Red Crescent volunteers, charity work`,`Past Simple Tense & Used to / Didn’t use to for Past Habits`,`الماضي البسيط والتعبير عن العادات الماضية بـ Used to`,`Use "used to + infinitive" to describe past habits or states that are no longer true today ("He used to work in a small clinic, but now he runs a major hospital"). Negative: "didn’t use to + infinitive". Question: "Did you use to...?"`,[{title:`1. Used to + Infinitive for Past Habits (التعبير عن عادات الماضي)`,explanation:`Affirmative: Subject + used to + base verb. Negative: Subject + didn’t use to + base verb. Question: Did + subject + use to + base verb?`,examples:[`Dr. Magdi Yacoub used to travel across Egypt with his father, who was a surgeon.`,`People didn’t use to have modern heart centers in Upper Egypt before 2009.`]},{title:`2. Past Simple for Completed Historical Achievements (الماضي البسيط للإنجازات التاريخية)`,explanation:`Use Past Simple (verb + ed or irregular second form) with definite past dates such as "in 1995", "in 2009", "when she was young".`,examples:[`Dr. Magdi Yacoub started a charity to help children with heart problems in Aswan.`,`Sameera Moussa studied nuclear physics at Cairo University.`]}],[{word:`surgeon`,pos:`n.`,ar:`طبيب جراح ماهر`,def:`A special doctor who knows how to look inside the body and perform operations.`,ex:`Sir Magdi Yacoub is a world-famous Egyptian heart surgeon.`,exAr:`السير مجدي يعقوب جراح قلب مصري ذائع الصيت عالمياً.`},{word:`scientist`,pos:`n.`,ar:`عالم باحث في العلوم`,def:`A person who studies or has expert knowledge of natural or physical sciences.`,ex:`Sameera Moussa was a pioneering Egyptian nuclear scientist.`,exAr:`كانت سميرة موسى عالمة ذرة مصرية رائدة.`},{word:`patron`,pos:`n.`,ar:`راعٍ وداعم للمؤسسات الخيرية`,def:`A person who gives financial or other support to a person, organization, or cause.`,ex:`Princess Fatma Ismail was a generous patron of Cairo University.`,exAr:`كانت الأميرة فاطمة إسماعيل راعية وداعمة كريمة لجامعة القاهرة.`},{word:`hero`,pos:`n.`,ar:`بطل وقدوة ملهمة`,def:`A person who is admired for courage, outstanding achievements, or noble qualities.`,ex:`Medical workers and firefighters are true everyday heroes.`,exAr:`الأطباء ورجال الإطفاء هم أبطال حقيقيون في حياتنا اليومية.`},{word:`charity`,pos:`n.`,ar:`مؤسسة وجمعية خيرية`,def:`An organization set up to provide help and raise money for those in need.`,ex:`The Aswan Heart Centre charity treats sick children for free.`,exAr:`يعالج مركز مجدي يعقوب للقلب الخيري بأسوان الأطفال المرضى مجاناً.`},{word:`emergency`,pos:`n.`,ar:`حالة طوارئ حرجة`,def:`A serious, unexpected, and often dangerous situation requiring immediate action.`,ex:`Ambulance paramedics respond rapidly to medical emergencies.`,exAr:`يستجيب مسعفو الإسعاف بسرعة لحالات الطوارئ الطبية.`},{word:`infection`,pos:`n.`,ar:`عدوى مرضية أو التهاب`,def:`A disease in a part of your body caused by bacteria or a virus.`,ex:`Washing hands with soap prevents the spread of eye and chest infections.`,exAr:`غسل اليدين بالصابون يمنع انتشار العدوى والالتهابات.`},{word:`countryside`,pos:`n.`,ar:`الريف والقرى المصرية`,def:`Land and scenery of a rural area outside towns and cities.`,ex:`My grandfather used to live in the quiet green countryside.`,exAr:`اعتاد جدي العيش في الريف الأخضر الهادئ.`},{word:`nuclear`,pos:`adj.`,ar:`نووي وذري (للعلاج السلمي)`,def:`Relating to the nucleus of an atom or atomic energy.`,ex:`Sameera Moussa wanted to use nuclear treatments to cure cancer.`,exAr:`أرادت سميرة موسى استخدام العلاجات الذرية في شفاء مرض السرطان.`},{word:`pump`,pos:`v.`,ar:`يضخ الدم في الجسم`,def:`Force liquid or gas to move in a specified direction.`,ex:`The human heart pumps blood around the body continuously.`,exAr:`يضخ قلب الإنسان الدم في جميع أنحاء الجسم باستمرار.`}],[{phrase:`perform heart surgery`,meaningAr:`يجري عملية جراحية في القلب`,example:`Skilled surgeons perform heart surgery to save children’s lives.`},{phrase:`work for a charity`,meaningAr:`يعمل لصالح مؤسسة خيرية`,example:`Many retired doctors volunteer to work for a charity.`},{phrase:`used to live in the countryside`,meaningAr:`اعتاد العيش في الريف`,example:`Before moving to Cairo, my uncle used to live in the countryside.`}],`Egypt has given the world remarkable heroes in medicine and science! Sir Magdi Yacoub was born in Belbeis in 1935. Because his father was a surgeon, the family used to travel to many places in Egypt. Magdi Yacoub became one of the top heart surgeons in the world. Although he retired in 2001, he did not stop helping people. In 2009, he opened the Aswan Heart Centre charity so that ill Egyptian children who didn’t use to have access to complex surgeries could receive free medical care.`,`Lina: "Who is the Egyptian hero you admire most, Salma?"
Salma: "I admire Dr. Magdi Yacoub! He is a world-famous heart surgeon."
Lina: "Where did he use to work before opening the Aswan Heart Centre?"
Salma: "He used to work at a famous hospital in London, performing life-saving heart transplants."`),o,s,c]}]},{stage:`Preparatory`,grade:9,gradeLabel:`Prep 3 - الصف الثالث الإعدادي (الشهادة الإعدادية)`,gradeLabelAr:`الصف الثالث الإعدادي (الشهادة الإعدادية العامة 2026/2027)`,track:`New Hello`,description:`High-stakes Third Preparatory Certificate: Urban geography, e-commerce & smart consumer rights, Decent Life (حياة كريمة), environmental ecosystems, passive voice, relative clauses, and national exam banks.`,semesters:[{semester:1,semesterLabel:`Term 1 - الفصل الدراسي الأول (Units 1 to 6 - New Hello)`,units:[f(9,`Prep 3`,1,1,`Around Town`,`حول المدينة ومعالم الإسماعيلية والنقل العام`,`Ismailia, Lake Timsah, Suez Canal, botanical gardens, public transport, ferries, monuments`,`Present Simple for Scheduled Transport & Prepositions of Place and Direction`,`المضارع البسيط للمواعيد المجدولة وحروف الجر للمكان والاتجاه`,`Use Present Simple to express official fixed timetables for public transport, cinema screenings, and school terms: "The train leaves at 7:00 PM / The museum opens at 9:00 AM". Prepositions of place: opposite (في الجهة المقابلة), next to (بجوار), between X and Y (بين كذا وكذا), on the corner (على الناصية).`,[{title:`1. Scheduled Timetables in Present Simple (المضارع البسيط للمواعيد والرحلات)`,explanation:`Even if the event happens in the future, if it is on an official schedule or timetable (train, bus, plane, film, lesson), use Present Simple (verb + s/es with singular subjects).`,examples:[`The express train to Aswan leaves platform 4 at 8:15 PM.`,`What time does the botanical museum close this afternoon?`]},{title:`2. Directional Prepositions for Map Navigation (إعطاء الاتجاهات في المحادثة)`,explanation:`Imperatives for directions: "Go straight on", "Take the second turning on the left", "It is on the corner opposite the library".`,examples:[`Go straight on for two hundred meters, then turn left at the traffic lights.`,`The ferry terminal is between the maritime museum and the botanical garden.`]}],[{word:`monuments`,pos:`n.`,ar:`آثار وصروح تاريخية خالدة`,def:`Statues, buildings, or structures built to commemorate a person or event.`,ex:`Ismailia boasts fascinating monuments commemorating the Suez Canal history.`,exAr:`تضم الإسماعيلية معالم وآثاراً تخلد تاريخ قناة السويس.`},{word:`botanical gardens`,pos:`n.`,ar:`الحدائق النباتية العلمية`,def:`Gardens dedicated to the collection, cultivation, and display of plants.`,ex:`The Orman botanical gardens in Giza preserve rare tropical trees.`,exAr:`تحفظ حديقة الأورمان النباتية في الجيزة أشجاراً استوائية نادرة.`},{word:`peaceful`,pos:`adj.`,ar:`هادئ ومسالم ومريح للأعصاب`,def:`Free from disturbance; tranquil and serene.`,ex:`Lake Timsah at sunrise is calm, scenic, and peaceful.`,exAr:`تتميز بحيرة التمساح عند شروق الشمس بالهدوء والجمال والسكينة.`},{word:`ferry`,pos:`n.`,ar:`معدية لنقل الركاب والسيارات`,def:`A boat or ship for conveying passengers and goods across water.`,ex:`We boarded the ferry to cross from Port Said to Port Fouad.`,exAr:`ركبنا المعدية للانتقال بحراً من بورسعيد إلى بورفؤاد.`},{word:`traffic`,pos:`n.`,ar:`حركة المرور والسيارات`,def:`Vehicles moving on a road or public highway.`,ex:`Ismailia is famous for clean air and smooth, light vehicle traffic.`,exAr:`تشتهر الإسماعيلية بنقاء هوائها وحركة المرور الهادئة والسلسة.`},{word:`platform`,pos:`n.`,ar:`رصيف محطة القطار`,def:`A raised level surface on which passengers board a train.`,ex:`The Alexandria express will depart from platform number two.`,exAr:`سيغادر قطار الإسكندرية السريع من رصيف المحطة رقم اثنين.`},{word:`timetable`,pos:`n.`,ar:`جدول مواعيد وسائل النقل`,def:`A schedule of the times at which public transport arrives and departs.`,ex:`Consult the railway timetable to choose the most convenient train.`,exAr:`راجع جدول مواعيد القطارات لاختيار موعد السفر الأنسب لك.`},{word:`passenger`,pos:`n.`,ar:`راكب ومسافر`,def:`A traveler on a public or private conveyance other than the driver.`,ex:`Each passenger must carry a validated train ticket.`,exAr:`يجب على كل راكب حمل تذكرة قطار صالحة ومؤكدة.`},{word:`tram`,pos:`n.`,ar:`الترام الكهربائي التراثي`,def:`An electric passenger vehicle running along rails in the streets.`,ex:`The historic blue tram in Alexandria is an eco-friendly way to travel.`,exAr:`يعد ترام الإسكندرية الأزرق وسيلة تنقل تراثية وصديقة للبيئة.`},{word:`aquarium`,pos:`n.`,ar:`متحف الأحياء المائية والأسماك`,def:`A public building where living aquatic animals and plants are exhibited.`,ex:`We marveled at colorful Red Sea clownfish at the Hurghada aquarium.`,exAr:`انبهرنا بأسماك البحر الأحمر الملونة في متحف الأحياء المائية بالغردقة.`},{word:`exhibition`,pos:`n.`,ar:`معرض فني أو تجاري`,def:`A public display of works of art or items of interest held in an art gallery.`,ex:`The modern art exhibition attracted thousands of visitors.`,exAr:`جذب معرض الفن الحديث آلاف الزوار والمهتمين.`},{word:`indoors`,pos:`adv.`,ar:`في الداخل (داخل المبنى)`,def:`Into or within a building.`,ex:`When the midday temperature soars, it is pleasant to read indoors.`,exAr:`عندما تشتد حرارة الظهيرة، يكون من الرائع القراءة في الداخل.`},{word:`outdoors`,pos:`adv.`,ar:`في الهواء الطلق بالخارج`,def:`In or into the open air; outside a building.`,ex:`Children love playing football outdoors in the fresh breeze.`,exAr:`يحب الأطفال لعب كرة القدم في الهواء الطلق والنسيم العليل.`},{word:`especially`,pos:`adv.`,ar:`بشكل خاص وتحديداً`,def:`Used to single out one person, thing, or circumstance over all others.`,ex:`I enjoy visiting coastal cities, especially Ismailia and Port Said.`,exAr:`أستمتع بزيارة المدن الساحلية، وبخاصة الإسماعيلية وبورسعيد.`},{word:`natural reserve`,pos:`n.`,ar:`محمية طبيعية محمية قانوناً`,def:`A protected area of importance for flora, fauna, or geological features.`,ex:`Ras Mohammed is Egypt’s premier marine natural reserve.`,exAr:`تعد رأس محمد المحمية البحرية الطبيعية الأولى والأهم في مصر.`},{word:`lake`,pos:`n.`,ar:`بحيرة مائية عذبة أو مالحة`,def:`A large body of water surrounded by land.`,ex:`Lake Qarun in Fayoum is an ancient historical body of water.`,exAr:`تعد بحيرة قارون في الفيوم مسطحاً مائياً تاريخياً عريقاً.`},{word:`comfortable`,pos:`adj.`,ar:`مريح ومبهج في الاستخدام`,def:`Providing physical ease and relaxation.`,ex:`First-class train seats are spacious and very comfortable.`,exAr:`مقاعد الدرجة الأولى في القطار واسعة ومريحة للغاية.`},{word:`pollution`,pos:`n.`,ar:`تلوث بيئي ومائي`,def:`The presence in or introduction into the environment of harmful substances.`,ex:`Planting rows of green trees combats urban air pollution.`,exAr:`تساعد زراعة صفوف الأشجار الخضراء في مكافحة تلوث الهواء في المدن.`},{word:`attractive`,pos:`adj.`,ar:`جذاب وجميل المظهر`,def:`Pleasing or appealing to the senses; charming.`,ex:`Ismailia is famous for its attractive colonial architecture and gardens.`,exAr:`تشتهر الإسماعيلية بطرازها المعماري الجذاب وحدائقها البديعة.`},{word:`cross`,pos:`v.`,ar:`يعبر النهر أو الطريق`,def:`Pass from one side of a road or river to the other.`,ex:`Wait for the pedestrian signal before you cross the busy avenue.`,exAr:`انتظر إشارة المشاة الخضراء قبل أن تعبر الشارع المزدحم.`}],[{phrase:`go straight on`,meaningAr:`امشِ في خط مستقيم للأمام`,example:`Go straight on until you see the botanical garden on your right.`},{phrase:`take the second turning`,meaningAr:`اتجه مع المنعطف الثاني`,example:`Take the second turning on your left past the post office.`},{phrase:`on the corner of the street`,meaningAr:`على ناصية الشارع تماماً`,example:`The bookshop is right on the corner of Tahrir Street.`},{phrase:`catch the ferry`,meaningAr:`يلحق بالمعدية للعبور`,example:`We must hurry to catch the nine o’clock ferry to Port Fouad.`},{phrase:`a peaceful natural haven`,meaningAr:`ملاذ طبيعي هادئ ومريح`,example:`Ismailia’s lakes offer a peaceful natural haven away from big-city noise.`}],`Ismailia is one of the most beautiful and peaceful cities in Egypt! Located on the west bank of the Suez Canal, it was founded in 1869. The city features wide, tree-lined boulevards, elegant historic monuments, and vast botanical gardens. Nearby lies Lake Timsah, where waters are tranquil and serene. Traveling around Ismailia is enjoyable because there is very little traffic pollution. To cross the canal, passengers board clean electric ferries. The railway station is situated near the city center: the train to Cairo departs every hour on the hour.`,`Tourist: "Excuse me, how can I get to the Natural History Museum from here?"
Local Resident: "Go straight on along this boulevard for two hundred meters. Take the first turning on your right. The museum is on the corner, opposite the botanical gardens."
Tourist: "Thank you so much! What time does the museum close today?"
Local Resident: "It closes at four o’clock in the afternoon."`),f(9,`Prep 3`,1,2,`Let’s Go Shopping!`,`هيا نتسوق عبر الإنترنت وخدمة العملاء`,`Online shopping, smart appliances (microwave, kettle, speakers), discounts, delivery, customer complaints`,`Correlative Conjunctions: "Both... and / Either... or / Neither... nor / None of"`,`روابط الجمع والاختيار والنفي المزدوج (Both / Either / Neither / None)`,`Both... and takes a PLURAL verb ("Both the kettle and the microwave are on sale"). Neither... nor matches the verb to the CLOSER subject ("Neither the manager nor the assistants were available"). Either... or presents two alternatives. None of is used for three or more items ("None of the laptops were damaged").`,[{title:`1. Correlative Conjunctions Masterclass (روابط الاختيار والجمع)`,explanation:`Both X and Y -> ALWAYS PLURAL VERB. Neither X nor Y -> Verb agrees with Y (the closer noun). Either X or Y -> Verb agrees with Y. None of + plural noun -> usually takes plural or singular verb.`,examples:[`Both the smartphone and the tablet are on special discount today.`,`Neither the seller nor the customers were happy with the broken delivery.`]},{title:`2. Formal Customer Service Complaints (حل محادثات الشكاوى وخدمة العملاء)`,explanation:`Polite complaint openings: "I am calling to make a complaint about...", "The item arrived damaged / didn’t work". Customer service replies: "I am terribly sorry about that. Could you give me your order number? We can replace it or refund your money."`,examples:[`Customer: "I want to make a complaint. The kettle I ordered makes a strange noise."`,`Assistant: "We apologize for the inconvenience. We will send you a replacement immediately."`]}],[{word:`discount`,pos:`n.`,ar:`خصم وتخفيض في السعر`,def:`A deduction from the usual cost of something.`,ex:`The electronics store offers a twenty percent discount on smart TVs.`,exAr:`يقدم متجر الإلكترونيات خصماً بنسبة عشرين بالمائة على الشاشات الذكية.`},{word:`complaint`,pos:`n.`,ar:`شكوى رسمية من عيب أو خدمة`,def:`A statement that something is unsatisfactory or unacceptable.`,ex:`The customer filed a formal complaint regarding delayed package delivery.`,exAr:`قدم العميل شكوى رسمية بخصوص تأخر وصول الطرد البريدي.`},{word:`microwave`,pos:`n.`,ar:`فرن الميكروويف لتسخين الطعام`,def:`An electric oven that uses electromagnetic waves to heat food quickly.`,ex:`Warm your soup in the microwave for two minutes.`,exAr:`سخن حساءك في الميكروويف لمدة دقيقتين.`},{word:`kettle`,pos:`n.`,ar:`غلاية مياه كهربائية`,def:`A vessel for boiling water, typically having a lid, spout, and handle.`,ex:`Boil water in the electric kettle to make hot mint tea.`,exAr:`اغلِ الماء في الغلاية الكهربائية لإعداد شاي النعناع الساخن.`},{word:`smart speaker`,pos:`n.`,ar:`مكبر صوت ذكي بالبلوتوث`,def:`A wireless speaker controlled with spoken voice commands.`,ex:`I use our smart speaker to play the morning Quran recitation.`,exAr:`أستخدم مكبر الصوت الذكي لتشغيل تلاوة القرآن الصباحية.`},{word:`delivery`,pos:`n.`,ar:`خدمة التوصيل والشحن للمنزل`,def:`The action of delivering letters, parcels, or ordered goods.`,ex:`Free home delivery is provided for orders over five hundred pounds.`,exAr:`تتوفر خدمة التوصيل المنزلي مجاناً للطلبات التي تتجاوز خمسمائة جنيه.`},{word:`order`,pos:`n. / v.`,ar:`طلب شراء / يطلب سلعة`,def:`A request to make, supply, or deliver goods.`,ex:`I placed an online order for a pair of running sneakers.`,exAr:`قمت بطلب شراء حذاء رياضي للجري عبر الإنترنت.`},{word:`special offer`,pos:`n.`,ar:`عرض ترويجي وتخفيض خاص`,def:`A temporary reduction in the price of products.`,ex:`Black Friday features special offers across all electronics departments.`,exAr:`تشهد عروض الجمعة تخفيضات خاصة عبر جميع أقسام الإلكترونيات.`},{word:`deal`,pos:`n.`,ar:`صفقة تجارية رابحة`,def:`An attractive arrangement or bargain in purchasing.`,ex:`Buying two laptops for the price of one was an unbeatable deal.`,exAr:`كان شراء جهازي حاسوب بسعر جهاز واحد صفقة لا تعوض.`},{word:`customer`,pos:`n.`,ar:`عميل وزبون المتجر`,def:`A person who buys goods or services from a shop or business.`,ex:`The polite shopkeeper greeted every customer with genuine warmth.`,exAr:`رحب صاحب المتجر اللبق بكل عميل بترحاب ومودة صادقة.`},{word:`review`,pos:`n. / v.`,ar:`تقييم ومراجعة للمنتج`,def:`A critical appraisal of a book, play, or commercial product.`,ex:`Always read customer reviews before ordering electronics online.`,exAr:`اقرأ دائماً تقييمات المشترين قبل طلب الأجهزة الإلكترونية عبر الإنترنت.`},{word:`charger`,pos:`n.`,ar:`شاحن بطارية الهاتف`,def:`A device for charging a storage battery such as a mobile phone.`,ex:`Do not leave your mobile phone charger plugged in all night.`,exAr:`لا تترك شاحن هاتفك المحمول موصولاً بالكهرباء طوال الليل.`},{word:`item`,pos:`n.`,ar:`سلعة أو منتج معروض`,def:`An individual article or unit in a collection or catalog.`,ex:`The courier delivered three items from my online shopping cart.`,exAr:`سلم مندوب الشحن ثلاث سلع من سلة تسوقي عبر الإنترنت.`},{word:`seller`,pos:`n.`,ar:`البائع في المتجر أو المتجر الرقمي`,def:`A person who sells goods or services.`,ex:`Choose an authorized online seller with certified consumer ratings.`,exAr:`اختر بائعاً رقمياً معتمداً ذا تقييمات مستهلكين موثوقة.`},{word:`refund`,pos:`n. / v.`,ar:`استرداد الأموال واسترجاع القيمة`,def:`A repayment of a sum of money to a dissatisfied customer.`,ex:`The store refunded my money when the kettle arrived with a defect.`,exAr:`استرد المتجر نقودي عندما وصلت الغلاية وبها عيب صناعي.`},{word:`exchange`,pos:`v.`,ar:`يستبدل سلعة بأخرى سليمة`,def:`Give something and receive something of the same kind in return.`,ex:`You can exchange this jacket for a larger size within fourteen days.`,exAr:`يمكنك استبدال هذه السترة بمقاس أكبر خلال أربعة عشر يوماً.`},{word:`quality`,pos:`n.`,ar:`جودة وخامة التصنيع`,def:`The standard of something as measured against other things of a similar kind.`,ex:`Egyptian cotton garments are renowned worldwide for superior quality.`,exAr:`تشتهر الملابس المصنوعة من القطن المصري عالمياً بجودتها الفائقة.`},{word:`online`,pos:`adj. / adv.`,ar:`عبر شبكة الإنترنت`,def:`Controlled by or connected to a global computer network.`,ex:`Online shopping saves time, but consumers must compare prices carefully.`,exAr:`يوفر التسوق عبر الإنترنت الوقت، لكن على المستهلكين مقارنة الأسعار بحرص.`},{word:`advert`,pos:`n.`,ar:`إعلان تجاري ترويجي`,def:`An advertisement marketing a product to consumers.`,ex:`The television advert highlighted a fifty percent discount on kitchenware.`,exAr:`أبرز الإعلان التلفزيوني خصماً قدره خمسون بالمائة على أواني المطبخ.`},{word:`guarantee`,pos:`n. / v.`,ar:`شهادة ضمان الجودة ضد العيوب`,def:`A formal promise or assurance that certain conditions will be fulfilled.`,ex:`This refrigerator comes with a ten-year manufacturer guarantee.`,exAr:`تأتي هذه الثلاجة مع شهادة ضمان من المصنع لمدة عشر سنوات.`}],[{phrase:`make a formal complaint`,meaningAr:`يقدم شكوى رسمية`,example:`I had to make a formal complaint because the microwave did not heat.`},{phrase:`both... and are on sale`,meaningAr:`كلاهما معروضان للبيع بتخفيض`,example:`Both the kettle and the blender are on sale this weekend.`},{phrase:`get a full refund`,meaningAr:`يسترد كامل المبلغ المدفوع`,example:`The customer was able to get a full refund for the damaged product.`},{phrase:`exchange for a new one`,meaningAr:`يستبدل المنتج بآخر جديد سليم`,example:`The company agreed to exchange the broken phone for a new one.`},{phrase:`check customer reviews`,meaningAr:`يفحص آراء وتقييمات المشترين`,example:`Savvy shoppers always check customer reviews before purchasing.`}],`E-commerce has transformed consumer habits across Egypt! Millions of families purchase household appliances and books through verified digital platforms. However, smart shopping requires digital literacy. Always check seller warranties, customer reviews, and return policies. Last week, Tarek ordered a new electric kettle for his grandmother’s birthday. When the parcel arrived, the kettle was scratched and failed to boil water. Tarek called customer service politely: "I would like to make a complaint. The kettle I ordered yesterday arrived defective." The representative apologized immediately: "We will dispatch a courier tomorrow to replace the item free of charge."`,`Customer: "Good afternoon. I am calling to make a complaint about my online order."
Agent: "Good afternoon, sir. I apologize for the trouble. What seems to be the problem?"
Customer: "I ordered a smart speaker, but when I unboxed it, the charger was missing."
Agent: "Could I have your order number, please? We will send you a replacement charger within 24 hours."`),f(9,`Prep 3`,1,3,`My Community & Decent Life`,`مجتمعي ومبادرة حياة كريمة في القرى`,`Decent Life initiative (حياة كريمة), rural hospitals, paved roads, sports facilities, community empowerment`,`Present Continuous for Future Arrangements & -ed vs. -ing Adjectives`,`المضارع المستمر للترتيبات المستقبلية والصفات المنتهية بـ ed و ing`,`Use Present Continuous (am/is/are + v-ing) for fixed future arrangements where time and place are already booked ("We are meeting the engineers tomorrow morning at 10:00"). Adjectives ending in "-ed" describe feelings of a person ("I am excited / amazed"). Adjectives ending in "-ing" describe the thing or person that causes the feeling ("The Decent Life project is exciting / amazing").`,[{title:`1. Present Continuous for Fixed Future Arrangements (الترتيبات المستقبلية)`,explanation:`When plans are already organized, tickets booked, or appointments scheduled, use Present Continuous. Look for clues: arranged, prepared, booked, bought tickets.`,examples:[`Our class is visiting the new rural medical center in Fayoum next Monday.`,`The municipal engineers are inspecting the paved roads tomorrow morning.`]},{title:`2. -ed vs. -ing Adjectives (الصفات المنتهية بـ ed و ing)`,explanation:`-ed describes how a person feels: "The villagers were amazed by the clean water project." -ing describes the cause or quality of the object: "The Decent Life initiative is an amazing project."`,examples:[`The students were interested in learning about community volunteering.`,`Reading about Egyptian historical heroes is truly interesting and inspiring.`]}],[{word:`facilities`,pos:`n.`,ar:`مرافق وخدمات مجتمعية عامة`,def:`Space or equipment provided for a particular purpose.`,ex:`Decent Life has built state-of-the-art sports facilities for rural youth.`,exAr:`أنشأت مبادرة حياة كريمة مرافق رياضية حديثة لشباب القرى.`},{word:`pavement`,pos:`n.`,ar:`رصيف مشاة ممهد وآمن`,def:`A paved path for pedestrians at the side of a road.`,ex:`The municipal project laid smooth stone pavements for elderly pedestrians.`,exAr:`قام المشروع بتمهيد أرصفة حجرية ملساء للمشاة وكبار السن.`},{word:`initiative`,pos:`n.`,ar:`مبادرة قومية رائدة`,def:`An act or strategy intended to resolve a difficulty or improve a situation.`,ex:`The Presidential Decent Life initiative transforms Egyptian rural hamlets.`,exAr:`تحدث مبادرة حياة كريمة الرئاسية تحولاً جذرياً في القرى المصرية.`},{word:`community`,pos:`n.`,ar:`المجتمع والبيئة المحلية`,def:`A group of people living in the same place or having a particular characteristic.`,ex:`Our local community organized a tree-planting day to beautify the park.`,exAr:`نظم مجتمعنا المحلي يوماً لزراعة الأشجار لتجميل الحديقة.`},{word:`rural`,pos:`adj.`,ar:`ريفي وقروي`,def:`In, relating to, or characteristic of the countryside rather than the town.`,ex:`Rural villages now enjoy potable running water and high-speed fiber internet.`,exAr:`تتمتع القرى الريفية الآن بمياه شرب نقية وإنترنت فائق السرعة بالألياف الضوئية.`},{word:`disabled`,pos:`adj.`,ar:`من ذوي الإعاقة والهمم`,def:`Having a physical or mental condition that limits movements or activities.`,ex:`The new health clinics provide accessible ramps for disabled citizens.`,exAr:`توفر المراكز الصحية الجديدة منحدرات ميسرة للمواطنين من ذوي الهمم.`},{word:`opportunity`,pos:`n.`,ar:`فرصة ثمينة للنجاح والعمل`,def:`A set of circumstances that makes it possible to do something.`,ex:`Vocational workshops offer rural women an opportunity to start businesses.`,exAr:`توفر الورش المهنية لسيدات الريف فرصة حقيقية لبدء مشاريعهن الخاصة.`},{word:`improve`,pos:`v.`,ar:`يحسن ويطور الخدمات`,def:`Make or become better in condition, quality, or standard.`,ex:`Paved asphalt roads dramatically improve transportation between villages.`,exAr:`تسهم الطرق المسفلتة الممهدة في تحسين الانتقال بين القرى بشكل كبير.`},{word:`healthcare`,pos:`n.`,ar:`الرعاية والخدمات الطبية`,def:`The organized provision of medical care to individuals or a community.`,ex:`Decent Life hospitals deliver comprehensive healthcare to underserved areas.`,exAr:`تقدم مستشفيات حياة كريمة رعاية صحية شاملة للمناطق الأكثر احتياجاً.`},{word:`elderly`,pos:`adj. / n.`,ar:`كبار السن والمسنون`,def:`Of persons: advanced in years; old.`,ex:`Dedicated volunteers deliver monthly medical supplies to elderly villagers.`,exAr:`يوصل المتطوعون المخلصون المستلزمات الطبية الشهرية للمسنين في القرى.`},{word:`education`,pos:`n.`,ar:`التعليم والتثقيف`,def:`The process of receiving or giving systematic instruction.`,ex:`Quality education empowers children to build prosperous, innovative futures.`,exAr:`يمكّن التعليم عالي الجودة الأطفال من بناء مستقبل مزدهر ومبتكر.`},{word:`neighborhood`,pos:`n.`,ar:`الحي السكني والمجاورة`,def:`A district, especially one forming a community within a town or city.`,ex:`Our quiet neighborhood collaborated to establish a youth reading room.`,exAr:`تعاون حيّنا السكني الهادئ لإنشاء قاعة قراءة للشباب.`},{word:`volunteer`,pos:`n. / v.`,ar:`متطوع للخدمة العامة`,def:`A person who freely offers to take part in an enterprise or undertake a task.`,ex:`College students volunteer to paint classroom walls and plant gardens.`,exAr:`يتطوع طلاب الجامعات لطلاء جدران الفصول وزراعة الحدائق المدرسية.`},{word:`deliver`,pos:`v.`,ar:`يقدم ويوصل الخدمات`,def:`Bring and hand over a letter, parcel, or service.`,ex:`Mobile medical convoys deliver free treatments directly to remote hamlets.`,exAr:`تقدم القوافل الطبية المتنقلة العلاج المجاني مباشرة للقرى والنجوع النائية.`},{word:`leisure`,pos:`n.`,ar:`وقت الفراغ والراحة`,def:`Use of free time for enjoyment and relaxation.`,ex:`The newly inaugurated youth center offers diverse leisure activities.`,exAr:`يقدم مركز الشباب الذي تم افتتاحه حديثاً أنشطة ترفيهية ورياضية متنوعة.`},{word:`project`,pos:`n.`,ar:`مشروع تنموي قومي`,def:`An enterprise carefully planned to achieve a particular socio-economic aim.`,ex:`The sanitation infrastructure project protects villages from canal flooding.`,exAr:`يحمي مشروع البنية التحتية للصرف الصحي القرى من مشكلات المياه.`},{word:`amazing`,pos:`adj.`,ar:`مذهل ورائع الإنجاز`,def:`Causing great surprise or wonder; astonishing.`,ex:`The rapid modernization of Upper Egyptian hamlets is truly amazing.`,exAr:`إن التطوير الشامل السريع لقرى صعيد مصر مذهل ومصدر فخر حقيقي.`},{word:`amazed`,pos:`adj.`,ar:`مندهش ومبهور بالإنجاز`,def:`Filled with astonishment; greatly surprised.`,ex:`The visitors were amazed by the solar-powered street lighting.`,exAr:`انبهر الزوار بأعمدة إنارة الشوارع التي تعمل بالطاقة الشمسية بالكامل.`},{word:`inspiring`,pos:`adj.`,ar:`ملهم ومحفز للهمم`,def:`Having the effect of inspiring someone; motivating.`,ex:`Watching young Egyptian engineers renovate villages is deeply inspiring.`,exAr:`إن مشاهدة المهندسين المصريين الشباب يطورون القرى أمر ملهم للغاية.`},{word:`inspired`,pos:`adj.`,ar:`مستلهم ومفعم بالحماس`,def:`Of extraordinary quality, as if arising from external creative impulse.`,ex:`Students felt inspired to launch their own neighborhood clean-up campaign.`,exAr:`شعر الطلاب بالحماس والاستلهام لإطلاق حملة نظافة خاصة بحيهم.`}],[{phrase:`Decent Life initiative`,meaningAr:`مبادرة حياة كريمة الرئاسية`,example:`The Decent Life initiative brings hope, clean water, and schools to Egyptian villages.`},{phrase:`equal opportunities for all`,meaningAr:`فرص متكافئة وعادلة للجميع`,example:`Modern development ensures equal opportunities for all children.`},{phrase:`paved roads and clinics`,meaningAr:`طرق ممهدة ومراكز طبية`,example:`Paved roads and modern clinics connect once-isolated hamlets.`},{phrase:`arranged to visit tomorrow`,meaningAr:`مرتب ومنسق للزيارة غداً`,example:`Our scouts troop is arranged to visit the community center tomorrow.`},{phrase:`amazed by the progress`,meaningAr:`مبهور بالتقدم والتطور الملحوظ`,example:`Everyone is amazed by the rapid progress in rural public infrastructure.`}],`The "Decent Life" (Haya Karima) initiative is an inspiring national endeavor transforming the Egyptian countryside! Launched by the Egyptian government, it targets over 4,500 rural villages across governorates like Minya, Asyut, Sohag, and Beheira. Before the initiative, many rural communities suffered from unpaved roads and inadequate medical clinics. Today, state-of-the-art schools, solar-illuminated streets, modern sanitation networks, and digital post offices are established. Young Egyptian engineers and university volunteers are working hand-in-hand to build a brighter future for generations to come.`,`Omar: "Have you read about the Decent Life projects in Upper Egypt, Karim?"
Karim: "Yes! The transformations in health clinics and schools are truly amazing."
Omar: "Our scout group is traveling to Sohag next month to help paint the new primary school!"
Karim: "That is fantastic! Count me in as a volunteer."`),l,u,d]}]}];export{e as n,p as t};